const STORAGE_KEY = "itinerary:stops";

function readStops() {
  const stops = getItem(STORAGE_KEY);

  if (!Array.isArray(stops)) {
    return [];
  }

  return stops;
}

function writeStops(stops) {
  setItem(STORAGE_KEY, stops);
  return stops;
}

function makeStop(stop) {
  return {
    id: crypto.randomUUID(),
    name: stop.name,
    startDate: stop.startDate,
    endDate: stop.endDate,
    description: stop.description,
  };
}

function normalizeIndex(index, length) {
  if (!Number.isInteger(index)) {
    return length;
  }

  if (index < 0) {
    return 0;
  }

  if (index > length) {
    return length;
  }

  return index;
}

export function listStops() {
  return readStops();
}

export function createStop(stop) {
  const nextStops = [...readStops(), makeStop(stop)];
  writeStops(nextStops);
  return nextStops[nextStops.length - 1];
}

export function updateStop(id, changes) {
  const nextStops = readStops().map((stop) =>
    stop.id === id
      ? {
          id: stop.id,
          name: changes.name ?? stop.name,
          startDate: changes.startDate ?? stop.startDate,
          endDate: changes.endDate ?? stop.endDate,
          description: changes.description ?? stop.description,
        }
      : stop,
  );

