+import assert from "node:assert/strict";
+import { webcrypto } from "node:crypto";
+import test from "node:test";
+
+import {
+  createStop,
+  listStops,
+  removeStop,
+  reorderStops,
+  updateStop,
+} from "./stops.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("creates, edits, deletes, and reorders stops while preserving all fields", () => {
+  globalThis.localStorage = createLocalStorage();
+  globalThis.crypto = webcrypto;
+
+  const first = createStop({
+    name: "Buenos Aires",
+    startDate: "2026-09-01",
+    endDate: "2026-09-02",
+    description: "Inicio del viaje",
+  });
+  const second = createStop({
+    name: "Córdoba",
+    startDate: "2026-09-03",
+    endDate: "2026-09-04",
+    description: "Parada intermedia",
+  });
+  const third = createStop({
+    name: "Mendoza",
+    startDate: "2026-09-05",
+    endDate: "2026-09-07",
+    description: "Destino final",
+  });
+
+  assert.deepEqual(listStops(), [first, second, third]);
+
+  const updatedSecond = updateStop(second.id, {
+    name: "Villa Carlos Paz",
+    startDate: "2026-09-03",
+    endDate: "2026-09-05",
+    description: "Cambio de parada",
+  });
+
+  assert.deepEqual(updatedSecond, {
+    id: second.id,
+    name: "Villa Carlos Paz",
+    startDate: "2026-09-03",
+    endDate: "2026-09-05",
+    description: "Cambio de parada",
+  });
+
+  assert.deepEqual(listStops(), [first, updatedSecond, third]);
+
+  const removedFirst = removeStop(first.id);
+
+  assert.deepEqual(removedFirst, first);
+  assert.deepEqual(listStops(), [updatedSecond, third]);
+
+  const movedThird = reorderStops(third.id, 0);
+
+  assert.deepEqual(movedThird, third);
+  assert.deepEqual(listStops(), [third, updatedSecond]);
+});
+
+test("reorderStops clamps indexes and returns null for missing stops", () => {
+  globalThis.localStorage = createLocalStorage();
+  globalThis.crypto = webcrypto;
+
+  const one = createStop({
+    name: "A",
+    startDate: "2026-08-01",
+    endDate: "2026-08-02",
+    description: "Uno",
+  });
+  const two = createStop({
+    name: "B",
+    startDate: "2026-08-03",
+    endDate: "2026-08-04",
+    description: "Dos",
+  });
+
+  assert.equal(reorderStops("missing", 0), null);
+  assert.deepEqual(listStops(), [one, two]);
+
+  assert.deepEqual(reorderStops(one.id, 10), one);
+  assert.deepEqual(listStops(), [two, one]);
+
+  assert.deepEqual(reorderStops(one.id, -3), one);
+  assert.deepEqual(listStops(), [one, two]);
+});

