+
+  assert.equal(items.length, 1);
+  assert.equal(items[0].name, "Passport");
+  assert.equal(items[0].completed, false);
+  assert.equal(getPackingProgress().completed, 0);
+  assert.equal(getPackingProgress().total, 1);
