@@ -0,0 +1,96 @@
+import { getItem, setItem } from "../../storage/store.mjs";
+
+const STORAGE_KEY = "itinerary:stops";
+
+function readStops() {
+  const stops = getItem(STORAGE_KEY);
+
+  if (!Array.isArray(stops)) {
+    return [];
+  }
+
+  return stops;
+}
+
+function writeStops(stops) {
+  setItem(STORAGE_KEY, stops);
+  return stops;
+}
+
+function makeStop(stop) {
+  return {
+    id: crypto.randomUUID(),
+    name: stop.name,
+    startDate: stop.startDate,
+    endDate: stop.endDate,
+    description: stop.description,
+  };
+}
+
+function normalizeIndex(index, length) {
+  if (!Number.isInteger(index)) {
+    return length;
+  }
+
+  if (index < 0) {
+    return 0;
+  }
+
+  if (index > length) {
+    return length;
+  }
+
+  return index;
+}
+
+export function listStops() {
+  return readStops();
+}
+
+export function createStop(stop) {
+  const nextStops = [...readStops(), makeStop(stop)];
+  writeStops(nextStops);
+  return nextStops[nextStops.length - 1];
+}
+
+export function updateStop(id, changes) {
+  const nextStops = readStops().map((stop) =>
+    stop.id === id
+      ? {
+          id: stop.id,
+          name: changes.name ?? stop.name,
+          startDate: changes.startDate ?? stop.startDate,
+          endDate: changes.endDate ?? stop.endDate,
+          description: changes.description ?? stop.description,
+        }
+      : stop,
+  );
+
+  writeStops(nextStops);
+  return nextStops.find((stop) => stop.id === id) ?? null;
+}
+
+export function removeStop(id) {
+  const currentStops = readStops();
+  const nextStops = currentStops.filter((stop) => stop.id !== id);
+
+  writeStops(nextStops);
+  return currentStops.find((stop) => stop.id === id) ?? null;
+}
+
+export function reorderStops(id, index) {
+  const currentStops = readStops();
+  const fromIndex = currentStops.findIndex((stop) => stop.id === id);
+
+  if (fromIndex === -1) {
+    return null;
+  }
+
+  const nextStops = [...currentStops];
+  const [stop] = nextStops.splice(fromIndex, 1);
+  const targetIndex = normalizeIndex(index, nextStops.length);
+
+  nextStops.splice(targetIndex, 0, stop);
+  writeStops(nextStops);
+  return stop;
+}
