+import { getItem, setItem } from "../../storage/store.mjs";
+
+const STORAGE_KEY = "itinerary:stops";
+const STOP_FIELDS = ["id", "name", "startDate", "endDate", "description"];
+
+function readStops() {
+  const stops = getItem(STORAGE_KEY);
+
+  return Array.isArray(stops) ? stops : [];
+}
+
+function writeStops(stops) {
+  setItem(STORAGE_KEY, stops);
+  return stops;
+}
+
+function createId() {
+  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === "function") {
+    return globalThis.crypto.randomUUID();
+  }
+
+  return `stop-${Date.now()}-${Math.random().toString(16).slice(2)}`;
+}
+
+function pickStopFields(stop) {
+  const result = {};
+
+  for (const field of STOP_FIELDS) {
+    if (field === "id") {
+      continue;
+    }
+
+    if (stop && Object.hasOwn(stop, field)) {
+      result[field] = stop[field];
+    }
+  }
+
+  return result;
+}
+
+function cloneStop(stop) {
+  return {
+    id: stop.id,
+    name: stop.name,
+    startDate: stop.startDate,
+    endDate: stop.endDate,
+    description: stop.description,
+  };
+}
+
+function clampIndex(index, length) {
+  if (!Number.isInteger(index)) {
+    return length;
+  }
+
+  if (index < 0) {
+    return 0;
+  }
+
+  if (index > length) {
+    return length;
+  }
+
+  return index;
+}
+
+export function listStops() {
+  return readStops().map(cloneStop);
+}
+
+export function createStop(stop) {
+  const nextStop = {
+    id: createId(),
+    name: stop?.name ?? "",
+    startDate: stop?.startDate ?? "",
+    endDate: stop?.endDate ?? "",
+    description: stop?.description ?? "",
+  };
+  const stops = [...readStops(), nextStop];
+
+  writeStops(stops);
+
+  return listStops();
+}
+
+export function updateStop(id, stop) {
+  const stops = readStops();
+  const nextStops = stops.map((currentStop) => {
+    if (currentStop.id !== id) {
+      return currentStop;
+    }
+
+    return {
+      ...currentStop,
+      ...pickStopFields(stop),
+    };
+  });
+
+  writeStops(nextStops);
+
+  return listStops();
+}
+
+export function removeStop(id) {
+  const nextStops = readStops().filter((stop) => stop.id !== id);
+
+  writeStops(nextStops);
+
+  return listStops();
+}
+
+export function reorderStops(id, index) {
+  const stops = readStops();
+  const currentIndex = stops.findIndex((stop) => stop.id === id);
+
+  if (currentIndex < 0) {
+    return listStops();
+  }
+
+  const nextStops = [...stops];
+  const [stop] = nextStops.splice(currentIndex, 1);
+  const nextIndex = clampIndex(index, nextStops.length);
+
+  nextStops.splice(nextIndex, 0, stop);
+  writeStops(nextStops);
+
+  return listStops();
+}

