diff --git a/src/itinerary/stops/stops.test.mjs b/src/itinerary/stops/stops.test.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..ba2d5aa27eb1a82bdc5b7349ef359553cb1c516f
--- /dev/null
+++ b/src/itinerary/stops/stops.test.mjs
@@ -0,0 +1,123 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import {
+  createStop,
+  listStops,
+  removeStop,
+  reorderStops,
+  updateStop,
+} from "./stops.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("creates, edits, removes, and reorders stops while preserving fields", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const afterFirstCreate = createStop({
+    name: "Buenos Aires",
+    startDate: "2026-09-01",
+    endDate: "2026-09-03",
+    description: "Primer tramo",
+  });
+
+  assert.equal(afterFirstCreate.length, 1);
+  assert.deepEqual(afterFirstCreate[0], {
+    id: afterFirstCreate[0].id,
+    name: "Buenos Aires",
+    startDate: "2026-09-01",
+    endDate: "2026-09-03",
+    description: "Primer tramo",
+  });
+
+  const afterSecondCreate = createStop({
+    name: "Mendoza",
+    startDate: "2026-09-03",
+    endDate: "2026-09-06",
+    description: "Viñedos y montaña",
+  });
+
+  assert.equal(afterSecondCreate.length, 2);
+  assert.deepEqual(listStops(), afterSecondCreate);
+
+  const updatedStops = updateStop(afterSecondCreate[0].id, {
+    name: "Buenos Aires Centro",
+    startDate: "2026-09-02",
+    endDate: "2026-09-04",
+    description: "Primer tramo actualizado",
+  });
+
+  assert.deepEqual(updatedStops[0], {
+    id: afterSecondCreate[0].id,
+    name: "Buenos Aires Centro",
+    startDate: "2026-09-02",
+    endDate: "2026-09-04",
+    description: "Primer tramo actualizado",
+  });
+  assert.deepEqual(updatedStops[1], afterSecondCreate[1]);
+
+  const reorderedStops = reorderStops(afterSecondCreate[1].id, 0);
+
+  assert.equal(reorderedStops[0].id, afterSecondCreate[1].id);
+  assert.equal(reorderedStops[1].id, afterSecondCreate[0].id);
+  assert.deepEqual(reorderedStops[0], {
+    id: afterSecondCreate[1].id,
+    name: "Mendoza",
+    startDate: "2026-09-03",
+    endDate: "2026-09-06",
+    description: "Viñedos y montaña",
+  });
+
+  const afterRemove = removeStop(afterSecondCreate[0].id);
+
+  assert.equal(afterRemove.length, 1);
+  assert.deepEqual(afterRemove[0], reorderedStops[0]);
+});
+
+test("reorderStops clamps indexes and ignores unknown ids", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const first = createStop({
+    name: "Rosario",
+    startDate: "2026-10-01",
+    endDate: "2026-10-02",
+    description: "Inicio",
+  });
+  const second = createStop({
+    name: "Córdoba",
+    startDate: "2026-10-02",
+    endDate: "2026-10-04",
+    description: "Centro",
+  });
+
+  const movedToEnd = reorderStops(first[0].id, 999);
+
+  assert.equal(movedToEnd[0].id, second[0].id);
+  assert.equal(movedToEnd[1].id, first[0].id);
+  assert.deepEqual(reorderStops("missing", 0), movedToEnd);
+  assert.deepEqual(listStops(), movedToEnd);
+});

