+    id: created.id,
+    name: "Mendoza",
+    startDate: "2026-03-01",
+    endDate: "2026-03-04",
+    description: "Bodega y montaña",
+  });
+  assert.deepEqual(listStops(), [created]);
+});
+
+test("updateStop edits a stop without losing its fields", () => {
+  useLocalStorage();
+
+  const created = createStop({
