+    name: "CABA",
+    description: "Museos y caminatas",
+  });
+
+  assert.deepEqual(updated, {
+    id: created.id,
+    name: "CABA",
+    startDate: "2026-03-10",
+    endDate: "2026-03-12",
+    description: "Museos y caminatas",
+  });
