+  globalThis.localStorage = createLocalStorage();
+
+  createStop({
+    name: "Salta",
+    startDate: "2026-11-01",
+    endDate: "2026-11-02",
+    description: "Ingreso al noroeste",
+  });
+
+  assert.throws(() => {
+    createActivity({
+      stopId: "missing-stop",
+      day: "2026-11-01",
+      time: "07:00",
+    });
+  }, /missing stop/i);
+});

