diff --git a/src/dashboard/summary.mjs b/src/dashboard/summary.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..b8fb0d98c64d68b47e0a72fb8ab3f82ed8be0453
--- /dev/null
+++ b/src/dashboard/summary.mjs
@@ -0,0 +1,278 @@
+import { listActivities } from "../itinerary/agenda/agenda.mjs";
+import { getBudgetSummary } from "../organization/budget/budget.mjs";
+import { listFavorites } from "../memories/favorites/favorites.mjs";
+import { listNotes } from "../memories/notes/notes.mjs";
+import { getPackingProgress } from "../organization/packing/packing.mjs";
+import { listStops } from "../itinerary/stops/stops.mjs";
+
+const TRIP_NAME = "Viaje en Familia";
+const MAX_NEXT_EVENTS = 4;
+const MAX_HIGHLIGHTS = 4;
+
+function parseDateOnly(value) {
+  if (typeof value !== "string") {
+    return null;
+  }
+
+  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
+
+  if (!match) {
+    return null;
+  }
+
+  const year = Number(match[1]);
+  const month = Number(match[2]);
+  const day = Number(match[3]);
+
+  if (
+    !Number.isInteger(year) ||
+    !Number.isInteger(month) ||
+    !Number.isInteger(day) ||
+    month < 1 ||
+    month > 12 ||
+    day < 1 ||
+    day > 31
+  ) {
+    return null;
+  }
+
+  return Date.UTC(year, month - 1, day);
+}
+
+function compareDayValues(left, right) {
+  const leftIsNumber = typeof left === "number" || /^\d+$/.test(String(left));
+  const rightIsNumber = typeof right === "number" || /^\d+$/.test(String(right));
+
+  if (leftIsNumber && rightIsNumber) {
+    return Number(left) - Number(right);
+  }
+
+  return String(left ?? "").localeCompare(String(right ?? ""));
+}
+
+function clampRatio(value) {
+  if (!Number.isFinite(value) || value < 0) {
+    return 0;
+  }
+
+  return value > 1 ? 1 : value;
+}
+
+function buildStopLookup(stops) {
+  return new Map(stops.map((stop, index) => [stop.id, { stop, index }]));
+}
+
+function buildTrip(stops) {
+  let startDate = null;
+  let endDate = null;
+  let stopCount = 0;
+
+  for (const stop of stops) {
+    stopCount += 1;
+
+    const stopStart = parseDateOnly(stop.startDate);
+    const stopEnd = parseDateOnly(stop.endDate);
+
+    if (stopStart !== null && (startDate === null || stopStart < startDate)) {
+      startDate = stopStart;
+    }
+
+    if (stopEnd !== null && (endDate === null || stopEnd > endDate)) {
+      endDate = stopEnd;
+    }
+  }
+
+  const durationDays =
+    startDate === null || endDate === null
+      ? 0
+      : Math.max(1, Math.round((endDate - startDate) / 86_400_000) + 1);
+
+  return {
+    name: TRIP_NAME,
+    startDate: stops.length > 0 ? stops[0].startDate : null,
+    endDate: stops.length > 0 ? stops[stops.length - 1].endDate : null,
+    spanStartDate: startDate === null ? null : new Date(startDate).toISOString().slice(0, 10),
+    spanEndDate: endDate === null ? null : new Date(endDate).toISOString().slice(0, 10),
+    durationDays,
+    stopCount,
+  };
+}
+
+function sortActivities(activities, stopLookup) {
+  return [...activities].sort((left, right) => {
+    const dayComparison = compareDayValues(left.day, right.day);
+
+    if (dayComparison !== 0) {
+      return dayComparison;
+    }
+
+    const timeComparison = String(left.time ?? "").localeCompare(String(right.time ?? ""));
+
+    if (timeComparison !== 0) {
+      return timeComparison;
+    }
+
+    const leftStopOrder = stopLookup.get(left.stopId)?.index ?? Number.MAX_SAFE_INTEGER;
+    const rightStopOrder = stopLookup.get(right.stopId)?.index ?? Number.MAX_SAFE_INTEGER;
+
+    if (leftStopOrder !== rightStopOrder) {
+      return leftStopOrder - rightStopOrder;
+    }
+
+    return String(left.id).localeCompare(String(right.id));
+  });
+}
+
+function buildUpcomingEvents(activities, stopLookup) {
+  const orderedActivities = sortActivities(activities, stopLookup);
+  const pendingActivities = orderedActivities.filter((activity) => activity.status === "pending");
+  const selectedActivities = pendingActivities.length > 0 ? pendingActivities : orderedActivities;
+
+  return selectedActivities.slice(0, MAX_NEXT_EVENTS).map((activity) => {
+    const stop = stopLookup.get(activity.stopId)?.stop ?? null;
+
+    return {
+      id: activity.id,
+      type: "activity",
+      title: stop ? stop.name : activity.stopId,
+      date: activity.day,
+      time: activity.time,
+      status: activity.status,
+      stopId: activity.stopId,
+      stopName: stop ? stop.name : null,
+    };
+  });
+}
+
+function buildBudget(summary) {
+  const categories = Object.entries(summary.byCategory ?? {})
+    .map(([category, spent]) => ({ category, spent }))
+    .sort((left, right) => {
+      if (right.spent !== left.spent) {
+        return right.spent - left.spent;
+      }
+
+      return left.category.localeCompare(right.category);
+    });
+
+  return {
+    total: summary.total,
+    spent: summary.spent,
+    available: summary.available,
+    byCategory: summary.byCategory,
+    categories,
+    utilization: clampRatio(summary.total > 0 ? summary.spent / summary.total : 0),
+  };
+}
+
+function buildPacking(progress) {
+  const remaining = Math.max(0, progress.total - progress.completed);
+
+  return {
+    completed: progress.completed,
+    total: progress.total,
+    remaining,
+    progress: clampRatio(progress.total > 0 ? progress.completed / progress.total : 0),
+  };
+}
+
+function buildFavoriteHighlight(favorite, stopLookup, activityLookup) {
+  if (favorite.targetType === "stop") {
+    const stop = stopLookup.get(favorite.targetId)?.stop ?? null;
+
+    return stop
+      ? {
+          kind: "favorite",
+          targetType: "stop",
+          title: stop.name,
+          detail: `${stop.startDate} · ${stop.endDate}`,
+        }
+      : null;
+  }
+
+  const activity = activityLookup.get(favorite.targetId) ?? null;
+
+  if (!activity) {
+    return null;
+  }
+
+  const stop = stopLookup.get(activity.stopId)?.stop ?? null;
+
+  return {
+    kind: "favorite",
+    targetType: "activity",
+    title: activity.time,
+    detail: stop ? `${stop.name} · ${activity.day}` : String(activity.day),
+  };
+}
+
+function buildNoteHighlight(note, stopLookup) {
+  if (note.stopId !== undefined && note.stopId !== null) {
+    const stop = stopLookup.get(String(note.stopId))?.stop ?? null;
+
+    return {
+      kind: "note",
+      title: stop ? stop.name : String(note.stopId),
+      detail: note.text,
+    };
+  }
+
+  return {
+    kind: "note",
+    title: `Día ${note.day}`,
+    detail: note.text,
+  };
+}
+
+function buildHighlightedMemories(favorites, notes, stopLookup, activityLookup) {
+  const highlights = [];
+
+  for (const note of notes) {
+    const highlight = buildNoteHighlight(note, stopLookup);
+
+    if (highlight) {
+      highlights.push(highlight);
+    }
+  }
+
+  for (const favorite of favorites) {
+    const highlight = buildFavoriteHighlight(favorite, stopLookup, activityLookup);
+
+    if (highlight) {
+      highlights.push(highlight);
+    }
+  }
+
+  return highlights.slice(0, MAX_HIGHLIGHTS);
+}
+
+export function buildDashboardSummary() {
+  const stops = listStops();
+  const activities = listActivities();
+  const favorites = listFavorites();
+  const notes = listNotes();
+  const stopLookup = buildStopLookup(stops);
+  const activityLookup = new Map(activities.map((activity) => [activity.id, activity]));
+
+  return {
+    trip: buildTrip(stops),
+    upcomingEvents: buildUpcomingEvents(activities, stopLookup),
+    budget: buildBudget(getBudgetSummary()),
+    packing: buildPacking(getPackingProgress()),
+    highlightedMemories: buildHighlightedMemories(favorites, notes, stopLookup, activityLookup),
+    counts: {
+      stops: stops.length,
+      activities: activities.length,
+      favorites: favorites.length,
+      notes: notes.length,
+    },
+  };
+}
+
+export function getDashboardSummary() {
+  return buildDashboardSummary();
+}
+
+export { TRIP_NAME };
+
+export default getDashboardSummary;

