+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("returns a zeroed dashboard summary before any data is stored", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  assert.deepEqual(getDashboardSummary(), {
+    trip: {
+      name: TRIP_NAME,
+      startDate: null,
+      endDate: null,
+      durationDays: 0,
+      stopCount: 0,
+    },
+    upcomingEvents: [],
+    budget: {
+      total: 0,
+      spent: 0,
+      available: 0,
+      byCategory: {},
+      categories: [],
+      utilization: 0,
+    },
