+      completed: 0,
+      total: 0,
+      remaining: 0,
+      progress: 0,
+    },
+    highlightedMemories: [],
+    counts: {
+      stops: 0,
+      activities: 0,
+      favorites: 0,
+      notes: 0,
+    },
+  });
+});
