+++ b/public/styles.css
@@ -0,0 +1,515 @@
+:root {
+  color-scheme: light;
+  --bg: #f2efe7;
+  --bg-soft: #e5efe9;
+  --surface: rgba(255, 255, 255, 0.8);
+  --surface-strong: #ffffff;
+  --border: rgba(26, 35, 32, 0.12);
+  --border-strong: rgba(26, 35, 32, 0.2);
+  --text: #13211e;
+  --muted: #5a6762;
+  --accent: #0f5e5e;
+  --accent-soft: #d7efeb;
+  --accent-warm: #c86a31;
+  --accent-warm-soft: #f8e3d4;
+  --success: #206a3a;
+  --warning: #a86215;
+  --shadow: 0 20px 45px rgba(16, 24, 22, 0.12);
+  --shadow-soft: 0 10px 24px rgba(16, 24, 22, 0.08);
+  --radius-xl: 28px;
+  --radius-lg: 22px;
+  --radius-md: 16px;
+  --radius-sm: 12px;
+  --font-display: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
+  --font-body: "Trebuchet MS", "Lucida Sans Unicode", "Lucida Grande", sans-serif;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html {
+  min-height: 100%;
+  background: var(--bg);
+}
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  color: var(--text);
+  font-family: var(--font-body);
+  background:
+    radial-gradient(circle at top left, rgba(15, 94, 94, 0.14), transparent 36%),
+    radial-gradient(circle at right 20%, rgba(200, 106, 49, 0.14), transparent 30%),
+    linear-gradient(135deg, var(--bg) 0%, #f7f4ee 48%, var(--bg-soft) 100%);
+}
+
+button,
+input,
+select,
+textarea {
+  font: inherit;
+}
+
+.canvas {
+  position: relative;
+  min-height: 100vh;
+  padding: 32px 20px 40px;
+  overflow: hidden;
+}
+
+.canvas__glow {
+  position: absolute;
+  inset: auto;
+  border-radius: 999px;
+  filter: blur(6px);
+  pointer-events: none;
+  opacity: 0.65;
+}
+
+.canvas__glow--one {
+  width: 18rem;
+  height: 18rem;
+  top: -5rem;
+  right: -3rem;
+  background: radial-gradient(circle, rgba(15, 94, 94, 0.2), transparent 68%);
+}
+
+.canvas__glow--two {
+  width: 22rem;
+  height: 22rem;
+  left: -8rem;
+  bottom: -9rem;
+  background: radial-gradient(circle, rgba(200, 106, 49, 0.16), transparent 68%);
+}
+
+.dashboard-shell {
+  position: relative;
+  z-index: 1;
+  max-width: 1180px;
+  margin: 0 auto;
+  display: grid;
+  gap: 18px;
+}
+
+.card {
+  border: 1px solid var(--border);
+  border-radius: var(--radius-xl);
+  background: var(--surface);
+  backdrop-filter: blur(16px);
+  box-shadow: var(--shadow);
+}
+
+.hero {
+  display: grid;
+  grid-template-columns: minmax(0, 1.55fr) minmax(280px, 0.85fr);
+  gap: 18px;
+  padding: 28px;
+  overflow: hidden;
+}
+
+.hero__copy {
+  display: grid;
+  gap: 12px;
+  align-content: start;
+}
+
+.eyebrow,
+.section-kicker {
+  margin: 0;
+  text-transform: uppercase;
+  letter-spacing: 0.14em;
+  font-size: 0.72rem;
+  font-weight: 700;
+  color: var(--accent);
+}
+
+.hero h1,
+.card h2,
+.card h3 {
+  margin: 0;
+  font-family: var(--font-display);
+  line-height: 1;
+}
+
+.hero h1 {
+  font-size: clamp(2.3rem, 5vw, 4.8rem);
+  max-width: 10ch;
+}
+
+.hero__range {
+  margin: 0;
+  max-width: 42rem;
+  color: var(--muted);
+  font-size: clamp(1rem, 2vw, 1.1rem);
+}
+
+.hero__metrics {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+}
+
+.metric-pill,
+.tag,
+.status-pill,
+.memory-pill {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.4rem;
+  border-radius: 999px;
+  border: 1px solid transparent;
+  padding: 0.5rem 0.8rem;
+  font-size: 0.86rem;
+  font-weight: 700;
+  line-height: 1;
+}
+
+.metric-pill {
+  background: var(--surface-strong);
+  border-color: var(--border);
+  color: var(--text);
+}
+
+.metric-pill--accent {
+  background: var(--accent-soft);
+  border-color: rgba(15, 94, 94, 0.15);
+  color: var(--accent);
+}
+
+.metric-pill--warm {
+  background: var(--accent-warm-soft);
+  border-color: rgba(200, 106, 49, 0.18);
+  color: var(--accent-warm);
+}
+
+.hero__focus {
+  min-height: 100%;
+  padding: 22px;
+  border-radius: 24px;
+  background:
+    linear-gradient(160deg, rgba(9, 27, 25, 0.98), rgba(14, 58, 55, 0.96)),
+    #10201d;
+  color: #f7fbf9;
+  box-shadow: 0 20px 42px rgba(7, 14, 13, 0.28);
+  display: grid;
+  align-content: start;
+  gap: 14px;
+  outline: none;
+}
+
+.hero__focus:focus-visible {
+  box-shadow:
+    0 0 0 3px rgba(248, 227, 212, 0.72),
+    0 0 0 6px rgba(15, 94, 94, 0.4),
+    0 20px 42px rgba(7, 14, 13, 0.28);
+}
+
+.hero__focus .section-kicker {
+  color: #cde8df;
+}
+
+.hero__focus h2 {
+  font-size: clamp(1.35rem, 3vw, 2rem);
+}
+
+.focus__detail {
+  margin: 0;
+  color: rgba(247, 251, 249, 0.86);
+  line-height: 1.6;
+}
+
+.focus__meta {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 8px;
+}
+
+.focus__meta .tag {
+  background: rgba(255, 255, 255, 0.08);
+  border-color: rgba(255, 255, 255, 0.12);
+  color: #f7fbf9;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(12, minmax(0, 1fr));
+  gap: 18px;
+}
+
+.panel {
+  padding: 22px;
+  display: grid;
+  gap: 16px;
+}
+
+.panel--events {
+  grid-column: span 7;
+}
+
+.panel--budget {
+  grid-column: span 5;
+}
+
+.panel--packing {
+  grid-column: span 5;
+}
+
+.panel--memories {
+  grid-column: span 7;
+}
+
+.panel__heading {
+  display: grid;
+  gap: 6px;
+}
+
+.panel__heading p {
+  margin: 0;
+  color: var(--muted);
+  line-height: 1.55;
+}
+
+.section-title {
+  font-size: 1.3rem;
+}
+
+.event-list,
+.memory-list,
+.category-list {
+  display: grid;
+  gap: 10px;
+}
+
+.event-item,
+.memory-item,
+.category-item {
+  border-radius: var(--radius-md);
+  border: 1px solid var(--border);
+  background: var(--surface-strong);
+  padding: 14px 15px;
+  box-shadow: var(--shadow-soft);
+}
+
+.event-item {
+  display: grid;
+  gap: 8px;
+  border-left: 4px solid var(--accent);
+}
+
+.event-item--done {
+  border-left-color: var(--success);
+}
+
+.event-item__top,
+.memory-item__top,
+.category-item__top {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+}
+
+.event-item h3,
+.memory-item h3,
