+++ b/src/dashboard/summary.test.mjs
@@ -0,0 +1,214 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createActivity } from "../itinerary/agenda/agenda.mjs";
+import { createStop } from "../itinerary/stops/stops.mjs";
+import { toggleFavorite } from "../memories/favorites/favorites.mjs";
+import { createNote } from "../memories/notes/notes.mjs";
+import { addExpense, setTotalBudget } from "../organization/budget/budget.mjs";
+import { addPackingItem, togglePackingItem } from "../organization/packing/packing.mjs";
+import { getDashboardSummary, TRIP_NAME } from "./summary.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("returns a zeroed dashboard summary before any data is stored", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  assert.deepEqual(getDashboardSummary(), {
+    trip: {
+      name: TRIP_NAME,
+      startDate: null,
+      endDate: null,
+      durationDays: 0,
+      stopCount: 0,
+    },
+    upcomingEvents: [],
+    budget: {
+      total: 0,
+      spent: 0,
+      available: 0,
+      byCategory: {},
+      categories: [],
+      utilization: 0,
+    },
+    packing: {
+      completed: 0,
+      total: 0,
+      remaining: 0,
+      progress: 0,
+    },
+    highlightedMemories: [],
+    counts: {
+      stops: 0,
+      activities: 0,
+      favorites: 0,
+      notes: 0,
+    },
+  });
+});
+
+test("composes the trip, agenda, budget, packing, and memories into a dashboard summary", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const firstStop = createStop({
+    name: "Buenos Aires",
+    startDate: "2026-09-01",
+    endDate: "2026-09-02",
+    description: "Inicio del viaje",
+  });
+  const secondStop = createStop({
+    name: "Mendoza",
+    startDate: "2026-09-03",
+    endDate: "2026-09-06",
+    description: "Viñedos y descanso",
+  });
+
+  const firstActivity = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-01",
+    time: "09:30",
+  });
+  createActivity({
+    stopId: secondStop.id,
+    day: "2026-09-04",
+    time: "17:00",
+  });
+
+  setTotalBudget(1800);
+  addExpense("alojamiento", 700);
+  addExpense("alimentacion", 250);
+  addExpense("transporte", 100);
+
+  const [bag] = addPackingItem("Pasaporte");
+  const [, coat] = addPackingItem("Campera");
+  togglePackingItem(coat.id);
+
+  const noteByDay = createNote({
+    text: "Reservar almuerzo temprano",
+    day: 2,
+  });
+  const noteByStop = createNote({
+    text: "Buscar mirador al atardecer",
+    stopId: secondStop.id,
+  });
+
+  const favoriteStop = toggleFavorite("stop", firstStop.id);
+  const favoriteActivity = toggleFavorite("activity", firstActivity.id);
+
+  const summary = getDashboardSummary();
+
+  assert.equal(summary.trip.name, TRIP_NAME);
+  assert.deepEqual(summary.trip, {
+    name: TRIP_NAME,
+    startDate: "2026-09-01",
+    endDate: "2026-09-06",
+    durationDays: 6,
+    stopCount: 2,
+  });
+
+  assert.equal(summary.upcomingEvents.length, 2);
+  assert.deepEqual(summary.upcomingEvents[0], {
+    id: firstActivity.id,
+    type: "activity",
+    title: "Buenos Aires",
+    date: "2026-09-01",
+    time: "09:30",
+    status: "pending",
+    stopId: firstStop.id,
+    stopName: "Buenos Aires",
+  });
+  assert.equal(summary.upcomingEvents[1].type, "activity");
+  assert.equal(summary.upcomingEvents[1].title, "Mendoza");
+  assert.equal(summary.upcomingEvents[1].date, "2026-09-04");
+  assert.equal(summary.upcomingEvents[1].time, "17:00");
+  assert.equal(summary.upcomingEvents[1].status, "pending");
+  assert.equal(summary.upcomingEvents[1].stopId, secondStop.id);
+  assert.equal(summary.upcomingEvents[1].stopName, "Mendoza");
+  assert.equal(typeof summary.upcomingEvents[1].id, "string");
+
+  assert.deepEqual(summary.budget, {
+    total: 1800,
+    spent: 1050,
+    available: 750,
+    byCategory: {
+      alojamiento: 700,
+      alimentacion: 250,
+      transporte: 100,
+    },
+    categories: [
+      { category: "alojamiento", spent: 700 },
+      { category: "alimentacion", spent: 250 },
+      { category: "transporte", spent: 100 },
+    ],
+    utilization: 1050 / 1800,
+  });
+
+  assert.deepEqual(summary.packing, {
+    completed: 1,
+    total: 2,
+    remaining: 1,
+    progress: 0.5,
+  });
+
+  assert.deepEqual(summary.highlightedMemories, [
+    {
+      kind: "note",
+      title: "Día 2",
+      detail: "Reservar almuerzo temprano",
+    },
+    {
+      kind: "note",
+      title: "Mendoza",
+      detail: "Buscar mirador al atardecer",
+    },
+    {
+      kind: "favorite",
+      targetType: "stop",
+      title: "Buenos Aires",
+      detail: "2026-09-01 · 2026-09-02",
+    },
+    {
+      kind: "favorite",
+      targetType: "activity",
+      title: "09:30",
+      detail: "Buenos Aires · 2026-09-01",
+    },
+  ]);
+
+  assert.deepEqual(summary.counts, {
+    stops: 2,
+    activities: 2,
+    favorites: 2,
+    notes: 2,
+  });
+
+  assert.equal(bag.completed, false);
+  assert.equal(favoriteStop.targetType, "stop");
+  assert.equal(favoriteActivity.targetType, "activity");
+  assert.equal(noteByDay.day, 2);
+  assert.equal(noteByStop.stopId, secondStop.id);
+});

