@@ -0,0 +1,515 @@
+const STORAGE_KEYS = {
+  stops: "itinerary:stops",
+  activities: "itinerary:agenda",
+  budget: "organization.budget",
+  packing: "organization:packing",
+  favorites: "itinerary:favorites",
+  notes: "memories:notes",
+};
+
+const MAX_NEXT_EVENTS = 4;
+const MAX_HIGHLIGHTS = 4;
+const TRIP_NAME = "Viaje en Familia";
+
+const numberFormatter = new Intl.NumberFormat("es-AR");
+const dateFormatter = new Intl.DateTimeFormat("es-AR", {
+  day: "numeric",
+  month: "short",
+  year: "numeric",
+});
+
+function readJSON(key, fallback) {
+  const serialized = window.localStorage.getItem(key);
+
+  if (serialized === null) {
+    return fallback;
+  }
+
+  try {
+    return JSON.parse(serialized);
+  } catch {
+    return fallback;
+  }
+}
+
+function parseDateOnly(value) {
+  if (typeof value !== "string") {
+    return null;
+  }
+
+  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
+
+  if (!match) {
+    return null;
+  }
+
+  return Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
+}
+
+function compareDayValues(left, right) {
+  const leftIsNumber = typeof left === "number" || /^\d+$/.test(String(left));
+  const rightIsNumber = typeof right === "number" || /^\d+$/.test(String(right));
+
+  if (leftIsNumber && rightIsNumber) {
+    return Number(left) - Number(right);
+  }
+
+  return String(left ?? "").localeCompare(String(right ?? ""));
+}
+
+function clampRatio(value) {
+  if (!Number.isFinite(value) || value < 0) {
+    return 0;
+  }
+
+  return value > 1 ? 1 : value;
+}
+
+function buildStopLookup(stops) {
+  return new Map(stops.map((stop, index) => [String(stop.id), { stop, index }]));
+}
+
+function readStops() {
+  const stops = readJSON(STORAGE_KEYS.stops, []);
+  return Array.isArray(stops) ? stops.filter(Boolean).map((stop) => ({ ...stop })) : [];
+}
+
+function readActivities() {
+  const activities = readJSON(STORAGE_KEYS.activities, []);
+  return Array.isArray(activities) ? activities.filter(Boolean).map((activity) => ({ ...activity })) : [];
+}
+
+function readFavorites() {
+  const favorites = readJSON(STORAGE_KEYS.favorites, []);
+  return Array.isArray(favorites) ? favorites.filter(Boolean).map((favorite) => ({ ...favorite })) : [];
+}
+
+function readNotes() {
+  const notes = readJSON(STORAGE_KEYS.notes, []);
+  return Array.isArray(notes) ? notes.filter(Boolean).map((note) => ({ ...note })) : [];
+}
+
+function readBudget() {
+  const budget = readJSON(STORAGE_KEYS.budget, null);
+
+  return {
+    total: Number.isFinite(budget?.total) ? budget.total : 0,
+    spent: Number.isFinite(budget?.spent) ? budget.spent : 0,
+    available: Number.isFinite(budget?.available) ? budget.available : 0,
+    byCategory:
+      budget && typeof budget.byCategory === "object" && budget.byCategory !== null
+        ? { ...budget.byCategory }
+        : {},
+  };
+}
+
+function readPacking() {
+  const items = readJSON(STORAGE_KEYS.packing, []);
+  const packingItems = Array.isArray(items) ? items.filter(Boolean).map((item) => ({ ...item })) : [];
+  const completed = packingItems.filter((item) => Boolean(item.completed)).length;
+
+  return {
+    completed,
+    total: packingItems.length,
+    remaining: Math.max(0, packingItems.length - completed),
+    progress: packingItems.length > 0 ? clampRatio(completed / packingItems.length) : 0,
+  };
+}
+
+function buildTrip(stops) {
+  let startDate = null;
+  let endDate = null;
+
+  for (const stop of stops) {
+    const stopStart = parseDateOnly(stop.startDate);
+    const stopEnd = parseDateOnly(stop.endDate);
+
+    if (stopStart !== null && (startDate === null || stopStart < startDate)) {
+      startDate = stopStart;
+    }
+
+    if (stopEnd !== null && (endDate === null || stopEnd > endDate)) {
+      endDate = stopEnd;
+    }
+  }
+
+  return {
+    name: TRIP_NAME,
+    startDate: startDate === null ? null : new Date(startDate).toISOString().slice(0, 10),
+    endDate: endDate === null ? null : new Date(endDate).toISOString().slice(0, 10),
+    durationDays:
+      startDate === null || endDate === null
+        ? 0
+        : Math.max(1, Math.round((endDate - startDate) / 86_400_000) + 1),
+    stopCount: stops.length,
+  };
+}
+
+function sortActivities(activities, stopLookup) {
+  return [...activities].sort((left, right) => {
+    const dayComparison = compareDayValues(left.day, right.day);
+
+    if (dayComparison !== 0) {
+      return dayComparison;
+    }
+
+    const timeComparison = String(left.time ?? "").localeCompare(String(right.time ?? ""));
+
+    if (timeComparison !== 0) {
+      return timeComparison;
+    }
+
+    const leftOrder = stopLookup.get(String(left.stopId))?.index ?? Number.MAX_SAFE_INTEGER;
+    const rightOrder = stopLookup.get(String(right.stopId))?.index ?? Number.MAX_SAFE_INTEGER;
+
+    if (leftOrder !== rightOrder) {
+      return leftOrder - rightOrder;
+    }
+
+    return String(left.id).localeCompare(String(right.id));
+  });
+}
+
+function buildUpcomingEvents(activities, stopLookup) {
+  const orderedActivities = sortActivities(activities, stopLookup);
+  const pendingActivities = orderedActivities.filter((activity) => activity.status === "pending");
+  const selectedActivities = pendingActivities.length > 0 ? pendingActivities : orderedActivities;
+
+  return selectedActivities.slice(0, MAX_NEXT_EVENTS).map((activity) => {
+    const stop = stopLookup.get(String(activity.stopId))?.stop ?? null;
+
+    return {
+      id: activity.id,
+      type: "activity",
+      title: stop ? stop.name : String(activity.stopId),
+      date: activity.day,
+      time: activity.time,
+      status: activity.status,
+      stopId: activity.stopId,
+      stopName: stop ? stop.name : null,
+    };
+  });
+}
+
+function buildHighlights(favorites, notes, stopLookup, activityLookup) {
+  const highlights = [];
+
+  for (const note of notes) {
+    if (note.stopId !== undefined && note.stopId !== null) {
+      const stop = stopLookup.get(String(note.stopId))?.stop ?? null;
+      highlights.push({
+        kind: "note",
+        title: stop ? stop.name : String(note.stopId),
+        detail: note.text,
+      });
+      continue;
+    }
+
+    highlights.push({
+      kind: "note",
+      title: `Día ${note.day}`,
+      detail: note.text,
+    });
+  }
+
+  for (const favorite of favorites) {
+    if (favorite.targetType === "stop") {
+      const stop = stopLookup.get(String(favorite.targetId))?.stop ?? null;
+      if (stop) {
+        highlights.push({
+          kind: "favorite",
+          targetType: "stop",
+          title: stop.name,
+          detail: `${stop.startDate} · ${stop.endDate}`,
+        });
+      }
+      continue;
+    }
+
+    const activity = activityLookup.get(String(favorite.targetId)) ?? null;
+    if (activity) {
+      const stop = stopLookup.get(String(activity.stopId))?.stop ?? null;
+      highlights.push({
+        kind: "favorite",
+        targetType: "activity",
+        title: activity.time,
+        detail: stop ? `${stop.name} · ${activity.day}` : String(activity.day),
+      });
+    }
+  }
+
+  return highlights.slice(0, MAX_HIGHLIGHTS);
+}
+
+function buildBudget(summary) {
+  const categories = Object.entries(summary.byCategory ?? {})
+    .map(([category, spent]) => ({ category, spent }))
+    .sort((left, right) => {
+      if (right.spent !== left.spent) {
+        return right.spent - left.spent;
+      }
+
+      return left.category.localeCompare(right.category);
+    });
+
+  return {
+    total: summary.total,
+    spent: summary.spent,
+    available: summary.available,
+    byCategory: summary.byCategory,
+    categories,
+    utilization: clampRatio(summary.total > 0 ? summary.spent / summary.total : 0),
+  };
+}
+
+function formatDate(value) {
+  if (!value) {
+    return null;
+  }
+
+  const timestamp = parseDateOnly(value);
+
+  if (timestamp === null) {
+    return value;
+  }
+
+  return dateFormatter.format(new Date(timestamp));
+}
+
+function formatMoney(value) {
+  return `$${numberFormatter.format(value)}`;
+}
+
+function escapeHtml(value) {
+  return String(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function statusLabel(status) {
+  return status === "done" ? "completado" : "pendiente";
+}
+
+function statusClass(status) {
+  return status === "done" ? "status-pill status-pill--done" : "status-pill";
+}
+
+function memoryClass(item) {
+  return item.kind === "favorite" ? "memory-pill memory-pill--favorite" : "memory-pill";
+}
+
+function renderDashboard() {
+  const stops = readStops();
+  const activities = readActivities();
+  const favorites = readFavorites();
+  const notes = readNotes();
+  const stopLookup = buildStopLookup(stops);
+  const activityLookup = new Map(activities.map((activity) => [String(activity.id), activity]));
+  const summary = {
+    trip: buildTrip(stops),
+    upcomingEvents: buildUpcomingEvents(activities, stopLookup),
+    budget: buildBudget(readBudget()),
+    packing: readPacking(),
+    highlightedMemories: buildHighlights(favorites, notes, stopLookup, activityLookup),
+  };
+
+  const tripRange =
+    summary.trip.startDate && summary.trip.endDate
+      ? `${formatDate(summary.trip.startDate)} — ${formatDate(summary.trip.endDate)}`
+      : "Todavía no hay fechas cargadas";
+
+  const metrics = [
+    { label: `${summary.trip.stopCount} paradas`, tone: "metric-pill--accent" },
+    { label: `${activities.length} actividades`, tone: "metric-pill--warm" },
+    { label: `${summary.highlightedMemories.length} recuerdos`, tone: "" },
+  ];
+
+  const focusEvent = summary.upcomingEvents[0] ?? null;
+  const focusTitle = focusEvent
+    ? `${formatDate(focusEvent.date) ?? focusEvent.date} · ${focusEvent.time}`
+    : "Próximo evento";
+  const focusDetail = focusEvent
+    ? `${focusEvent.title} · ${statusLabel(focusEvent.status)}`
+    : "La agenda aparecerá aquí cuando haya actividades.";
+  const focusMeta = focusEvent
+    ? `
+      <span class="tag">${escapeHtml(focusEvent.stopName ?? focusEvent.title)}</span>
+      <span class="${statusClass(focusEvent.status)}">${escapeHtml(statusLabel(focusEvent.status))}</span>
+    `
+    : `<span class="tag">Esperando actividades</span>`;
+
+  const dashboard = document.querySelector("#dashboard");
+  const tripRangeNode = document.querySelector("#trip-range");
+  const tripMetricsNode = document.querySelector("#trip-metrics");
+  const focusTitleNode = document.querySelector("#focus-title");
+  const focusDetailNode = document.querySelector("#focus-detail");
+  const focusMetaNode = document.querySelector("#focus-meta");
+
+  document.title = `${TRIP_NAME} · Dashboard`;
+  tripRangeNode.textContent = tripRange;
+  tripMetricsNode.innerHTML = metrics
+    .map(({ label, tone }) => `<span class="metric-pill ${tone}">${escapeHtml(label)}</span>`)
+    .join("");
+  focusTitleNode.textContent = focusTitle;
+  focusDetailNode.textContent = focusDetail;
+  focusMetaNode.innerHTML = focusMeta;
+
+  const budgetProgress = summary.budget.utilization * 100;
+  const packingProgress = summary.packing.progress * 100;
+
+  const upcomingEventsMarkup = summary.upcomingEvents.length
+    ? `<div class="event-list">
+        ${summary.upcomingEvents
+          .map(
+            (event) => `
+              <article class="event-item ${event.status === "done" ? "event-item--done" : ""}">
+                <div class="event-item__top">
+                  <h3>${escapeHtml(event.title)}</h3>
+                  <span class="${statusClass(event.status)}">${escapeHtml(statusLabel(event.status))}</span>
+                </div>
+                <p>${escapeHtml(formatDate(event.date) ?? String(event.date))} · ${escapeHtml(event.time)}</p>
+                <div class="event-meta">
+                  <span class="tag">${escapeHtml(event.stopName ?? event.title)}</span>
+                  <span class="tag">Parada ${escapeHtml(String(summary.trip.stopCount))}</span>
+                </div>
+              </article>
+            `,
+          )
+          .join("")}
+      </div>`
+    : `<div class="empty-state">Aún no hay actividades cargadas. Cuando agregues agenda, este bloque mostrará los próximos pasos del viaje.</div>`;
+
+  const budgetCategoriesMarkup = summary.budget.categories.length
+    ? `<div class="category-list">
+        ${summary.budget.categories
+          .map(
+            (item) => `
+              <article class="category-item">
+                <div class="category-item__top">
+                  <h3>${escapeHtml(item.category)}</h3>
+                  <span>${formatMoney(item.spent)}</span>
+                </div>
+                <div class="category-item__bar" aria-hidden="true">
+                  <div class="category-item__fill" style="width:${summary.budget.spent > 0 ? Math.max(6, (item.spent / summary.budget.spent) * 100) : 0}%"></div>
+                </div>
+              </article>
+            `,
+          )
+          .join("")}
+      </div>`
+    : `<div class="empty-state">No hay gastos registrados todavía. Carga el presupuesto para ver el reparto por categoría.</div>`;
+
+  const packingStatsMarkup = `
+    <dl class="packing__stats">
+      <div class="stat">
+        <dt>Listo</dt>
+        <dd>${numberFormatter.format(summary.packing.completed)}</dd>
+      </div>
+      <div class="stat">
+        <dt>Total</dt>
+        <dd>${numberFormatter.format(summary.packing.total)}</dd>
+      </div>
+      <div class="stat">
+        <dt>Restante</dt>
+        <dd>${numberFormatter.format(summary.packing.remaining)}</dd>
+      </div>
+    </dl>
+  `;
+
+  const memoriesMarkup = summary.highlightedMemories.length
+    ? `<div class="memory-list">
+        ${summary.highlightedMemories
+          .map(
+            (memory) => `
+              <article class="memory-item">
+                <div class="memory-item__top">
+                  <h3>${escapeHtml(memory.title)}</h3>
+                  <span class="${memoryClass(memory)}">${escapeHtml(memory.kind === "favorite" ? "favorito" : "nota")}</span>
+                </div>
+                <p>${escapeHtml(memory.detail)}</p>
+                <div class="memory-meta">
+                  <span class="tag">${escapeHtml(memory.kind === "favorite" ? memory.targetType : "recuerdo")}</span>
+                </div>
+              </article>
+            `,
+          )
+          .join("")}
+      </div>`
+    : `<div class="empty-state">Todavía no hay recuerdos destacados. Las notas y favoritos aparecerán aquí cuando existan.</div>`;
+
+  dashboard.innerHTML = `
+    <article class="card panel panel--events">
+      <div class="panel__heading">
+        <p class="section-kicker">Agenda</p>
+        <h2 class="section-title">Próximos eventos</h2>
+        <p>Eventos ordenados por fecha y hora, priorizando los que todavía están pendientes.</p>
+      </div>
+      ${upcomingEventsMarkup}
+    </article>
+
+    <article class="card panel panel--budget">
+      <div class="panel__heading">
+        <p class="section-kicker">Presupuesto</p>
+        <h2 class="section-title">Resumen financiero</h2>
+        <p>El gasto acumulado y la disponibilidad quedan a la vista con alto contraste.</p>
+      </div>
+      <dl class="budget__stats">
+        <div class="stat">
+          <dt>Total</dt>
+          <dd>${formatMoney(summary.budget.total)}</dd>
+        </div>
+        <div class="stat">
+          <dt>Gastado</dt>
+          <dd>${formatMoney(summary.budget.spent)}</dd>
+        </div>
+        <div class="stat">
+          <dt>Disponible</dt>
+          <dd>${formatMoney(summary.budget.available)}</dd>
+        </div>
+      </dl>
+      <div class="progress" aria-label="Progreso del presupuesto">
+        <div class="progress__labels">
+          <span>Uso del presupuesto</span>
+          <strong>${Math.round(budgetProgress)}%</strong>
+        </div>
+        <div class="progress__bar" aria-hidden="true">
+          <div class="progress__fill progress__fill--budget" style="width:${budgetProgress}%"></div>
+        </div>
+      </div>
+      ${budgetCategoriesMarkup}
+    </article>
+
+    <article class="card panel panel--packing">
+      <div class="panel__heading">
+        <p class="section-kicker">Equipaje</p>
+        <h2 class="section-title">Progreso de armado</h2>
+        <p>Todo lo que ya está listo y lo que todavía falta por completar.</p>
+      </div>
+      ${packingStatsMarkup}
+      <div class="progress" aria-label="Progreso del equipaje">
+        <div class="progress__labels">
+          <span>Equipaje listo</span>
+          <strong>${Math.round(packingProgress)}%</strong>
+        </div>
+        <div class="progress__bar" aria-hidden="true">
+          <div class="progress__fill progress__fill--packing" style="width:${packingProgress}%"></div>
+        </div>
+      </div>
+    </article>
+
+    <article class="card panel panel--memories">
+      <div class="panel__heading">
+        <p class="section-kicker">Recuerdos</p>
+        <h2 class="section-title">Destacados</h2>
+        <p>Notas y favoritos mezclados para que el viaje también tenga memoria visible.</p>
+      </div>
+      ${memoriesMarkup}
+    </article>
+  `;
+}
+
+window.addEventListener("DOMContentLoaded", renderDashboard);
+window.addEventListener("storage", renderDashboard);
