+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createActivity } from "../itinerary/agenda/agenda.mjs";
+import { toggleFavorite } from "../memories/favorites/favorites.mjs";
+import { createNote } from "../memories/notes/notes.mjs";
+import { setTotalBudget, addExpense } from "../organization/budget/budget.mjs";
+import { addPackingItem, togglePackingItem } from "../organization/packing/packing.mjs";
+import { createStop } from "../itinerary/stops/stops.mjs";
+import { buildDashboardSummary } from "./summary.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("builds a dashboard summary from the canonical stores", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const madrid = createStop({
+    name: "Madrid",
+    startDate: "2026-09-01",
+    endDate: "2026-09-03",
+    description: "Llegada y primer paseo",
+  });
+  const sevilla = createStop({
+    name: "Sevilla",
+    startDate: "2026-09-04",
+    endDate: "2026-09-06",
+    description: "Centro histórico y tapas",
+  });
+
+  const breakfast = createActivity({
+    stopId: madrid.id,
+    day: 1,
+    time: "08:30",
+    status: "pending",
+  });
+  const museum = createActivity({
+    stopId: sevilla.id,
+    day: 4,
+    time: "19:00",
+    status: "done",
+  });
+
+  setTotalBudget(2500);
+  addExpense("transporte", 900);
+  addExpense("alojamiento", 800);
+
+  addPackingItem("Documentos");
+  const sunscreen = addPackingItem("Protector solar");
+  togglePackingItem(sunscreen.id);
+
+  createNote({
+    text: "Reservar mesa cerca de la plaza",
+    day: 1,
+  });
+  createNote({
+    text: "Buscar helado en el centro",
+    stopId: sevilla.id,
+  });
+
+  toggleFavorite("stop", madrid.id);
+  toggleFavorite("activity", breakfast.id);
+
+  const summary = buildDashboardSummary();
+
+  assert.deepEqual(summary.trip, {
+    name: "Viaje en familia",
+    startDate: "2026-09-01",
+    endDate: "2026-09-06",
+    dateLabel: "1 sep 2026 al 6 sep 2026",
+    stopCount: 2,
+    durationLabel: "6 días",
+  });
+
+  assert.deepEqual(
+    summary.upcomingEvents.map((event) => ({
+      id: event.id,
+      stopName: event.stopName,
+      label: event.label,
+      status: event.status,
+      statusLabel: event.statusLabel,
+    })),
+    [
+      {
+        id: breakfast.id,
+        stopName: "Madrid",
+        label: "Día 1 · 08:30",
+        status: "pending",
+        statusLabel: "Pendiente",
+      },
+      {
+        id: museum.id,
+        stopName: "Sevilla",
+        label: "Día 4 · 19:00",
+        status: "done",
+        statusLabel: "Completado",
+      },
+    ],
+  );
+
+  assert.equal(summary.budget.total, 2500);
+  assert.equal(summary.budget.spent, 1700);
+  assert.equal(summary.budget.available, 800);
+  assert.deepEqual(summary.budget.byCategory, [
+    { category: "transporte", amount: 900 },
+    { category: "alojamiento", amount: 800 },
+  ]);
+
+  assert.deepEqual(summary.packing, {
+    completed: 1,
+    total: 2,
+    remaining: 1,
+    completionPercent: 50,
+    completionLabel: "1 de 2",
+  });
+
+  assert.deepEqual(summary.memories.favorites, [
+    {
+      targetType: "stop",
+      targetId: madrid.id,
+      label: "Parada: Madrid",
+      detail: "1 sep 2026 al 3 sep 2026",
+    },
+    {
+      targetType: "activity",
+      targetId: breakfast.id,
+      label: "Actividad: Día 1 · 08:30 · Madrid",
+      detail: "Actividad pendiente",
+    },
+  ]);
+
+  assert.deepEqual(summary.memories.notes, [
+    {
+      id: summary.memories.notes[0].id,
+      text: "Reservar mesa cerca de la plaza",
+      day: 1,
+      stopId: undefined,
+      label: "Día 1",
+    },
+    {
+      id: summary.memories.notes[1].id,
+      text: "Buscar helado en el centro",
+      day: undefined,
+      stopId: sevilla.id,
+      label: "Sevilla",
+    },
+  ]);
+
+  assert.deepEqual(summary.counts, {
+    stops: 2,
+    activities: 2,
+    notes: 2,
+    favorites: 2,
+  });
+});
+
+test("returns empty dashboard sections when no data is stored", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const summary = buildDashboardSummary();
+
+  assert.deepEqual(summary.trip, {
+    name: "Viaje en familia",
+    startDate: null,
+    endDate: null,
+    dateLabel: "Fechas por definir",
+    stopCount: 0,
+    durationLabel: "0 días",
+  });
+  assert.deepEqual(summary.upcomingEvents, []);
+  assert.deepEqual(summary.budget, {
+    total: 0,
+    spent: 0,
+    available: 0,
+    usagePercent: 0,
+    usageLabel: "0% usado",
+    byCategory: [],
+  });
+  assert.deepEqual(summary.packing, {
+    completed: 0,
+    total: 0,
+    remaining: 0,
+    completionPercent: 0,
+    completionLabel: "Sin pendientes",
+  });
+  assert.deepEqual(summary.memories, {
+    favorites: [],
+    notes: [],
+  });
+  assert.deepEqual(summary.counts, {
+    stops: 0,
+    activities: 0,
+    notes: 0,
+    favorites: 0,
+  });
+});

