@@ -0,0 +1,436 @@
+:root {
+  color-scheme: light;
+  --bg: #edf2f7;
+  --bg-accent: #dbeafe;
+  --surface: #ffffff;
+  --surface-strong: #0f172a;
+  --surface-soft: #f8fafc;
+  --text: #0f172a;
+  --text-soft: #475569;
+  --border: rgba(15, 23, 42, 0.12);
+  --border-strong: rgba(15, 23, 42, 0.18);
+  --accent: #1d4ed8;
+  --accent-soft: rgba(29, 78, 216, 0.12);
+  --accent-strong: #2563eb;
+  --success: #0f766e;
+  --warning: #b45309;
+  --shadow: 0 24px 70px rgba(15, 23, 42, 0.08);
+  --radius-lg: 28px;
+  --radius-md: 20px;
+  --radius-sm: 14px;
+  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+}
+
+*,
+*::before,
+*::after {
+  box-sizing: border-box;
+}
+
+html {
+  min-height: 100%;
+}
+
+body {
+  margin: 0;
+  min-height: 100dvh;
+  color: var(--text);
+  background:
+    radial-gradient(circle at top left, rgba(29, 78, 216, 0.12), transparent 34%),
+    radial-gradient(circle at 85% 10%, rgba(37, 99, 235, 0.08), transparent 26%),
+    linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
+}
+
+body::before {
+  content: "";
+  position: fixed;
+  inset: 0;
+  pointer-events: none;
+  background:
+    linear-gradient(120deg, rgba(255, 255, 255, 0.3), transparent 20%),
+    linear-gradient(315deg, rgba(29, 78, 216, 0.04), transparent 42%);
+  opacity: 0.9;
+}
+
+button,
+a {
+  font: inherit;
+}
+
+button {
+  border: 0;
+  background: none;
+}
+
+.app-shell {
+  position: relative;
+  z-index: 1;
+  width: min(1180px, calc(100% - 32px));
+  margin: 0 auto;
+  padding: 28px 0 40px;
+}
+
+.dashboard {
+  display: grid;
+  gap: 20px;
+}
+
+.hero {
+  display: grid;
+  gap: 24px;
+  padding: 28px;
+  border: 1px solid rgba(255, 255, 255, 0.12);
+  border-radius: var(--radius-lg);
+  color: #f8fafc;
+  background:
+    linear-gradient(135deg, rgba(15, 23, 42, 0.98), rgba(15, 23, 42, 0.92)),
+    linear-gradient(120deg, rgba(29, 78, 216, 0.25), transparent 55%);
+  box-shadow: var(--shadow);
+}
+
+.hero-top {
+  display: flex;
+  align-items: flex-start;
+  justify-content: space-between;
+  gap: 20px;
+}
+
+.eyebrow {
+  margin: 0 0 10px;
+  color: rgba(226, 232, 240, 0.72);
+  font-size: 0.82rem;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+}
+
+.hero h1,
+.panel h2 {
+  margin: 0;
+  letter-spacing: -0.04em;
+}
+
+.hero h1 {
+  max-width: 11ch;
+  font-size: clamp(2.5rem, 5vw, 4.8rem);
+  line-height: 0.95;
+}
+
+.hero-copy {
+  max-width: 52rem;
+}
+
+.hero-lead {
+  margin: 14px 0 0;
+  max-width: 46rem;
+  color: rgba(226, 232, 240, 0.78);
+  font-size: 1.04rem;
+  line-height: 1.6;
+}
+
+.hero-actions {
+  display: flex;
+  flex-wrap: wrap;
+  justify-content: flex-end;
+  gap: 12px;
+}
+
+.refresh-button {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  min-height: 44px;
+  padding: 0 18px;
+  border-radius: 999px;
+  color: #0f172a;
+  background: #f8fafc;
+  border: 1px solid rgba(248, 250, 252, 0.18);
+  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.12);
+  cursor: pointer;
+  transition: transform 150ms ease, background-color 150ms ease, box-shadow 150ms ease;
+}
+
+.refresh-button:hover {
+  transform: translateY(-1px);
+}
+
+.refresh-button:active {
+  transform: translateY(0);
+}
+
+.refresh-button:focus-visible {
+  outline: 3px solid #ffffff;
+  outline-offset: 3px;
+}
+
+.hero-stats {
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 12px;
+}
+
+.stat {
+  padding: 16px 18px;
+  border-radius: var(--radius-sm);
+  background: rgba(255, 255, 255, 0.06);
+  border: 1px solid rgba(255, 255, 255, 0.1);
+}
+
+.stat dt {
+  margin: 0 0 6px;
+  color: rgba(226, 232, 240, 0.68);
+  font-size: 0.82rem;
+}
+
+.stat dd {
+  margin: 0;
+  font-size: 1.25rem;
+  font-weight: 700;
+}
+
+.dashboard-grid {
+  display: grid;
+  grid-template-columns: minmax(0, 1.45fr) minmax(0, 0.95fr);
+  gap: 20px;
+}
+
+.panel {
+  display: grid;
+  gap: 18px;
+  padding: 24px;
+  border-radius: var(--radius-lg);
+  background: rgba(255, 255, 255, 0.84);
+  border: 1px solid var(--border);
+  box-shadow: var(--shadow);
+  backdrop-filter: blur(18px);
+  -webkit-backdrop-filter: blur(18px);
+}
+
+.panel h2 {
+  font-size: clamp(1.25rem, 2.4vw, 1.8rem);
+}
+
+.panel-copy {
+  margin: -6px 0 0;
+  color: var(--text-soft);
+  line-height: 1.55;
+}
+
+.events-list,
+.memory-list,
+.category-list {
+  display: grid;
+  gap: 12px;
+}
+
+.event-row,
+.memory-row,
+.category-row {
+  display: grid;
+  gap: 10px;
+  padding: 16px;
+  border-radius: var(--radius-md);
+  border: 1px solid var(--border);
+  background: linear-gradient(180deg, #ffffff, #f8fbff);
+}
+
+.event-row {
+  grid-template-columns: minmax(0, 1fr) auto;
+  align-items: start;
+}
+
+.event-main {
+  display: grid;
+  gap: 6px;
+}
+
+.event-title,
+.memory-title,
+.category-title {
+  font-weight: 700;
+  color: var(--text);
+}
+
+.event-meta,
+.memory-meta,
+.category-meta {
+  color: var(--text-soft);
+  line-height: 1.45;
+}
+
+.status-pill {
+  justify-self: start;
+  padding: 7px 11px;
+  border-radius: 999px;
+  font-size: 0.78rem;
+  font-weight: 700;
+  letter-spacing: 0.02em;
+  color: var(--accent-strong);
+  background: var(--accent-soft);
+}
+
+.status-pill.is-done {
+  color: var(--success);
+  background: rgba(15, 118, 110, 0.12);
+}
+
+.summary-grid {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 12px;
+}
+
+.summary-card {
+  display: grid;
+  gap: 6px;
+  padding: 16px;
+  border-radius: var(--radius-md);
+  background: var(--surface-soft);
+  border: 1px solid var(--border);
+}
+
+.summary-card span {
+  color: var(--text-soft);
+  font-size: 0.88rem;
+}
+
+.summary-card strong {
+  font-size: 1.2rem;
+  line-height: 1.1;
+}
+
+.progress-track {
+  height: 12px;
+  border-radius: 999px;
+  overflow: hidden;
+  background: rgba(15, 23, 42, 0.08);
+}
+
+.progress-fill {
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), #60a5fa);
+}
+
+.progress-label {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+  color: var(--text-soft);
+}
+
+.section-hero {
+  display: grid;
+  gap: 16px;
+}
+
+.section-meta {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+}
+
+.meta-chip {
+  display: inline-flex;
+  align-items: center;
+  min-height: 34px;
+  padding: 0 12px;
+  border-radius: 999px;
+  background: rgba(29, 78, 216, 0.08);
+  color: var(--accent-strong);
+  font-size: 0.88rem;
+  font-weight: 700;
+}
+
+.empty-state {
+  padding: 20px;
+  border-radius: var(--radius-md);
+  color: var(--text-soft);
+  background: linear-gradient(180deg, #ffffff, #f8fbff);
+  border: 1px dashed rgba(15, 23, 42, 0.16);
+}
+
+.memory-split {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 14px;
+}
+
+.memory-group {
+  display: grid;
+  gap: 12px;
+}
+
+.memory-group h3 {
+  margin: 0;
+  font-size: 0.98rem;
+}
+
+.memory-row {
+  gap: 8px;
+}
+
+.memory-text {
+  margin: 0;
+  color: var(--text);
+  line-height: 1.55;
+}
+
+.focus-card {
+  outline: none;
+}
+
+.focus-card:focus-within,
+.panel:focus-within,
+.hero:focus-within {
+  border-color: rgba(29, 78, 216, 0.28);
+  box-shadow:
+    0 0 0 4px rgba(29, 78, 216, 0.12),
+    var(--shadow);
+}
+
+button:focus-visible,
+a:focus-visible,
+[tabindex]:focus-visible {
+  outline: 3px solid var(--accent);
+  outline-offset: 3px;
+}
+
+@media (max-width: 960px) {
+  .hero-stats {
+    grid-template-columns: repeat(2, minmax(0, 1fr));
+  }
+
+  .dashboard-grid {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (max-width: 720px) {
+  .app-shell {
+    width: min(100% - 20px, 1180px);
+    padding-top: 18px;
+  }
+
+  .hero {
+    padding: 22px;
+  }
+
+  .hero-top {
+    flex-direction: column;
+  }
+
+  .hero-actions {
+    justify-content: flex-start;
+  }
+
+  .hero-stats,
+  .summary-grid,
+  .memory-split {
+    grid-template-columns: 1fr;
+  }
+
+  .event-row {
+    grid-template-columns: 1fr;
+  }
+}
diff --git a/src/dashboard/summary.mjs b/src/dashboard/summary.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..37cb3c2f4ac174d97b3e43c81d0432c9b3e8f105
--- /dev/null
+++ b/src/dashboard/summary.mjs
@@ -0,0 +1,338 @@
+import { getBudgetSummary } from "../organization/budget/budget.mjs";
+import { listFavorites } from "../memories/favorites/favorites.mjs";
+import { listNotes } from "../memories/notes/notes.mjs";
+import { getPackingProgress } from "../organization/packing/packing.mjs";
+import { listActivities } from "../itinerary/agenda/agenda.mjs";
+import { listStops } from "../itinerary/stops/stops.mjs";
+
+export const DASHBOARD_STORAGE_KEYS = [
+  "itinerary:stops",
+  "itinerary:agenda",
+  "organization.budget",
+  "organization:packing",
+  "memories:notes",
+  "itinerary:favorites",
+];
+
+const TRIP_NAME = "Viaje en familia";
+const MONTHS = [
+  "ene",
+  "feb",
+  "mar",
+  "abr",
+  "may",
+  "jun",
+  "jul",
+  "ago",
+  "sep",
+  "oct",
+  "nov",
+  "dic",
+];
+
+function isIsoDate(value) {
+  return typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value);
+}
+
+function parseUtcDate(value) {
+  if (!isIsoDate(value)) {
+    return null;
+  }
+
+  const parsed = new Date(`${value}T00:00:00Z`);
+
+  return Number.isNaN(parsed.getTime()) ? null : parsed;
+}
+
+function compareIsoDates(left, right) {
+  if (left === right) {
+    return 0;
+  }
+
+  if (!isIsoDate(left)) {
+    return 1;
+  }
+
+  if (!isIsoDate(right)) {
+    return -1;
+  }
+
+  return left < right ? -1 : 1;
+}
+
+function formatShortDate(value) {
+  const date = parseUtcDate(value);
+
+  if (!date) {
+    return "";
+  }
+
+  return `${date.getUTCDate()} ${MONTHS[date.getUTCMonth()]} ${date.getUTCFullYear()}`;
+}
+
+function formatDateRange(startDate, endDate) {
+  const start = formatShortDate(startDate);
+  const end = formatShortDate(endDate);
+
+  if (start && end) {
+    if (start === end) {
+      return start;
+    }
+
+    return `${start} al ${end}`;
+  }
+
+  return "Fechas por definir";
+}
+
+function formatDayLabel(day) {
+  return `Día ${day}`;
+}
+
+function formatTimeLabel(time) {
+  return typeof time === "string" && time.trim() !== "" ? time : "Horario por definir";
+}
+
+function formatInteger(value) {
+  return new Intl.NumberFormat("es-AR", { maximumFractionDigits: 0 }).format(value);
+}
+
+function createEmptyTripSummary() {
+  return {
+    name: TRIP_NAME,
+    startDate: null,
+    endDate: null,
+    dateLabel: "Fechas por definir",
+    stopCount: 0,
+    durationLabel: "0 días",
+  };
+}
+
+function createTripSummary(stops) {
+  if (stops.length === 0) {
+    return createEmptyTripSummary();
+  }
+
+  const startDate = stops.reduce((best, stop) => {
+    if (!isIsoDate(stop.startDate)) {
+      return best;
+    }
+
+    if (best == null || compareIsoDates(stop.startDate, best) < 0) {
+      return stop.startDate;
+    }
+
+    return best;
+  }, null);
+
+  const endDate = stops.reduce((best, stop) => {
+    if (!isIsoDate(stop.endDate)) {
+      return best;
+    }
+
+    if (best == null || compareIsoDates(best, stop.endDate) < 0) {
+      return stop.endDate;
+    }
+
+    return best;
+  }, null);
+
+  let durationLabel = `${stops.length} paradas`;
+
+  if (startDate && endDate) {
+    const start = parseUtcDate(startDate);
+    const end = parseUtcDate(endDate);
+
+    if (start && end) {
+      const daySpan = Math.max(1, Math.round((end.getTime() - start.getTime()) / 86400000) + 1);
+      durationLabel = `${daySpan} día${daySpan === 1 ? "" : "s"}`;
+    }
+  }
+
+  return {
+    name: TRIP_NAME,
+    startDate,
+    endDate,
+    dateLabel: formatDateRange(startDate, endDate),
+    stopCount: stops.length,
+    durationLabel,
+  };
+}
+
+function sortActivitiesForDashboard(left, right) {
+  const leftRank = left.status === "pending" ? 0 : 1;
+  const rightRank = right.status === "pending" ? 0 : 1;
+
+  if (leftRank !== rightRank) {
+    return leftRank - rightRank;
+  }
+
+  if (left.day !== right.day) {
+    return left.day - right.day;
+  }
+
+  if (left.time !== right.time) {
+    return String(left.time).localeCompare(String(right.time));
+  }
+
+  return String(left.id).localeCompare(String(right.id));
+}
+
+function createUpcomingEvents(activities, stopsById) {
+  return [...activities]
+    .sort(sortActivitiesForDashboard)
+    .map((activity) => {
+      const stop = stopsById.get(String(activity.stopId));
+
+      return {
+        id: activity.id,
+        stopId: activity.stopId,
+        stopName: stop ? stop.name : "Parada sin nombre",
+        day: activity.day,
+        time: activity.time,
+        status: activity.status,
+        statusLabel: activity.status === "done" ? "Completado" : "Pendiente",
+        label: `${formatDayLabel(activity.day)} · ${formatTimeLabel(activity.time)}`,
+      };
+    });
+}
+
+function createBudgetSnapshot() {
+  const summary = getBudgetSummary();
+  const ratio = summary.total > 0 ? Math.min(100, Math.max(0, (summary.spent / summary.total) * 100)) : 0;
+
+  return {
+    total: summary.total,
+    spent: summary.spent,
+    available: summary.available,
+    usagePercent: ratio,
+    usageLabel: `${Math.round(ratio)}% usado`,
+    byCategory: Object.entries(summary.byCategory)
+      .map(([category, amount]) => ({
+        category,
+        amount,
+      }))
+      .sort((left, right) => right.amount - left.amount),
+  };
+}
+
+function createPackingSnapshot() {
+  const progress = getPackingProgress();
+  const completionPercent = progress.total > 0 ? (progress.completed / progress.total) * 100 : 0;
+
+  return {
+    completed: progress.completed,
+    total: progress.total,
+    remaining: Math.max(progress.total - progress.completed, 0),
+    completionPercent,
+    completionLabel: progress.total === 0 ? "Sin pendientes" : `${progress.completed} de ${progress.total}`,
+  };
+}
+
+function createStopLookup(stops) {
+  return new Map(stops.map((stop) => [String(stop.id), stop]));
+}
+
+function createActivityLookup(activities) {
+  return new Map(activities.map((activity) => [String(activity.id), activity]));
+}
+
+function resolveFavoriteLabel(favorite, stopsById, activitiesById) {
+  if (favorite.targetType === "stop") {
+    const stop = stopsById.get(String(favorite.targetId));
+
+    return stop
+      ? `Parada: ${stop.name}`
+      : `Parada: ${String(favorite.targetId)}`;
+  }
+
+  const activity = activitiesById.get(String(favorite.targetId));
+
+  if (!activity) {
+    return `Actividad: ${String(favorite.targetId)}`;
+  }
+
+  const stop = stopsById.get(String(activity.stopId));
+  const stopName = stop ? stop.name : "Parada sin nombre";
+
+  return `Actividad: ${formatDayLabel(activity.day)} · ${formatTimeLabel(activity.time)} · ${stopName}`;
+}
+
+function resolveFavoriteDetail(favorite, stopsById, activitiesById) {
+  if (favorite.targetType === "stop") {
+    const stop = stopsById.get(String(favorite.targetId));
+
+    if (!stop) {
+      return "Marcado como favorito";
+    }
+
+    return formatDateRange(stop.startDate, stop.endDate);
+  }
+
+  const activity = activitiesById.get(String(favorite.targetId));
+
+  if (!activity) {
+    return "Marcado como favorito";
+  }
+
+  return activity.status === "done" ? "Actividad completada" : "Actividad pendiente";
+}
+
+function createFavoritesSnapshot(favorites, stopsById, activitiesById) {
+  return favorites.map((favorite) => ({
+    targetType: favorite.targetType,
+    targetId: favorite.targetId,
+    label: resolveFavoriteLabel(favorite, stopsById, activitiesById),
+    detail: resolveFavoriteDetail(favorite, stopsById, activitiesById),
+  }));
+}
+
+function resolveNoteLabel(note, stopsById) {
+  if (typeof note.day === "number") {
+    return formatDayLabel(note.day);
+  }
+
+  const stop = stopsById.get(String(note.stopId));
+
+  return stop ? stop.name : `Parada ${String(note.stopId)}`;
+}
+
+function createNotesSnapshot(notes, stopsById) {
+  return notes.map((note) => ({
+    id: note.id,
+    text: note.text,
+    day: note.day,
+    stopId: note.stopId,
+    label: resolveNoteLabel(note, stopsById),
+  }));
+}
+
+export function buildDashboardSummary() {
+  const stops = listStops();
+  const activities = listActivities();
+  const notes = listNotes();
+  const favorites = listFavorites();
+  const stopsById = createStopLookup(stops);
+  const activitiesById = createActivityLookup(activities);
+
+  return {
+    trip: createTripSummary(stops),
+    upcomingEvents: createUpcomingEvents(activities, stopsById),
+    budget: createBudgetSnapshot(),
+    packing: createPackingSnapshot(),
+    memories: {
+      favorites: createFavoritesSnapshot(favorites, stopsById, activitiesById),
+      notes: createNotesSnapshot(notes, stopsById),
+    },
+    counts: {
+      stops: stops.length,
+      activities: activities.length,
+      notes: notes.length,
+      favorites: favorites.length,
+    },
+  };
+}
+
+export function formatDashboardMoney(value) {
+  return formatInteger(value);
+}
