diff --git a/src/dashboard/summary.mjs b/src/dashboard/summary.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..37cb3c2f4ac174d97b3e43c81d0432c9b3e8f105
--- /dev/null
+++ b/src/dashboard/summary.mjs
@@ -0,0 +1,338 @@
+import { getBudgetSummary } from "../organization/budget/budget.mjs";
+import { listFavorites } from "../memories/favorites/favorites.mjs";
+import { listNotes } from "../memories/notes/notes.mjs";
+import { getPackingProgress } from "../organization/packing/packing.mjs";
+import { listActivities } from "../itinerary/agenda/agenda.mjs";
+import { listStops } from "../itinerary/stops/stops.mjs";
+
+export const DASHBOARD_STORAGE_KEYS = [
+  "itinerary:stops",
+  "itinerary:agenda",
+  "organization.budget",
+  "organization:packing",
+  "memories:notes",
+  "itinerary:favorites",
+];
+
+const TRIP_NAME = "Viaje en familia";
+const MONTHS = [
+  "ene",
+  "feb",
+  "mar",
+  "abr",
+  "may",
+  "jun",
+  "jul",
+  "ago",
+  "sep",
+  "oct",
+  "nov",
+  "dic",
+];
+
+function isIsoDate(value) {
+  return typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value);
+}
+
+function parseUtcDate(value) {
+  if (!isIsoDate(value)) {
+    return null;
+  }
+
+  const parsed = new Date(`${value}T00:00:00Z`);
+
+  return Number.isNaN(parsed.getTime()) ? null : parsed;
+}
+
+function compareIsoDates(left, right) {
+  if (left === right) {
+    return 0;
+  }
+
+  if (!isIsoDate(left)) {
+    return 1;
+  }
+
+  if (!isIsoDate(right)) {
+    return -1;
+  }
+
+  return left < right ? -1 : 1;
+}
+
+function formatShortDate(value) {
+  const date = parseUtcDate(value);
+
+  if (!date) {
+    return "";
+  }
+
+  return `${date.getUTCDate()} ${MONTHS[date.getUTCMonth()]} ${date.getUTCFullYear()}`;
+}
+
+function formatDateRange(startDate, endDate) {
+  const start = formatShortDate(startDate);
+  const end = formatShortDate(endDate);
+
+  if (start && end) {
+    if (start === end) {
+      return start;
+    }
+
+    return `${start} al ${end}`;
+  }
+
+  return "Fechas por definir";
+}
+
+function formatDayLabel(day) {
+  return `Día ${day}`;
+}
+
+function formatTimeLabel(time) {
+  return typeof time === "string" && time.trim() !== "" ? time : "Horario por definir";
+}
+
+function formatInteger(value) {
+  return new Intl.NumberFormat("es-AR", { maximumFractionDigits: 0 }).format(value);
+}
+
+function createEmptyTripSummary() {
+  return {
+    name: TRIP_NAME,
+    startDate: null,
+    endDate: null,
+    dateLabel: "Fechas por definir",
+    stopCount: 0,
+    durationLabel: "0 días",
+  };
+}
+
+function createTripSummary(stops) {
+  if (stops.length === 0) {
+    return createEmptyTripSummary();
+  }
+
+  const startDate = stops.reduce((best, stop) => {
+    if (!isIsoDate(stop.startDate)) {
+      return best;
+    }
+
+    if (best == null || compareIsoDates(stop.startDate, best) < 0) {
+      return stop.startDate;
+    }
+
+    return best;
+  }, null);
+
+  const endDate = stops.reduce((best, stop) => {
+    if (!isIsoDate(stop.endDate)) {
+      return best;
+    }
+
+    if (best == null || compareIsoDates(best, stop.endDate) < 0) {
+      return stop.endDate;
+    }
+
+    return best;
+  }, null);
+
+  let durationLabel = `${stops.length} paradas`;
+
+  if (startDate && endDate) {
+    const start = parseUtcDate(startDate);
+    const end = parseUtcDate(endDate);
+
+    if (start && end) {
+      const daySpan = Math.max(1, Math.round((end.getTime() - start.getTime()) / 86400000) + 1);
+      durationLabel = `${daySpan} día${daySpan === 1 ? "" : "s"}`;
+    }
+  }
+
+  return {
+    name: TRIP_NAME,
+    startDate,
+    endDate,
+    dateLabel: formatDateRange(startDate, endDate),
+    stopCount: stops.length,
+    durationLabel,
+  };
+}
+
+function sortActivitiesForDashboard(left, right) {
+  const leftRank = left.status === "pending" ? 0 : 1;
+  const rightRank = right.status === "pending" ? 0 : 1;
+
+  if (leftRank !== rightRank) {
+    return leftRank - rightRank;
+  }
+
+  if (left.day !== right.day) {
+    return left.day - right.day;
+  }
+
+  if (left.time !== right.time) {
+    return String(left.time).localeCompare(String(right.time));
+  }
+
+  return String(left.id).localeCompare(String(right.id));
+}
+
+function createUpcomingEvents(activities, stopsById) {
+  return [...activities]
+    .sort(sortActivitiesForDashboard)
+    .map((activity) => {
+      const stop = stopsById.get(String(activity.stopId));
+
+      return {
+        id: activity.id,
+        stopId: activity.stopId,
+        stopName: stop ? stop.name : "Parada sin nombre",
+        day: activity.day,
+        time: activity.time,
+        status: activity.status,
+        statusLabel: activity.status === "done" ? "Completado" : "Pendiente",
+        label: `${formatDayLabel(activity.day)} · ${formatTimeLabel(activity.time)}`,
+      };
+    });
+}
+
+function createBudgetSnapshot() {
+  const summary = getBudgetSummary();
+  const ratio = summary.total > 0 ? Math.min(100, Math.max(0, (summary.spent / summary.total) * 100)) : 0;
+
+  return {
+    total: summary.total,
+    spent: summary.spent,
+    available: summary.available,
+    usagePercent: ratio,
+    usageLabel: `${Math.round(ratio)}% usado`,
+    byCategory: Object.entries(summary.byCategory)
+      .map(([category, amount]) => ({
+        category,
+        amount,
+      }))
+      .sort((left, right) => right.amount - left.amount),
+  };
+}
+
+function createPackingSnapshot() {
+  const progress = getPackingProgress();
+  const completionPercent = progress.total > 0 ? (progress.completed / progress.total) * 100 : 0;
+
+  return {
+    completed: progress.completed,
+    total: progress.total,
+    remaining: Math.max(progress.total - progress.completed, 0),
+    completionPercent,
+    completionLabel: progress.total === 0 ? "Sin pendientes" : `${progress.completed} de ${progress.total}`,
+  };
+}
+
+function createStopLookup(stops) {
+  return new Map(stops.map((stop) => [String(stop.id), stop]));
+}
+
+function createActivityLookup(activities) {
+  return new Map(activities.map((activity) => [String(activity.id), activity]));
+}
+
+function resolveFavoriteLabel(favorite, stopsById, activitiesById) {
+  if (favorite.targetType === "stop") {
+    const stop = stopsById.get(String(favorite.targetId));
+
+    return stop
+      ? `Parada: ${stop.name}`
+      : `Parada: ${String(favorite.targetId)}`;
+  }
+
+  const activity = activitiesById.get(String(favorite.targetId));
+
+  if (!activity) {
+    return `Actividad: ${String(favorite.targetId)}`;
+  }
+
+  const stop = stopsById.get(String(activity.stopId));
+  const stopName = stop ? stop.name : "Parada sin nombre";
+
+  return `Actividad: ${formatDayLabel(activity.day)} · ${formatTimeLabel(activity.time)} · ${stopName}`;
+}
+
+function resolveFavoriteDetail(favorite, stopsById, activitiesById) {
+  if (favorite.targetType === "stop") {
+    const stop = stopsById.get(String(favorite.targetId));
+
+    if (!stop) {
+      return "Marcado como favorito";
+    }
+
+    return formatDateRange(stop.startDate, stop.endDate);
+  }
+
+  const activity = activitiesById.get(String(favorite.targetId));
+
+  if (!activity) {
+    return "Marcado como favorito";
+  }
+
+  return activity.status === "done" ? "Actividad completada" : "Actividad pendiente";
+}
+
+function createFavoritesSnapshot(favorites, stopsById, activitiesById) {
+  return favorites.map((favorite) => ({
+    targetType: favorite.targetType,
+    targetId: favorite.targetId,
+    label: resolveFavoriteLabel(favorite, stopsById, activitiesById),
+    detail: resolveFavoriteDetail(favorite, stopsById, activitiesById),
+  }));
+}
+
+function resolveNoteLabel(note, stopsById) {
+  if (typeof note.day === "number") {
+    return formatDayLabel(note.day);
+  }
+
+  const stop = stopsById.get(String(note.stopId));
+
+  return stop ? stop.name : `Parada ${String(note.stopId)}`;
+}
+
+function createNotesSnapshot(notes, stopsById) {
+  return notes.map((note) => ({
+    id: note.id,
+    text: note.text,
+    day: note.day,
+    stopId: note.stopId,
+    label: resolveNoteLabel(note, stopsById),
+  }));
+}
+
+export function buildDashboardSummary() {
+  const stops = listStops();
+  const activities = listActivities();
+  const notes = listNotes();
+  const favorites = listFavorites();
+  const stopsById = createStopLookup(stops);
+  const activitiesById = createActivityLookup(activities);
+
+  return {
+    trip: createTripSummary(stops),
+    upcomingEvents: createUpcomingEvents(activities, stopsById),
+    budget: createBudgetSnapshot(),
+    packing: createPackingSnapshot(),
+    memories: {
+      favorites: createFavoritesSnapshot(favorites, stopsById, activitiesById),
+      notes: createNotesSnapshot(notes, stopsById),
+    },
+    counts: {
+      stops: stops.length,
+      activities: activities.length,
+      notes: notes.length,
+      favorites: favorites.length,
+    },
+  };
+}
+
+export function formatDashboardMoney(value) {
+  return formatInteger(value);
+}
diff --git a/src/dashboard/summary.test.mjs b/src/dashboard/summary.test.mjs
