index 0000000000000000000000000000000000000000..4113ccf7eb79a376864b445a663de249f1a45e5e
--- /dev/null
+++ b/src/dashboard/summary.test.mjs
@@ -0,0 +1,219 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createActivity } from "../itinerary/agenda/agenda.mjs";
+import { toggleFavorite } from "../memories/favorites/favorites.mjs";
+import { createNote } from "../memories/notes/notes.mjs";
+import { setTotalBudget, addExpense } from "../organization/budget/budget.mjs";
+import { addPackingItem, togglePackingItem } from "../organization/packing/packing.mjs";
+import { createStop } from "../itinerary/stops/stops.mjs";
+import { buildDashboardSummary } from "./summary.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("builds a dashboard summary from the canonical stores", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const madrid = createStop({
+    name: "Madrid",
+    startDate: "2026-09-01",
+    endDate: "2026-09-03",
+    description: "Llegada y primer paseo",
+  });
+  const sevilla = createStop({
+    name: "Sevilla",
+    startDate: "2026-09-04",
+    endDate: "2026-09-06",
+    description: "Centro histórico y tapas",
+  });
+
+  const breakfast = createActivity({
+    stopId: madrid.id,
+    day: 1,
+    time: "08:30",
+    status: "pending",
+  });
+  const museum = createActivity({
+    stopId: sevilla.id,
+    day: 4,
+    time: "19:00",
+    status: "done",
+  });
+
+  setTotalBudget(2500);
+  addExpense("transporte", 900);
+  addExpense("alojamiento", 800);
+
+  addPackingItem("Documentos");
+  const sunscreen = addPackingItem("Protector solar");
+  togglePackingItem(sunscreen.id);
+
+  createNote({
+    text: "Reservar mesa cerca de la plaza",
+    day: 1,
+  });
+  createNote({
+    text: "Buscar helado en el centro",
+    stopId: sevilla.id,
+  });
+
+  toggleFavorite("stop", madrid.id);
+  toggleFavorite("activity", breakfast.id);
+
+  const summary = buildDashboardSummary();
+
+  assert.deepEqual(summary.trip, {
+    name: "Viaje en familia",
+    startDate: "2026-09-01",
+    endDate: "2026-09-06",
+    dateLabel: "1 sep 2026 al 6 sep 2026",
+    stopCount: 2,
+    durationLabel: "6 días",
+  });
+
+  assert.deepEqual(
+    summary.upcomingEvents.map((event) => ({
+      id: event.id,
+      stopName: event.stopName,
+      label: event.label,
+      status: event.status,
+      statusLabel: event.statusLabel,
+    })),
+    [
+      {
+        id: breakfast.id,
+        stopName: "Madrid",
+        label: "Día 1 · 08:30",
+        status: "pending",
+        statusLabel: "Pendiente",
+      },
+      {
+        id: museum.id,
+        stopName: "Sevilla",
+        label: "Día 4 · 19:00",
+        status: "done",
+        statusLabel: "Completado",
+      },
+    ],
+  );
+
+  assert.equal(summary.budget.total, 2500);
+  assert.equal(summary.budget.spent, 1700);
+  assert.equal(summary.budget.available, 800);
+  assert.deepEqual(summary.budget.byCategory, [
+    { category: "transporte", amount: 900 },
+    { category: "alojamiento", amount: 800 },
+  ]);
+
+  assert.deepEqual(summary.packing, {
+    completed: 1,
+    total: 2,
+    remaining: 1,
+    completionPercent: 50,
+    completionLabel: "1 de 2",
+  });
+
+  assert.deepEqual(summary.memories.favorites, [
+    {
+      targetType: "stop",
+      targetId: madrid.id,
+      label: "Parada: Madrid",
+      detail: "1 sep 2026 al 3 sep 2026",
+    },
+    {
+      targetType: "activity",
+      targetId: breakfast.id,
+      label: "Actividad: Día 1 · 08:30 · Madrid",
+      detail: "Actividad pendiente",
+    },
+  ]);
+
+  assert.deepEqual(summary.memories.notes, [
+    {
+      id: summary.memories.notes[0].id,
+      text: "Reservar mesa cerca de la plaza",
+      day: 1,
+      stopId: undefined,
+      label: "Día 1",
+    },
+    {
+      id: summary.memories.notes[1].id,
+      text: "Buscar helado en el centro",
+      day: undefined,
+      stopId: sevilla.id,
+      label: "Sevilla",
+    },
+  ]);
+
+  assert.deepEqual(summary.counts, {
+    stops: 2,
+    activities: 2,
+    notes: 2,
+    favorites: 2,
+  });
+});
+
+test("returns empty dashboard sections when no data is stored", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const summary = buildDashboardSummary();
+
+  assert.deepEqual(summary.trip, {
+    name: "Viaje en familia",
+    startDate: null,
+    endDate: null,
+    dateLabel: "Fechas por definir",
+    stopCount: 0,
+    durationLabel: "0 días",
+  });
+  assert.deepEqual(summary.upcomingEvents, []);
+  assert.deepEqual(summary.budget, {
+    total: 0,
+    spent: 0,
+    available: 0,
+    usagePercent: 0,
+    usageLabel: "0% usado",
+    byCategory: [],
+  });
+  assert.deepEqual(summary.packing, {
+    completed: 0,
+    total: 0,
+    remaining: 0,
+    completionPercent: 0,
+    completionLabel: "Sin pendientes",
+  });
+  assert.deepEqual(summary.memories, {
+    favorites: [],
+    notes: [],
+  });
+  assert.deepEqual(summary.counts, {
+    stops: 0,
+    activities: 0,
+    notes: 0,
+    favorites: 0,
+  });
+});

diff --git a/public/app.mjs b/public/app.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..09cdf8f6969d2ca9e0749142da02b14cd5ef1e86
--- /dev/null
+++ b/public/app.mjs
@@ -0,0 +1,481 @@
+const STORAGE_KEYS = {
+  stops: "itinerary:stops",
+  agenda: "itinerary:agenda",
+  budget: "organization.budget",
+  packing: "organization:packing",
+  notes: "memories:notes",
+  favorites: "itinerary:favorites",
+};
+
+const MONTHS = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
+
+function readJSON(key, fallback) {
+  try {
+    const raw = globalThis.localStorage?.getItem(key);
+
+    if (raw == null) {
+      return fallback;
+    }
+
+    return JSON.parse(raw);
+  } catch {
+    return fallback;
+  }
+}
+
+function isIsoDate(value) {
+  return typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value);
+}
+
+function parseDate(value) {
+  if (!isIsoDate(value)) {
+    return null;
+  }
+
+  const parsed = new Date(`${value}T00:00:00Z`);
+
+  return Number.isNaN(parsed.getTime()) ? null : parsed;
+}
+
+function formatShortDate(value) {
+  const date = parseDate(value);
+
+  if (!date) {
+    return "";
+  }
+
+  return `${date.getUTCDate()} ${MONTHS[date.getUTCMonth()]} ${date.getUTCFullYear()}`;
+}
+
+function formatRange(startDate, endDate) {
+  const start = formatShortDate(startDate);
+  const end = formatShortDate(endDate);
+
+  if (start && end) {
+    if (start === end) {
+      return start;
+    }
+
+    return `${start} al ${end}`;
+  }
+
+  return "Fechas por definir";
+}
+
+function formatDayLabel(day) {
+  return `Día ${day}`;
+}
+
+function formatTimeLabel(time) {
+  return typeof time === "string" && time.trim() !== "" ? time : "Horario por definir";
+}
+
+function formatNumber(value) {
+  return new Intl.NumberFormat("es-AR", { maximumFractionDigits: 0 }).format(value);
+}
+
+function buildSummary() {
+  const rawStops = readJSON(STORAGE_KEYS.stops, []);
+  const rawActivities = readJSON(STORAGE_KEYS.agenda, []);
+  const rawBudget = readJSON(STORAGE_KEYS.budget, { total: 0, spent: 0, available: 0, byCategory: {} });
+  const rawPacking = readJSON(STORAGE_KEYS.packing, []);
+  const rawNotes = readJSON(STORAGE_KEYS.notes, []);
+  const rawFavorites = readJSON(STORAGE_KEYS.favorites, []);
+
+  const stops = Array.isArray(rawStops) ? rawStops : [];
+  const activities = Array.isArray(rawActivities) ? rawActivities : [];
+  const budget =
+    rawBudget && typeof rawBudget === "object"
+      ? rawBudget
+      : { total: 0, spent: 0, available: 0, byCategory: {} };
+  const packing = Array.isArray(rawPacking) ? rawPacking : [];
+  const notes = Array.isArray(rawNotes) ? rawNotes : [];
+  const favorites = Array.isArray(rawFavorites) ? rawFavorites : [];
+
+  const stopsById = new Map(stops.map((stop) => [String(stop.id), stop]));
+  const activitiesById = new Map(activities.map((activity) => [String(activity.id), activity]));
+
+  const sortedActivities = [...activities].sort((left, right) => {
+    const leftRank = left.status === "pending" ? 0 : 1;
+    const rightRank = right.status === "pending" ? 0 : 1;
+
+    if (leftRank !== rightRank) {
+      return leftRank - rightRank;
+    }
+
+    if (left.day !== right.day) {
+      return left.day - right.day;
+    }
+
+    return String(left.time).localeCompare(String(right.time));
+  });
+
+  const upcomingEvents = sortedActivities.map((activity) => {
+    const stop = stopsById.get(String(activity.stopId));
+
+    return {
+      id: activity.id,
+      stopName: stop ? stop.name : "Parada sin nombre",
+      label: `${formatDayLabel(activity.day)} · ${formatTimeLabel(activity.time)}`,
+      status: activity.status,
+      statusLabel: activity.status === "done" ? "Completado" : "Pendiente",
+    };
+  });
+
+  const tripStart = stops.reduce((best, stop) => {
+    if (!isIsoDate(stop.startDate)) {
+      return best;
+    }
+
+    if (best == null || stop.startDate.localeCompare(best) < 0) {
+      return stop.startDate;
+    }
+
+    return best;
+  }, null);
+
+  const tripEnd = stops.reduce((best, stop) => {
+    if (!isIsoDate(stop.endDate)) {
+      return best;
+    }
+
+    if (best == null || best.localeCompare(stop.endDate) < 0) {
+      return stop.endDate;
+    }
+
+    return best;
+  }, null);
+
+  const trip = {
+    name: "Viaje en familia",
+    startDate: tripStart,
+    endDate: tripEnd,
+    dateLabel: formatRange(tripStart, tripEnd),
+    stopCount: stops.length,
+      durationLabel:
+      tripStart && tripEnd
+        ? `${Math.max(1, Math.round((parseDate(tripEnd).getTime() - parseDate(tripStart).getTime()) / 86400000) + 1)} días`
+        : `${stops.length} paradas`,
+  };
+
+  const usagePercent = budget.total > 0 ? Math.min(100, Math.max(0, (budget.spent / budget.total) * 100)) : 0;
+  const completionPercent = packing.length > 0 ? (packing.filter((item) => item.completed).length / packing.length) * 100 : 0;
+
+  const favoriteItems = favorites.map((favorite) => {
+    if (favorite.targetType === "stop") {
+      const stop = stopsById.get(String(favorite.targetId));
+
+      return {
+        label: stop ? `Parada: ${stop.name}` : `Parada: ${favorite.targetId}`,
+        detail: stop ? formatRange(stop.startDate, stop.endDate) : "Marcado como favorito",
+      };
+    }
+
+    const activity = activitiesById.get(String(favorite.targetId));
+
+    if (!activity) {
+      return {
+        label: `Actividad: ${favorite.targetId}`,
+        detail: "Marcado como favorito",
+      };
+    }
+
+    const stop = stopsById.get(String(activity.stopId));
+
+    return {
+      label: `Actividad: ${formatDayLabel(activity.day)} · ${formatTimeLabel(activity.time)} · ${stop ? stop.name : "Parada sin nombre"}`,
+      detail: activity.status === "done" ? "Actividad completada" : "Actividad pendiente",
+    };
+  });
+
+  const noteItems = notes.map((note) => {
+    const stop = note.stopId != null ? stopsById.get(String(note.stopId)) : null;
+
+    return {
+      label: typeof note.day === "number" ? formatDayLabel(note.day) : stop ? stop.name : `Parada ${note.stopId}`,
+      text: note.text,
+    };
+  });
+
+  return {
+    trip,
+    upcomingEvents,
+    budget: {
+      total: budget.total ?? 0,
+      spent: budget.spent ?? 0,
+      available: budget.available ?? 0,
+      usagePercent,
+      byCategory: Object.entries(budget.byCategory ?? {})
+        .map(([category, amount]) => ({ category, amount }))
+        .sort((left, right) => right.amount - left.amount),
+    },
+    packing: {
+      completed: packing.filter((item) => item.completed).length,
+      total: packing.length,
+      remaining: Math.max(packing.length - packing.filter((item) => item.completed).length, 0),
+      completionPercent,
+    },
+    memories: {
+      favorites: favoriteItems,
+      notes: noteItems,
+    },
+  };
+}
+
+function createElement(tagName, className, children = []) {
+  const element = document.createElement(tagName);
+
+  if (className) {
+    element.className = className;
+  }
+
+  for (const child of children) {
+    if (child == null) {
+      continue;
+    }
+
+    element.append(child.nodeType ? child : document.createTextNode(String(child)));
+  }
+
+  return element;
+}
+
+function createStat(label, value) {
+  const container = createElement("div", "stat");
+  container.append(createElement("span", null, [label]), createElement("strong", null, [value]));
+  return container;
+}
+
+function renderEvents(events) {
+  const list = createElement("div", "events-list");
+
+  if (events.length === 0) {
+    list.append(
+      createElement("div", "empty-state", ["No hay eventos programados todavía. Agrega actividades para ver el próximo paso del viaje."]),
+    );
+    return list;
+  }
+
+  for (const event of events.slice(0, 5)) {
+    const row = createElement("article", "event-row");
+    const title = createElement("div", "event-main", [
+      createElement("div", "event-title", [event.stopName]),
+      createElement("div", "event-meta", [event.label]),
+    ]);
+    const pill = createElement("span", `status-pill${event.status === "done" ? " is-done" : ""}`, [event.statusLabel]);
+    row.append(title, pill);
+    list.append(row);
+  }
+
+  return list;
+}
+
+function renderBudget(summary) {
+  const section = createElement("section", "panel focus-card");
+  section.append(
+    createElement("h2", null, ["Presupuesto"]),
+    createElement("p", "panel-copy", ["Resumen de gasto por categoría con disponibilidad restante."]),
+  );
+
+  section.append(
+    createElement("div", "summary-grid", [
+      createElement("div", "summary-card", [createElement("span", null, ["Total"]), createElement("strong", null, [formatNumber(summary.total)])]),
+      createElement("div", "summary-card", [createElement("span", null, ["Gastado"]), createElement("strong", null, [formatNumber(summary.spent)])]),
+      createElement("div", "summary-card", [createElement("span", null, ["Disponible"]), createElement("strong", null, [formatNumber(summary.available)])]),
+    ]),
+  );
+
+  const meter = createElement("div", null, [
+    createElement("div", "progress-label", [
+      createElement("span", null, ["Uso del presupuesto"]),
+      createElement("strong", null, [`${Math.round(summary.usagePercent)}%`]),
+    ]),
+    createElement("div", "progress-track", [
+      (() => {
+        const fill = createElement("div", "progress-fill");
+        fill.style.width = `${summary.usagePercent}%`;
+        return fill;
+      })(),
+    ]),
+  ]);
+  meter.setAttribute("role", "progressbar");
+  meter.setAttribute("aria-valuemin", "0");
+  meter.setAttribute("aria-valuemax", "100");
+  meter.setAttribute("aria-valuenow", String(Math.round(summary.usagePercent)));
+  section.append(meter);
+
+  const categories = createElement("div", "category-list");
+  if (summary.byCategory.length === 0) {
+    categories.append(createElement("div", "empty-state", ["Sin gastos cargados por categoría."]));
+  } else {
+    for (const category of summary.byCategory.slice(0, 4)) {
+      categories.append(
+        createElement("article", "category-row", [
+          createElement("div", null, [
+            createElement("div", "category-title", [category.category]),
+            createElement("div", "category-meta", [formatNumber(category.amount)]),
+          ]),
+        ]),
+      );
+    }
+  }
+
+  section.append(categories);
+  return section;
+}
+
+function renderPacking(summary) {
+  const section = createElement("section", "panel focus-card");
+  section.append(
+    createElement("h2", null, ["Equipaje"]),
+    createElement("p", "panel-copy", ["Progreso del checklist con lo completado y lo pendiente."]),
+  );
+
+  section.append(
+    createElement("div", "summary-grid", [
+      createElement("div", "summary-card", [createElement("span", null, ["Completado"]), createElement("strong", null, [String(summary.completed)])]),
+      createElement("div", "summary-card", [createElement("span", null, ["Total"]), createElement("strong", null, [String(summary.total)])]),
+      createElement("div", "summary-card", [createElement("span", null, ["Pendiente"]), createElement("strong", null, [String(summary.remaining)])]),
+    ]),
+  );
+
+  const meter = createElement("div", null, [
+    createElement("div", "progress-label", [
+      createElement("span", null, ["Avance del equipaje"]),
+      createElement("strong", null, [summary.total === 0 ? "Sin pendientes" : `${Math.round(summary.completionPercent)}%`]),
+    ]),
+    createElement("div", "progress-track", [
+      (() => {
+        const fill = createElement("div", "progress-fill");
+        fill.style.width = `${summary.completionPercent}%`;
+        return fill;
+      })(),
+    ]),
+  ]);
+  meter.setAttribute("role", "progressbar");
+  meter.setAttribute("aria-valuemin", "0");
+  meter.setAttribute("aria-valuemax", "100");
+  meter.setAttribute("aria-valuenow", String(Math.round(summary.completionPercent)));
+  section.append(meter);
+
+  if (summary.total === 0) {
+    section.append(createElement("div", "empty-state", ["Todavía no hay elementos de equipaje."]));
+  }
+
+  return section;
+}
+
+function renderMemories(summary) {
+  const section = createElement("section", "panel focus-card");
+  section.append(
+    createElement("h2", null, ["Recuerdos destacados"]),
+    createElement("p", "panel-copy", ["Favoritos guardados y notas asociadas a días o paradas."]),
+  );
+
+  const split = createElement("div", "memory-split");
+
+  const favoritesGroup = createElement("div", "memory-group");
+  favoritesGroup.append(createElement("h3", null, ["Marcados como favoritos"]));
+  if (summary.favorites.length === 0) {
+    favoritesGroup.append(createElement("div", "empty-state", ["Aún no hay favoritos marcados."]));
+  } else {
+    for (const favorite of summary.favorites.slice(0, 4)) {
+      favoritesGroup.append(
+        createElement("article", "memory-row", [
+          createElement("div", "memory-title", [favorite.label]),
+          createElement("div", "memory-meta", [favorite.detail]),
+        ]),
+      );
+    }
+  }
+
+  const notesGroup = createElement("div", "memory-group");
+  notesGroup.append(createElement("h3", null, ["Notas recientes"]));
+  if (summary.notes.length === 0) {
+    notesGroup.append(createElement("div", "empty-state", ["Las notas aparecerán aquí cuando agregues recuerdos o recordatorios."]));
+  } else {
+    for (const note of summary.notes.slice(0, 4)) {
+      notesGroup.append(
+        createElement("article", "memory-row", [
+          createElement("div", "memory-title", [note.label]),
+          createElement("p", "memory-text", [note.text]),
+        ]),
+      );
+    }
+  }
+
+  split.append(favoritesGroup, notesGroup);
+  section.append(split);
+  return section;
+}
+
+function renderDashboard() {
+  const root = document.getElementById("app");
+
+  if (!root) {
+    return;
+  }
+
+  const summary = buildSummary();
+  const page = createElement("div", "dashboard");
+
+  const hero = createElement("section", "hero");
+  const heroTop = createElement("div", "hero-top");
+  const copy = createElement("div", "hero-copy", [
+    createElement("p", "eyebrow", ["Dashboard del viaje"]),
+    createElement("h1", null, [summary.trip.name]),
+    createElement("p", "hero-lead", [summary.trip.dateLabel]),
+    createElement("div", "section-meta", [
+      createElement("span", "meta-chip", [`${summary.trip.stopCount} paradas`]),
+      createElement("span", "meta-chip", [summary.trip.durationLabel]),
+    ]),
+  ]);
+  const actions = createElement("div", "hero-actions");
+  const refresh = createElement("button", "refresh-button", ["Actualizar"]);
+  refresh.type = "button";
+  refresh.addEventListener("click", renderDashboard);
+  actions.append(refresh);
+  heroTop.append(copy, actions);
+  hero.append(heroTop);
+
+  hero.append(
+    createElement("div", "hero-stats", [
+      createStat("Eventos", String(summary.upcomingEvents.length)),
+      createStat("Presupuesto", `${Math.round(summary.budget.usagePercent)}% usado`),
+      createStat("Equipaje", summary.packing.total === 0 ? "Sin pendientes" : `${summary.packing.completed}/${summary.packing.total}`),
+      createStat("Recuerdos", `${summary.memories.favorites.length + summary.memories.notes.length}`),
+    ]),
+  );
+
+  const grid = createElement("div", "dashboard-grid");
+
+  const eventsPanel = createElement("section", "panel focus-card");
+  eventsPanel.append(
+    createElement("div", "section-hero", [
+      createElement("h2", null, ["Próximos eventos"]),
+      createElement("p", "panel-copy", ["La secuencia de actividades ordenada por día y horario."]),
+    ]),
+    renderEvents(summary.upcomingEvents),
+  );
+
+  grid.append(eventsPanel, renderBudget(summary.budget));
+  grid.append(renderPacking(summary.packing), renderMemories(summary.memories));
+
+  page.append(hero, grid);
+  root.replaceChildren(page);
+}
+
+function boot() {
+  renderDashboard();
+  globalThis.addEventListener("storage", (event) => {
+    if (Object.values(STORAGE_KEYS).includes(event.key ?? "")) {
+      renderDashboard();
+    }
+  });
+}
+
+if (document.readyState === "loading") {
+  document.addEventListener("DOMContentLoaded", boot, { once: true });
+} else {
+  boot();
+}
