@@ -0,0 +1,412 @@
+:root {
+  color-scheme: dark;
+  --bg: #08111b;
+  --bg-2: #0d1a29;
+  --surface: rgba(11, 20, 34, 0.84);
+  --surface-strong: rgba(18, 29, 46, 0.96);
+  --surface-soft: rgba(255, 255, 255, 0.04);
+  --border: rgba(183, 198, 227, 0.18);
+  --border-strong: rgba(226, 233, 244, 0.28);
+  --text: #f3f7ff;
+  --muted: #9eb0c8;
+  --faint: #6f8199;
+  --accent: #ffb84d;
+  --accent-2: #7be4b5;
+  --danger: #ff7a90;
+  --shadow: 0 28px 70px rgba(0, 0, 0, 0.45);
+  --radius-xl: 28px;
+  --radius-lg: 22px;
+  --radius-md: 16px;
+  --radius-sm: 12px;
+  --max-width: 1180px;
+}
+
+*,
+*::before,
+*::after {
+  box-sizing: border-box;
+}
+
+html {
+  background:
+    radial-gradient(circle at top left, rgba(255, 184, 77, 0.18), transparent 28%),
+    radial-gradient(circle at top right, rgba(123, 228, 181, 0.16), transparent 24%),
+    linear-gradient(180deg, var(--bg) 0%, var(--bg-2) 100%);
+  min-height: 100%;
+}
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  color: var(--text);
+  font-family: "Aptos", "Segoe UI", system-ui, -apple-system, sans-serif;
+  line-height: 1.5;
+  background:
+    linear-gradient(135deg, rgba(255, 255, 255, 0.03) 0, transparent 22%),
+    linear-gradient(225deg, rgba(255, 255, 255, 0.02) 0, transparent 16%);
+}
+
+body::before {
+  content: "";
+  position: fixed;
+  inset: 0;
+  pointer-events: none;
+  background:
+    linear-gradient(transparent 0 96%, rgba(255, 255, 255, 0.03) 100%),
+    linear-gradient(90deg, transparent 0 96%, rgba(255, 255, 255, 0.03) 100%);
+  background-size: 48px 48px;
+  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.55), transparent 88%);
+}
+
+img {
+  max-width: 100%;
+  display: block;
+}
+
+button,
+a,
+[tabindex] {
+  -webkit-tap-highlight-color: transparent;
+}
+
+:focus-visible {
+  outline: 3px solid var(--accent);
+  outline-offset: 3px;
+}
+
+.skip-link {
+  position: absolute;
+  top: 0.75rem;
+  left: 0.75rem;
+  z-index: 20;
+  padding: 0.7rem 1rem;
+  border-radius: 999px;
+  background: var(--accent);
+  color: #1a1a1a;
+  text-decoration: none;
+  transform: translateY(-180%);
+  transition: transform 180ms ease;
+}
+
+.skip-link:focus {
+  transform: translateY(0);
+}
+
+.app-shell {
+  position: relative;
+  isolation: isolate;
+  width: min(100%, var(--max-width));
+  margin: 0 auto;
+  padding: 2rem clamp(1rem, 3vw, 2rem) 3rem;
+}
+
+.dashboard-shell {
+  position: relative;
+  display: grid;
+  gap: 1.25rem;
+}
+
+.dashboard-backdrop {
+  position: absolute;
+  inset: 0;
+  z-index: -1;
+  border-radius: calc(var(--radius-xl) + 12px);
+  background:
+    radial-gradient(circle at 15% 15%, rgba(255, 184, 77, 0.15), transparent 24%),
+    radial-gradient(circle at 85% 10%, rgba(123, 228, 181, 0.14), transparent 22%),
+    linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent 65%);
+  filter: blur(0.1px);
+}
+
+.hero-panel,
+.card {
+  border: 1px solid var(--border);
+  border-radius: var(--radius-xl);
+  background: linear-gradient(180deg, var(--surface) 0%, rgba(9, 17, 29, 0.92) 100%);
+  box-shadow: var(--shadow);
+  backdrop-filter: blur(18px);
+}
+
+.hero-panel {
+  padding: clamp(1.5rem, 4vw, 2.5rem);
+  overflow: hidden;
+}
+
+.eyebrow,
+.card-kicker {
+  margin: 0 0 0.7rem;
+  color: var(--accent-2);
+  text-transform: uppercase;
+  letter-spacing: 0.18em;
+  font-size: 0.76rem;
+  font-weight: 700;
+}
+
+.hero-title,
+.card-title {
+  margin: 0;
+  font-family: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
+  letter-spacing: -0.03em;
+  line-height: 1.05;
+}
+
+.hero-title {
+  font-size: clamp(2.35rem, 7vw, 4.8rem);
+  max-width: 10ch;
+}
+
+.hero-route {
+  margin: 0.85rem 0 0;
+  color: var(--text);
+  font-size: clamp(1rem, 2vw, 1.2rem);
+  max-width: 38rem;
+}
+
+.hero-dates {
+  margin: 0.4rem 0 0;
+  color: var(--muted);
+  font-size: 1rem;
+}
+
+.hero-metrics {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 0.85rem;
+  margin-top: 1.6rem;
+}
+
+.metric {
+  padding: 1rem 1.1rem;
+  border: 1px solid var(--border);
+  border-radius: var(--radius-md);
+  background: var(--surface-soft);
+}
+
+.metric-value {
+  display: block;
+  font-size: clamp(1.3rem, 2.8vw, 1.9rem);
+  font-weight: 800;
+}
+
+.metric-label {
+  display: block;
+  margin-top: 0.25rem;
+  color: var(--muted);
+  font-size: 0.92rem;
+}
+
+.dashboard-grid {
+  display: grid;
+  grid-template-columns: repeat(12, minmax(0, 1fr));
+  gap: 1rem;
+}
+
+.card {
+  grid-column: span 6;
+  padding: 1.2rem;
+  overflow: hidden;
+}
+
+.card-wide {
+  grid-column: span 12;
+}
+
+.card-title {
+  margin-bottom: 0.85rem;
+  font-size: clamp(1.55rem, 4vw, 2rem);
+}
+
+.card-copy {
+  margin: 0.75rem 0 0;
+  color: var(--muted);
+}
+
+.progress {
+  display: grid;
+  gap: 0.45rem;
+  margin-bottom: 1rem;
+}
+
+.progress-track {
+  width: 100%;
+  height: 0.8rem;
