+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createActivity, toggleActivityStatus } from "../itinerary/agenda/agenda.mjs";
+import { addExpense, setTotalBudget } from "../organization/budget/budget.mjs";
+import { toggleFavorite } from "../memories/favorites/favorites.mjs";
+import { createNote } from "../memories/notes/notes.mjs";
+import {
+  addPackingItem,
+  togglePackingItem,
+} from "../organization/packing/packing.mjs";
+import { createStop } from "../itinerary/stops/stops.mjs";
+import { createDashboardSummary } from "./summary.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("composes a dashboard summary from the canonical stores", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const madrid = createStop({
+    name: "Madrid",
+    startDate: "2026-09-01",
+    endDate: "2026-09-03",
+    description: "Llegada y primer tramo",
+  });
+  const valencia = createStop({
+    name: "Valencia",
+    startDate: "2026-09-04",
+    endDate: "2026-09-06",
+    description: "Playa y cierre del viaje",
+  });
+
+  const welcomeActivity = createActivity({
+    stopId: madrid.id,
+    day: 1,
+    time: "09:00",
+  });
+  const dinnerActivity = createActivity({
+    stopId: valencia.id,
+    day: 4,
+    time: "20:30",
+  });
+  toggleActivityStatus(dinnerActivity.id);
+
+  setTotalBudget(1200);
+  addExpense("alojamiento", 400);
+  addExpense("comida", 150);
+
+  const passport = addPackingItem("Pasaporte");
+  const charger = addPackingItem("Cargador");
+  togglePackingItem(charger.id);
+
+  const noteByStop = createNote({
+    text: "Atardecer en la terraza",
+    stopId: madrid.id,
+  });
+  const noteByDay = createNote({
+    text: "Reservar helado",
+    day: 2,
+  });
+
+  toggleFavorite("stop", madrid.id);
+  toggleFavorite("activity", welcomeActivity.id);
+
+  const summary = createDashboardSummary();
+
+  assert.deepEqual(summary.trip, {
+    name: "Viaje en Familia",
+    routeLabel: "Madrid -> Valencia",
+    startDate: "2026-09-01",
+    endDate: "2026-09-06",
+    dateLabel: "01/09/2026 - 06/09/2026",
+    stopCount: 2,
+  });
+
+  assert.deepEqual(summary.upcomingEvents, [
+    {
+      id: welcomeActivity.id,
+      stopId: madrid.id,
+      stopName: "Madrid",
+      day: 1,
+      time: "09:00",
+      status: "pending",
+      title: "Madrid",
+      subtitle: "Dia 1 - 09:00",
+    },
+  ]);
+
+  assert.deepEqual(summary.budget, {
+    total: 1200,
+    spent: 550,
+    available: 650,
+    byCategory: {
+      alojamiento: 400,
+      comida: 150,
+    },
+    usagePercent: 46,
+    categoryBreakdown: [
+      { category: "alojamiento", amount: 400 },
+      { category: "comida", amount: 150 },
+    ],
+  });
+
+  assert.deepEqual(summary.packing, {
+    completed: 1,
+    total: 2,
+    remaining: 1,
+    completionPercent: 50,
+    completionLabel: "1 de 2",
+    pendingItems: [passport.name],
+  });
+
+  assert.deepEqual(summary.memories, {
+    notesCount: 2,
+    favoritesCount: 2,
+    highlights: [
+      {
+        kind: "note",
+        title: noteByStop.text,
+        detail: "Madrid",
+      },
+      {
+        kind: "note",
+        title: noteByDay.text,
+        detail: "Dia 2",
+      },
+      {
+        kind: "favorite",
+        title: "Madrid",
+        detail: "Parada marcada",
+      },
+      {
+        kind: "favorite",
+        title: "Madrid - 09:00",
+        detail: "Actividad marcada",
+      },
+    ],
+  });
+});
+
+test("returns an empty-friendly dashboard summary when nothing is stored", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  assert.deepEqual(createDashboardSummary(), {
+    trip: {
+      name: "Viaje en Familia",
+      routeLabel: "Sin paradas todavia",
+      startDate: "",
+      endDate: "",
+      dateLabel: "Fechas por definir",
+      stopCount: 0,
+    },
+    upcomingEvents: [],
+    budget: {
+      total: 0,
+      spent: 0,
+      available: 0,
+      byCategory: {},
+      usagePercent: 0,
+      categoryBreakdown: [],
+    },
+    packing: {
+      completed: 0,
+      total: 0,
+      remaining: 0,
+      completionPercent: 0,
+      completionLabel: "0 de 0",
+      pendingItems: [],
+    },
+    memories: {
+      notesCount: 0,
+      favoritesCount: 0,
+      highlights: [],
+    },
+  });
+});

diff --git a/public/app.mjs b/public/app.mjs
