+
+test("returns an empty-friendly dashboard summary when nothing is stored", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  assert.deepEqual(createDashboardSummary(), {
+    trip: {
+      name: "Viaje en Familia",
+      routeLabel: "Sin paradas todavia",
+      startDate: "",
