+  gap: 0.2rem;
+  padding: 0.9rem 1rem;
+}
+
+.stack-item-title {
+  font-size: 0.98rem;
+}
+
+.stack-item-detail {
+  color: var(--muted);
+  font-size: 0.9rem;
+}
+
+.empty-state {
+  padding: 0.9rem 1rem;
+  color: var(--faint);
+}
+
+.balance-stats {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 0.75rem;
+  margin-bottom: 1rem;
+}
+
+.balance-stat {
+  padding: 0.95rem 1rem;
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.04);
+  border: 1px solid var(--border);
