+  background:
+    linear-gradient(135deg, rgba(255, 255, 255, 0.03) 0, transparent 22%),
+    linear-gradient(225deg, rgba(255, 255, 255, 0.02) 0, transparent 16%);
+}
+
+body::before {
+  content: "";
+  position: fixed;
+  inset: 0;
+  pointer-events: none;
+  background:
+    linear-gradient(transparent 0 96%, rgba(255, 255, 255, 0.03) 100%),
