+const STORAGE_KEYS = {
+  stops: "itinerary:stops",
+  agenda: "itinerary:agenda",
+  budget: "organization.budget",
+  packing: "organization:packing",
+  notes: "memories:notes",
+  favorites: "itinerary:favorites",
+};
+
+const DEFAULT_TRIP_NAME = "Viaje en Familia";
+
+function readJson(key, fallback) {
+  const raw = globalThis.localStorage?.getItem(key);
+
+  if (raw === null || raw === undefined) {
+    return fallback;
+  }
+
+  try {
+    return JSON.parse(raw);
+  } catch {
+    return fallback;
+  }
+}
+
+function parseIsoDate(value) {
+  if (typeof value !== "string") {
+    return null;
+  }
+
+  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
+
+  if (!match) {
+    return null;
+  }
+
+  return {
+    year: Number(match[1]),
+    month: Number(match[2]),
+    day: Number(match[3]),
+  };
+}
+
+function formatIsoDate(value) {
+  const parsed = parseIsoDate(value);
+
+  if (!parsed) {
+    return value ?? "";
+  }
+
+  return `${String(parsed.day).padStart(2, "0")}/${String(parsed.month).padStart(2, "0")}/${parsed.year}`;
+}
+
+function compareIsoDate(a, b) {
+  const left = parseIsoDate(a) ?? { year: 0, month: 0, day: 0 };
+  const right = parseIsoDate(b) ?? { year: 0, month: 0, day: 0 };
+
+  if (left.year !== right.year) {
+    return left.year - right.year;
+  }
+
+  if (left.month !== right.month) {
+    return left.month - right.month;
+  }
+
+  return left.day - right.day;
+}
+
+function compareTime(a, b) {
+  return String(a ?? "").localeCompare(String(b ?? ""), "en", {
+    numeric: true,
+    sensitivity: "base",
+  });
+}
+
+function formatMoney(amount) {
+  return new Intl.NumberFormat("es-AR", {
+    maximumFractionDigits: 0,
+  }).format(amount);
+}
+
+function buildTripSummary(stops) {
+  if (stops.length === 0) {
+    return {
+      name: DEFAULT_TRIP_NAME,
+      routeLabel: "Sin paradas todavia",
+      startDate: "",
+      endDate: "",
+      dateLabel: "Fechas por definir",
+      stopCount: 0,
+    };
+  }
+
+  const orderedStops = [...stops].sort((left, right) => {
+    const byStart = compareIsoDate(left.startDate, right.startDate);
+
+    if (byStart !== 0) {
+      return byStart;
+    }
+
+    return compareIsoDate(left.endDate, right.endDate);
+  });
+  const firstStop = orderedStops[0];
+  const lastStop = orderedStops[orderedStops.length - 1];
+
+  return {
+    name: DEFAULT_TRIP_NAME,
+    routeLabel:
+      orderedStops.length > 1 ? `${firstStop.name} -> ${lastStop.name}` : firstStop.name,
+    startDate: firstStop.startDate,
+    endDate: lastStop.endDate,
+    dateLabel:
+      firstStop.startDate === lastStop.endDate
+        ? formatIsoDate(firstStop.startDate)
+        : `${formatIsoDate(firstStop.startDate)} - ${formatIsoDate(lastStop.endDate)}`,
+    stopCount: orderedStops.length,
+  };
+}
+
+function buildUpcomingEvents(stops, activities) {
+  const stopLookup = new Map(stops.map((stop, index) => [stop.id, { ...stop, order: index }]));
+  const pendingActivities = activities.filter((activity) => activity.status === "pending");
+  const source = pendingActivities.length > 0 ? pendingActivities : activities;
+
+  return source
+    .slice()
+    .sort((left, right) => {
+      const leftStop = stopLookup.get(left.stopId);
+      const rightStop = stopLookup.get(right.stopId);
+      const leftOrder = leftStop ? leftStop.order : Number.POSITIVE_INFINITY;
+      const rightOrder = rightStop ? rightStop.order : Number.POSITIVE_INFINITY;
+
+      if (leftOrder !== rightOrder) {
+        return leftOrder - rightOrder;
+      }
+
+      const dayOrder = Number(left.day) - Number(right.day);
+
+      if (dayOrder !== 0) {
+        return dayOrder;
+      }
+
+      return compareTime(left.time, right.time);
+    })
+    .map((activity) => ({
+      id: activity.id,
+      stopId: activity.stopId,
+      stopName: stopLookup.get(activity.stopId)?.name ?? "Parada",
+      day: activity.day,
+      time: activity.time,
+      status: activity.status,
+      title: stopLookup.get(activity.stopId)?.name ?? "Parada",
+      subtitle: `Dia ${activity.day} - ${activity.time}`,
+    }));
+}
+
+function buildBudgetSummary(summary) {
+  const total = Number.isFinite(summary?.total) ? summary.total : 0;
+  const spent = Number.isFinite(summary?.spent) ? summary.spent : 0;
+  const available = Number.isFinite(summary?.available) ? summary.available : total - spent;
+  const byCategory = summary?.byCategory && typeof summary.byCategory === "object" ? summary.byCategory : {};
+  const categoryBreakdown = Object.entries(byCategory)
+    .map(([category, amount]) => ({
+      category,
+      amount: Number.isFinite(amount) ? amount : 0,
+    }))
+    .sort((left, right) => right.amount - left.amount);
+
+  return {
+    total,
+    spent,
+    available,
+    byCategory: Object.fromEntries(categoryBreakdown.map((entry) => [entry.category, entry.amount])),
+    usagePercent: total > 0 ? Math.round((spent / total) * 100) : 0,
+    categoryBreakdown,
+  };
+}
+
+function buildPackingSummary(packingItems, progress) {
+  const completed = Number.isFinite(progress?.completed) ? progress.completed : 0;
+  const total = Number.isFinite(progress?.total) ? progress.total : 0;
+
+  return {
+    completed,
+    total,
+    remaining: Math.max(total - completed, 0),
+    completionPercent: total > 0 ? Math.round((completed / total) * 100) : 0,
+    completionLabel: `${completed} de ${total}`,
+    pendingItems: packingItems.filter((item) => !item.completed).map((item) => item.name),
+  };
+}
+
+function buildMemoryHighlights(stops, activities, notes, favorites) {
+  const stopLookup = new Map(stops.map((stop) => [stop.id, stop]));
+  const activityLookup = new Map(activities.map((activity) => [activity.id, activity]));
+
+  const noteHighlights = notes.slice(0, 3).map((note) => ({
+    kind: "note",
+    title: note.text,
+    detail:
+      note.day !== undefined ? `Dia ${note.day}` : stopLookup.get(note.stopId)?.name ?? "Sin ubicacion",
+  }));
+
+  const favoriteHighlights = favorites.slice(0, 3).map((favorite) => {
+    const isStop = favorite.targetType === "stop";
+    const activity = activityLookup.get(favorite.targetId);
+    const title = isStop
+      ? stopLookup.get(favorite.targetId)?.name ?? favorite.targetId
+      : activity
+        ? `${stopLookup.get(activity.stopId)?.name ?? "Parada"} - ${activity.time}`
+        : favorite.targetId;
+
+    return {
+      kind: "favorite",
+      title,
+      detail: isStop ? "Parada marcada" : "Actividad marcada",
+    };
+  });
+
+  return {
+    notesCount: notes.length,
+    favoritesCount: favorites.length,
+    highlights: [...noteHighlights, ...favoriteHighlights],
+  };
+}
+
+function createDashboardSummary() {
+  const stops = readJson(STORAGE_KEYS.stops, []);
+  const activities = readJson(STORAGE_KEYS.agenda, []);
+  const notes = readJson(STORAGE_KEYS.notes, []);
+  const favorites = readJson(STORAGE_KEYS.favorites, []);
+  const budget = readJson(STORAGE_KEYS.budget, null);
+  const packingItems = readJson(STORAGE_KEYS.packing, []);
+  const packingProgress = {
+    completed: packingItems.filter((item) => item && item.completed).length,
+    total: packingItems.length,
+  };
+
+  return {
+    trip: buildTripSummary(stops),
+    upcomingEvents: buildUpcomingEvents(stops, activities),
+    budget: buildBudgetSummary(budget),
+    packing: buildPackingSummary(packingItems, packingProgress),
+    memories: buildMemoryHighlights(stops, activities, notes, favorites),
+  };
+}
+
+function el(tagName, className, text) {
+  const node = document.createElement(tagName);
+
+  if (className) {
+    node.className = className;
+  }
+
+  if (text !== undefined) {
+    node.textContent = text;
+  }
+
+  return node;
+}
+
+function renderProgressBar(value, label) {
+  const wrapper = el("div", "progress");
+  const track = el("div", "progress-track");
+  const fill = el("div", "progress-fill");
+
+  fill.style.width = `${Math.max(0, Math.min(100, value))}%`;
+  track.append(fill);
+  wrapper.append(track);
+
+  const meta = el("div", "progress-meta");
+  meta.textContent = label;
+  wrapper.append(meta);
+
+  return wrapper;
+}
+
+function renderSummaryList(items, emptyLabel) {
+  const list = el("ul", "stack-list");
+
+  if (!items.length) {
+    const empty = el("li", "empty-state", emptyLabel);
+    list.append(empty);
+    return list;
+  }
+
+  for (const item of items) {
+    const entry = el("li", "stack-item");
+    const title = el("strong", "stack-item-title", item.title);
+    const detail = el("span", "stack-item-detail", item.detail);
+    entry.append(title, detail);
+    list.append(entry);
+  }
+
+  return list;
+}
+
+function renderCategoryBreakdown(categoryBreakdown, spent) {
+  const list = el("div", "category-list");
+
+  if (!categoryBreakdown.length) {
+    list.append(el("p", "empty-state", "Sin categorias registradas"));
+    return list;
+  }
+
+  for (const item of categoryBreakdown) {
+    const row = el("div", "category-row");
+    const label = el("span", "category-name", item.category);
+    const amount = el("span", "category-amount", formatMoney(item.amount));
+    const bar = el("div", "category-bar");
+    const fill = el("span", "category-bar-fill");
+    fill.style.width = `${spent > 0 ? Math.max(6, Math.round((item.amount / spent) * 100)) : 0}%`;
+    bar.append(fill);
+    row.append(label, amount, bar);
+    list.append(row);
+  }
+
+  return list;
+}
+
+function renderDashboard() {
+  const summary = createDashboardSummary();
+  const app = document.getElementById("app");
+
+  if (!app) {
+    return;
+  }
+
+  app.replaceChildren();
+
+  const shell = el("div", "dashboard-shell");
+  const backdrop = el("div", "dashboard-backdrop");
+  shell.append(backdrop);
+
+  const header = el("header", "hero-panel");
+  const eyebrow = el("p", "eyebrow", "Dashboard del viaje");
+  const title = el("h1", "hero-title", summary.trip.name);
+  const route = el("p", "hero-route", summary.trip.routeLabel);
+  const dates = el("p", "hero-dates", summary.trip.dateLabel);
+
+  const metrics = el("div", "hero-metrics");
+  const stopMetric = el("div", "metric");
+  stopMetric.append(el("span", "metric-value", String(summary.trip.stopCount)), el("span", "metric-label", "paradas"));
+  const eventMetric = el("div", "metric");
+  eventMetric.append(
+    el("span", "metric-value", String(summary.upcomingEvents.length)),
+    el("span", "metric-label", "proximos eventos"),
+  );
+  const memoryMetric = el("div", "metric");
+  memoryMetric.append(
+    el("span", "metric-value", String(summary.memories.highlights.length)),
+    el("span", "metric-label", "destacados"),
+  );
+  metrics.append(stopMetric, eventMetric, memoryMetric);
+
+  header.append(eyebrow, title, route, dates, metrics);
+  shell.append(header);
+
+  const grid = el("section", "dashboard-grid");
+
+  const upcomingCard = el("article", "card card-wide");
+  upcomingCard.append(el("p", "card-kicker", "Proximos eventos"), el("h2", "card-title", "Agenda"));
+  upcomingCard.append(
+    renderProgressBar(
+      summary.upcomingEvents.length === 0 ? 0 : 100,
+      summary.upcomingEvents.length ? `${summary.upcomingEvents.length} eventos listos` : "Sin eventos cargados",
+    ),
+  );
+  upcomingCard.append(
+    renderSummaryList(
+      summary.upcomingEvents.map((event) => ({
+        title: `${event.title} - ${event.subtitle}`,
+        detail: event.status === "done" ? "Completado" : "Pendiente",
+      })),
+      "No hay eventos proximos",
+    ),
+  );
+
+  const budgetCard = el("article", "card");
+  budgetCard.append(el("p", "card-kicker", "Presupuesto"), el("h2", "card-title", "Balance"));
+  const balanceStats = el("div", "balance-stats");
+  const totalStat = el("div", "balance-stat");
+  totalStat.append(el("span", "balance-stat-value", `$${formatMoney(summary.budget.total)}`), el("span", "balance-stat-label", "total"));
+  const spentStat = el("div", "balance-stat");
+  spentStat.append(el("span", "balance-stat-value", `$${formatMoney(summary.budget.spent)}`), el("span", "balance-stat-label", "gastado"));
+  const availableStat = el("div", "balance-stat");
+  availableStat.append(el("span", "balance-stat-value", `$${formatMoney(summary.budget.available)}`), el("span", "balance-stat-label", "disponible"));
+  balanceStats.append(totalStat, spentStat, availableStat);
+  budgetCard.append(balanceStats);
+  budgetCard.append(renderProgressBar(summary.budget.usagePercent, `${summary.budget.usagePercent}% comprometido`));
+  budgetCard.append(renderCategoryBreakdown(summary.budget.categoryBreakdown, summary.budget.spent));
+
+  const packingCard = el("article", "card");
+  packingCard.append(el("p", "card-kicker", "Equipaje"), el("h2", "card-title", "Preparativos"));
+  packingCard.append(renderProgressBar(summary.packing.completionPercent, summary.packing.completionLabel));
+  const packingCopy = el("p", "card-copy", `${summary.packing.completed} completados, ${summary.packing.remaining} pendientes`);
+  packingCard.append(packingCopy);
+  packingCard.append(renderSummaryList(
+    summary.packing.pendingItems.slice(0, 3).map((item) => ({
+      title: item,
+      detail: "Pendiente de empacar",
+    })),
+    "Todo empacado",
+  ));
+
+  const memoriesCard = el("article", "card");
+  memoriesCard.append(el("p", "card-kicker", "Recuerdos"), el("h2", "card-title", "Destacados"));
+  const memoryStats = el("p", "card-copy", `${summary.memories.notesCount} notas y ${summary.memories.favoritesCount} favoritos`);
+  memoriesCard.append(memoryStats);
+  memoriesCard.append(renderSummaryList(summary.memories.highlights, "Sin recuerdos destacados"));
+
+  grid.append(upcomingCard, budgetCard, packingCard, memoriesCard);
+  shell.append(grid);
+  app.append(shell);
+}
+
+document.addEventListener("DOMContentLoaded", renderDashboard);
+globalThis.addEventListener?.("storage", renderDashboard);
