diff --git a/src/dashboard/summary.mjs b/src/dashboard/summary.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..d86d6b3773c544ca430c159d7cbe8d2dd9e2b9ee
--- /dev/null
+++ b/src/dashboard/summary.mjs
@@ -0,0 +1,307 @@
+import { listActivities } from "../itinerary/agenda/agenda.mjs";
+import { searchItinerary } from "../itinerary/search/search.mjs";
+import { listStops } from "../itinerary/stops/stops.mjs";
+import { listFavorites } from "../memories/favorites/favorites.mjs";
+import { listNotes } from "../memories/notes/notes.mjs";
+import { getBudgetSummary } from "../organization/budget/budget.mjs";
+import { getPackingProgress } from "../organization/packing/packing.mjs";
+
+export const DEFAULT_TRIP_NAME = "Viaje en familia";
+
+const MONTH_LABELS = [
+  "ene",
+  "feb",
+  "mar",
+  "abr",
+  "may",
+  "jun",
+  "jul",
+  "ago",
+  "sep",
+  "oct",
+  "nov",
+  "dic",
+];
+
+function toNumber(value) {
+  return Number.isFinite(value) ? value : 0;
+}
+
+function padNumber(value) {
+  return String(value).padStart(2, "0");
+}
+
+export function formatIsoDate(value) {
+  const text = String(value ?? "").trim();
+
+  if (text === "") {
+    return "";
+  }
+
+  const parts = text.split("-");
+
+  if (parts.length !== 3) {
+    return text;
+  }
+
+  const [year, month, day] = parts;
+  const monthIndex = Number(month) - 1;
+
+  if (
+    !Number.isInteger(monthIndex) ||
+    monthIndex < 0 ||
+    monthIndex >= MONTH_LABELS.length ||
+    !/^\d{4}$/.test(year) ||
+    !/^\d{1,2}$/.test(day)
+  ) {
+    return text;
+  }
+
+  return `${Number(day)} ${MONTH_LABELS[monthIndex]} ${year}`;
+}
+
+function formatCategoryLabel(category) {
+  return String(category ?? "")
+    .replace(/[_-]+/g, " ")
+    .trim()
+    .replace(/\s+/g, " ")
+    .replace(/^\p{L}/u, (letter) => letter.toUpperCase());
+}
+
+function formatPercent(value) {
+  return `${Math.round(value)}%`;
+}
+
+function formatDayNumber(day) {
+  const value = Number(day);
+
+  if (!Number.isFinite(value) || value <= 0) {
+    return String(day ?? "");
+  }
+
+  return `Día ${value}`;
+}
+
+function createStopIndex(stops) {
+  return new Map(stops.map((stop) => [String(stop.id), stop]));
+}
+
+function createActivityIndex(activities) {
+  return new Map(activities.map((activity) => [String(activity.id), activity]));
+}
+
+function compareSchedule(a, b) {
+  const dayCompare = String(a.day ?? "").localeCompare(String(b.day ?? ""));
+
+  if (dayCompare !== 0) {
+    return dayCompare;
+  }
+
+  return String(a.time ?? "").localeCompare(String(b.time ?? ""));
+}
+
+function buildTripSummary(stops, tripName) {
+  const firstStop = stops[0] ?? null;
+  const lastStop = stops[stops.length - 1] ?? null;
+  const name = String(tripName ?? DEFAULT_TRIP_NAME).trim() || DEFAULT_TRIP_NAME;
+  const rangeLabel =
+    firstStop && lastStop
+      ? `${formatIsoDate(firstStop.startDate)} - ${formatIsoDate(lastStop.endDate)}`
+      : "Fechas por definir";
+
+  return {
+    name,
+    rangeLabel,
+    startDate: firstStop ? firstStop.startDate : null,
+    endDate: lastStop ? lastStop.endDate : null,
+    stopCount: stops.length,
+  };
+}
+
+function buildUpcomingEvents(stops, activities, limit) {
+  const itinerary = searchItinerary("", { status: "pending" });
+  const events = [];
+  let currentStop = null;
+
+  for (const entry of itinerary) {
+    if (Object.prototype.hasOwnProperty.call(entry, "startDate")) {
+      currentStop = entry;
+      continue;
+    }
+
+    if (!Object.prototype.hasOwnProperty.call(entry, "time")) {
+      continue;
+    }
+
+    const stop = currentStop ?? stops.find((item) => String(item.id) === String(entry.stopId)) ?? null;
+
+    events.push({
+      id: entry.id,
+      stopId: entry.stopId,
+      stopName: stop ? stop.name : "Parada desconocida",
+      day: entry.day,
+      dayLabel: formatIsoDate(entry.day),
+      time: entry.time,
+      status: entry.status,
+    });
+
+    if (events.length >= limit) {
+      return events;
+    }
+  }
+
+  if (events.length > 0) {
+    return events;
+  }
+
+  return activities
+    .slice()
+    .sort(compareSchedule)
+    .slice(0, limit)
+    .map((activity) => {
+      const stop = stops.find((item) => String(item.id) === String(activity.stopId)) ?? null;
+
+      return {
+        id: activity.id,
+        stopId: activity.stopId,
+        stopName: stop ? stop.name : "Parada desconocida",
+        day: activity.day,
+        dayLabel: formatIsoDate(activity.day),
+        time: activity.time,
+        status: activity.status,
+      };
+    });
+}
+
+function buildBudgetSection(summary) {
+  const total = toNumber(summary?.total);
+  const spent = toNumber(summary?.spent);
+  const available = toNumber(summary?.available);
+  const byCategory = summary?.byCategory && typeof summary.byCategory === "object" ? summary.byCategory : {};
+  const categoryEntries = Object.entries(byCategory)
+    .map(([category, amount]) => ({
+      category,
+      label: formatCategoryLabel(category),
+      amount: toNumber(amount),
+    }))
+    .sort((a, b) => b.amount - a.amount || a.label.localeCompare(b.label, "es"));
+
+  return {
+    total,
+    spent,
+    available,
+    spentPercent: total > 0 ? Math.min(100, (spent / total) * 100) : 0,
+    byCategory: categoryEntries,
+  };
+}
+
+function buildPackingSection(progress) {
+  const completed = toNumber(progress?.completed);
+  const total = toNumber(progress?.total);
+  const remaining = Math.max(total - completed, 0);
+
+  return {
+    completed,
+    total,
+    remaining,
+    percent: total > 0 ? Math.min(100, (completed / total) * 100) : 0,
+  };
+}
+
+function buildMemorySection(notes, favorites, stops, activities) {
+  const stopIndex = createStopIndex(stops);
+  const activityIndex = createActivityIndex(activities);
+
+  const noteHighlights = notes.map((note) => {
+    const relatedStop = note.stopId ? stopIndex.get(String(note.stopId)) ?? null : null;
+
+    return {
+      kind: "note",
+      id: note.id,
+      label: note.text,
+      detail: relatedStop ? relatedStop.name : formatDayNumber(note.day),
+    };
+  });
+
+  const favoriteHighlights = favorites.map((favorite) => {
+    if (favorite.targetType === "stop") {
+      const stop = stopIndex.get(String(favorite.targetId)) ?? null;
+
+      return {
+        kind: "favorite-stop",
+        id: `${favorite.targetType}:${favorite.targetId}`,
+        label: stop ? stop.name : "Parada favorita",
+        detail: "Favorito",
+      };
+    }
+
+    const activity = activityIndex.get(String(favorite.targetId)) ?? null;
+    const stop = activity ? stopIndex.get(String(activity.stopId)) ?? null : null;
+
+    return {
+      kind: "favorite-activity",
+      id: `${favorite.targetType}:${favorite.targetId}`,
+      label:
+        activity && stop
+          ? `${activity.time} · ${stop.name}`
+          : "Actividad favorita",
+      detail: activity ? formatIsoDate(activity.day) : "Favorita",
+    };
+  });
+
+  return {
+    favorites: favoriteHighlights,
+    notes: noteHighlights,
+    highlights: [...favoriteHighlights, ...noteHighlights].slice(0, 4),
+  };
+}
+
+export function buildDashboardSummary({
+  tripName = DEFAULT_TRIP_NAME,
+  stops = [],
+  activities = [],
+  budgetSummary = null,
+  packingProgress = null,
+  notes = [],
+  favorites = [],
+} = {}) {
+  const normalizedStops = Array.isArray(stops) ? stops : [];
+  const normalizedActivities = Array.isArray(activities) ? activities : [];
+  const normalizedNotes = Array.isArray(notes) ? notes : [];
+  const normalizedFavorites = Array.isArray(favorites) ? favorites : [];
+  const trip = buildTripSummary(normalizedStops, tripName);
+  const events = buildUpcomingEvents(normalizedStops, normalizedActivities, 3);
+  const budget = buildBudgetSection(budgetSummary ?? getBudgetSummary());
+  const packing = buildPackingSection(packingProgress ?? getPackingProgress());
+  const memories = buildMemorySection(
+    normalizedNotes,
+    normalizedFavorites,
+    normalizedStops,
+    normalizedActivities,
+  );
+
+  return {
+    trip,
+    events,
+    budget,
+    packing,
+    memories,
+    emptyStates: {
+      events: "No hay eventos pendientes",
+      budget: "Presupuesto sin cargar",
+      packing: "Todavia no hay equipaje cargado",
+      memories: "Todavia no hay recuerdos destacados",
+    },
+  };
+}
+
+export function getDashboardSummary() {
+  return buildDashboardSummary({
+    stops: listStops(),
+    activities: listActivities(),
+    budgetSummary: getBudgetSummary(),
+    packingProgress: getPackingProgress(),
+    notes: listNotes(),
+    favorites: listFavorites(),
+  });
+}
