+
+  return {
+    total,
+    spent,
+    available,
+    spentPercent: total > 0 ? Math.min(100, (spent / total) * 100) : 0,
+    byCategory: Object.entries(byCategory)
+      .map(([category, amount]) => ({
+        category,
+        label: formatCategoryLabel(category),
+        amount: toNumber(amount),
+      }))
+      .sort((a, b) => b.amount - a.amount || a.label.localeCompare(b.label, "es")),
+  };
+}
+
+function buildPackingSection(progress) {
+  const completed = toNumber(progress?.completed);
+  const total = toNumber(progress?.total);
+
+  return {
+    completed,
+    total,
+    remaining: Math.max(total - completed, 0),
+    percent: total > 0 ? Math.min(100, (completed / total) * 100) : 0,
+  };
+}
+
+function buildMemorySection(notes, favorites, stops, activities) {
+  const stopIndex = createStopIndex(stops);
+  const activityIndex = createActivityIndex(activities);
+
+  const favoriteItems = favorites.map((favorite) => {
+    if (favorite.targetType === "stop") {
+      const stop = stopIndex.get(String(favorite.targetId)) ?? null;
+
+      return {
+        kind: "favorite-stop",
+        label: stop ? stop.name : "Parada favorita",
+        detail: "Favorito",
+      };
+    }
+
+    const activity = activityIndex.get(String(favorite.targetId)) ?? null;
+    const stop = activity ? stopIndex.get(String(activity.stopId)) ?? null : null;
+
+    return {
+      kind: "favorite-activity",
+      label: activity && stop ? `${activity.time} · ${stop.name}` : "Actividad favorita",
+      detail: activity ? formatIsoDate(activity.day) : "Favorita",
+    };
+  });
+
+  const noteItems = notes.map((note) => {
+    const relatedStop = note.stopId ? stopIndex.get(String(note.stopId)) ?? null : null;
+
+    return {
+      kind: "note",
+      label: note.text,
+      detail: relatedStop ? relatedStop.name : formatDayNumber(note.day),
+    };
+  });
+
+  return {
+    favorites: favoriteItems,
+    notes: noteItems,
+    highlights: [...favoriteItems, ...noteItems].slice(0, 4),
+  };
+}
+
+function getState() {
+  return {
+    stops: toArray(readJSON(STORAGE_KEYS.stops, [])),
+    activities: toArray(readJSON(STORAGE_KEYS.agenda, [])),
+    budget: readJSON(STORAGE_KEYS.budget, null),
+    packing: readJSON(STORAGE_KEYS.packing, null),
+    notes: toArray(readJSON(STORAGE_KEYS.notes, [])),
+    favorites: toArray(readJSON(STORAGE_KEYS.favorites, [])),
+  };
+}
+
+function renderList(items, emptyLabel, renderItem, listClass, itemClass) {
+  if (items.length === 0) {
+    return `<div class="empty-state">${escapeHtml(emptyLabel)}</div>`;
+  }
+
+  return `<ul class="${listClass}">${items
+    .map((item) => `<li class="${itemClass}">${renderItem(item)}</li>`)
+    .join("")}</ul>`;
+}
+
+function renderDashboard(summary) {
