+}
+
+.category-bar .track {
+  margin-top: 0.45rem;
+}
+
+.category-amount {
+  font-weight: 700;
+}
+
+.section-note {
+  color: var(--muted);
+  font-size: 0.93rem;
+}
+
+:focus-visible {
+  outline: 3px solid var(--accent-strong);
+  outline-offset: 3px;
+}
+
+@media (max-width: 960px) {
+  .dashboard-hero {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (max-width: 760px) {
+  .dashboard-shell {
+    padding-inline: 0.75rem;
+  }
+
+  .dashboard-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .dashboard-panel--wide {
+    grid-column: auto;
+  }
+
+  .budget-numbers,
+  .stat-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .budget-overview,
+  .packing-overview,
+  .panel-head {
+    align-items: start;
+    flex-direction: column;
+  }
+
+  .event-item,
+  .memory-item,
+  .category-item {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (prefers-reduced-motion: no-preference) {
+  .dashboard-hero,
+  .dashboard-panel,
+  .stat-card,
+  .event-item,
+  .memory-item,
+  .category-item {
+    transition:
+      transform 160ms ease,
+      border-color 160ms ease,
+      box-shadow 160ms ease;
+  }
+
+  .dashboard-panel:hover,
+  .stat-card:hover,
+  .event-item:hover,
+  .memory-item:hover,
+  .category-item:hover {
+    transform: translateY(-2px);
+    border-color: rgba(15, 118, 110, 0.22);
+    box-shadow: 0 14px 32px rgba(15, 23, 42, 0.08);
+  }
+}
diff --git a/src/dashboard/summary.mjs b/src/dashboard/summary.mjs
