+}
+
+.dashboard-panel {
+  padding: 1.25rem;
+}
+
+.dashboard-panel--wide {
+  grid-column: span 2;
+}
+
+.panel-head {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
