+          <h1 class="dashboard-title" id="dashboard-title">${escapeHtml(summary.trip.name)}</h1>
+          <p class="dashboard-subtitle">
+            Un tablero compacto para ver el viaje, los próximos eventos, el presupuesto, el equipaje y los recuerdos destacados en una sola pantalla.
+          </p>
+          <div class="trip-meta" aria-label="Metadatos del viaje">
+            <div class="meta-pill"><strong>Fechas</strong> ${escapeHtml(summary.trip.rangeLabel)}</div>
+            <div class="meta-pill"><strong>Paradas</strong> ${escapeHtml(summary.trip.stopCount)}</div>
+            <div class="meta-pill"><strong>Eventos</strong> ${escapeHtml(summary.events.length)}</div>
+          </div>
+        </div>
+        <aside class="hero-aside" aria-label="Resumen rápido">
+          <div class="stat-grid">
+            <div class="stat-card">
+              <div class="stat-label">Presupuesto</div>
+              <div class="stat-value">${escapeHtml(summary.budget.available)}</div>
+              <div class="stat-support">Disponible de ${escapeHtml(summary.budget.total)}</div>
+            </div>
+            <div class="stat-card">
+              <div class="stat-label">Equipaje</div>
+              <div class="stat-value">${escapeHtml(summary.packing.completed)} / ${escapeHtml(summary.packing.total)}</div>
+              <div class="stat-support">Piezas completadas</div>
+            </div>
+          </div>
+          <div class="stat-card">
+            <div class="stat-label">Próximo evento</div>
+            <div class="stat-value">${
+              summary.events[0]
+                ? escapeHtml(summary.events[0].time)
+                : "Sin pendientes"
+            }</div>
+            <div class="stat-support">${
+              summary.events[0]
+                ? `${escapeHtml(summary.events[0].stopName)} · ${escapeHtml(summary.events[0].dayLabel)}`
+                : "No hay eventos pendientes"
+            }</div>
+          </div>
+        </aside>
+      </section>
+
+      <section class="dashboard-grid" aria-label="Panel de control del viaje">
+        <article class="dashboard-panel dashboard-panel--wide" data-dashboard-section="events" aria-labelledby="events-title">
+          <div class="panel-head">
+            <h2 class="panel-title" id="events-title">Próximos eventos</h2>
+            <span class="panel-count">${escapeHtml(summary.events.length)} programados</span>
+          </div>
+          ${renderList(
+            summary.events,
+            "No hay eventos pendientes",
+            (event) => `
+              <div class="event-item">
+                <div>
+                  <h3 class="event-title">${escapeHtml(event.stopName)}</h3>
+                  <div class="event-meta">${escapeHtml(event.dayLabel)} · ${escapeHtml(event.time)}</div>
+                </div>
+                <div class="status-chip">${escapeHtml(event.statusLabel)}</div>
+              </div>
+            `,
+            "event-list",
+            "event-wrapper",
+          )}
+        </article>
+
+        <article class="dashboard-panel" data-dashboard-section="budget" aria-labelledby="budget-title">
+          <div class="panel-head">
+            <h2 class="panel-title" id="budget-title">Presupuesto</h2>
+            <span class="panel-count">${escapeHtml(formatPercent(budgetProgress))} usado</span>
+          </div>
+          <div class="budget-summary">
+            <div class="budget-numbers" aria-label="Resumen numérico del presupuesto">
+              <dl class="budget-number">
+                <dt>Total</dt>
+                <dd>${escapeHtml(summary.budget.total)}</dd>
+              </dl>
+              <dl class="budget-number">
+                <dt>Gastado</dt>
+                <dd>${escapeHtml(summary.budget.spent)}</dd>
+              </dl>
+              <dl class="budget-number">
+                <dt>Disponible</dt>
+                <dd>${escapeHtml(summary.budget.available)}</dd>
+              </dl>
+            </div>
+            <div class="track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(budgetProgress)}" aria-label="Progreso del presupuesto">
+              <div class="track-fill" style="width: ${budgetProgress}%"></div>
+            </div>
+            <div class="budget-overview">
+              <div>
+                <strong>${escapeHtml(formatPercent(budgetProgress))} del total</strong>
+                <span>Usado sobre el presupuesto fijado</span>
+              </div>
+            </div>
+            ${renderList(
+              summary.budget.byCategory,
+              "Todavía no hay gastos registrados",
+              (item) => `
+                <div class="category-item">
+                  <div class="category-name">${escapeHtml(item.label)}</div>
+                  <div class="category-amount">${escapeHtml(item.amount)}</div>
