+};
+
+const DEFAULT_TRIP_NAME = "Viaje en familia";
+const MONTH_LABELS = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
+
+function readJSON(key, fallback) {
+  const raw = globalThis.localStorage?.getItem(key);
+
+  if (raw === null || raw === undefined) {
+    return fallback;
+  }
+
+  try {
+    return JSON.parse(raw);
+  } catch {
+    return fallback;
+  }
+}
+
+function toArray(value) {
+  return Array.isArray(value) ? value : [];
+}
+
+function toNumber(value) {
+  return Number.isFinite(value) ? value : 0;
+}
+
+function formatIsoDate(value) {
+  const text = String(value ?? "").trim();
+
+  if (text === "") {
+    return "";
+  }
+
+  const parts = text.split("-");
+
+  if (parts.length !== 3) {
+    return text;
+  }
+
+  const [year, month, day] = parts;
+  const monthIndex = Number(month) - 1;
+
+  if (
+    !Number.isInteger(monthIndex) ||
+    monthIndex < 0 ||
+    monthIndex >= MONTH_LABELS.length ||
+    !/^\d{4}$/.test(year) ||
+    !/^\d{1,2}$/.test(day)
+  ) {
+    return text;
+  }
+
+  return `${Number(day)} ${MONTH_LABELS[monthIndex]} ${year}`;
+}
+
+function formatCategoryLabel(category) {
+  return String(category ?? "")
+    .replace(/[_-]+/g, " ")
+    .trim()
+    .replace(/\s+/g, " ")
+    .replace(/^\p{L}/u, (letter) => letter.toUpperCase());
+}
+
+function formatDayNumber(day) {
+  const value = Number(day);
+
+  if (!Number.isFinite(value) || value <= 0) {
+    return String(day ?? "");
+  }
+
+  return `Día ${value}`;
+}
+
+function escapeHtml(value) {
+  return String(value ?? "")
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function createStopIndex(stops) {
+  return new Map(stops.map((stop) => [String(stop.id), stop]));
+}
+
+function createActivityIndex(activities) {
+  return new Map(activities.map((activity) => [String(activity.id), activity]));
+}
+
+function compareSchedule(a, b) {
+  const dayCompare = String(a.day ?? "").localeCompare(String(b.day ?? ""));
+
+  if (dayCompare !== 0) {
+    return dayCompare;
+  }
+
+  return String(a.time ?? "").localeCompare(String(b.time ?? ""));
+}
+
+function buildTripSummary(stops) {
+  const firstStop = stops[0] ?? null;
+  const lastStop = stops[stops.length - 1] ?? null;
+
+  return {
+    name: DEFAULT_TRIP_NAME,
+    rangeLabel:
+      firstStop && lastStop
+        ? `${formatIsoDate(firstStop.startDate)} - ${formatIsoDate(lastStop.endDate)}`
+        : "Fechas por definir",
+    stopCount: stops.length,
+  };
+}
+
+function buildUpcomingEvents(stops, activities, limit) {
+  const events = [];
+  const itinerary = [];
+  let currentStop = null;
+
+  for (const stop of stops) {
+    itinerary.push(stop);
+    const matchingActivities = activities.filter((activity) => String(activity.stopId) === String(stop.id));
+
+    for (const activity of matchingActivities) {
+      itinerary.push(activity);
+    }
+  }
+
+  for (const entry of itinerary) {
+    if (Object.prototype.hasOwnProperty.call(entry, "startDate")) {
+      currentStop = entry;
+      continue;
+    }
+
+    if (entry.status !== "pending") {
+      continue;
+    }
+
+    const stop = currentStop ?? stops.find((item) => String(item.id) === String(entry.stopId)) ?? null;
+
+    events.push({
+      id: entry.id,
+      stopName: stop ? stop.name : "Parada desconocida",
+      dayLabel: formatIsoDate(entry.day),
+      time: entry.time,
+      statusLabel: "Pendiente",
+    });
+
+    if (events.length >= limit) {
+      break;
+    }
+  }
+
+  if (events.length > 0) {
+    return events;
+  }
+
+  return activities
+    .slice()
+    .sort(compareSchedule)
+    .slice(0, limit)
+    .map((activity) => {
+      const stop = stops.find((item) => String(item.id) === String(activity.stopId)) ?? null;
+
+      return {
+        id: activity.id,
+        stopName: stop ? stop.name : "Parada desconocida",
+        dayLabel: formatIsoDate(activity.day),
+        time: activity.time,
+        statusLabel: activity.status === "done" ? "Completado" : "Pendiente",
+      };
+    });
+}
+
+function buildBudgetSection(summary) {
+  const total = toNumber(summary?.total);
+  const spent = toNumber(summary?.spent);
+  const available = toNumber(summary?.available);
+  const byCategory = summary?.byCategory && typeof summary.byCategory === "object" ? summary.byCategory : {};
+
+  return {
+    total,
+    spent,
+    available,
+    spentPercent: total > 0 ? Math.min(100, (spent / total) * 100) : 0,
+    byCategory: Object.entries(byCategory)
+      .map(([category, amount]) => ({
+        category,
+        label: formatCategoryLabel(category),
+        amount: toNumber(amount),
+      }))
+      .sort((a, b) => b.amount - a.amount || a.label.localeCompare(b.label, "es")),
+  };
+}
+
+function buildPackingSection(progress) {
+  const completed = toNumber(progress?.completed);
+  const total = toNumber(progress?.total);
+
+  return {
+    completed,
+    total,
+    remaining: Math.max(total - completed, 0),
+    percent: total > 0 ? Math.min(100, (completed / total) * 100) : 0,
+  };
+}
+
+function buildMemorySection(notes, favorites, stops, activities) {
+  const stopIndex = createStopIndex(stops);
+  const activityIndex = createActivityIndex(activities);
+
+  const favoriteItems = favorites.map((favorite) => {
+    if (favorite.targetType === "stop") {
+      const stop = stopIndex.get(String(favorite.targetId)) ?? null;
+
+      return {
+        kind: "favorite-stop",
+        label: stop ? stop.name : "Parada favorita",
+        detail: "Favorito",
+      };
+    }
+
+    const activity = activityIndex.get(String(favorite.targetId)) ?? null;
+    const stop = activity ? stopIndex.get(String(activity.stopId)) ?? null : null;
+
+    return {
+      kind: "favorite-activity",
+      label: activity && stop ? `${activity.time} · ${stop.name}` : "Actividad favorita",
+      detail: activity ? formatIsoDate(activity.day) : "Favorita",
+    };
+  });
+
+  const noteItems = notes.map((note) => {
+    const relatedStop = note.stopId ? stopIndex.get(String(note.stopId)) ?? null : null;
+
+    return {
+      kind: "note",
+      label: note.text,
+      detail: relatedStop ? relatedStop.name : formatDayNumber(note.day),
+    };
+  });
+
+  return {
+    favorites: favoriteItems,
+    notes: noteItems,
+    highlights: [...favoriteItems, ...noteItems].slice(0, 4),
+  };
+}
+
+function getState() {
+  return {
+    stops: toArray(readJSON(STORAGE_KEYS.stops, [])),
+    activities: toArray(readJSON(STORAGE_KEYS.agenda, [])),
+    budget: readJSON(STORAGE_KEYS.budget, null),
+    packing: readJSON(STORAGE_KEYS.packing, null),
+    notes: toArray(readJSON(STORAGE_KEYS.notes, [])),
+    favorites: toArray(readJSON(STORAGE_KEYS.favorites, [])),
+  };
+}
+
+function renderList(items, emptyLabel, renderItem, listClass, itemClass) {
+  if (items.length === 0) {
+    return `<div class="empty-state">${escapeHtml(emptyLabel)}</div>`;
+  }
+
+  return `<ul class="${listClass}">${items
+    .map((item) => `<li class="${itemClass}">${renderItem(item)}</li>`)
+    .join("")}</ul>`;
+}
+
+function renderDashboard(summary) {
+  const budgetProgress = summary.budget.spentPercent;
+  const packingProgress = summary.packing.percent;
+
+  return `
+    <main class="dashboard-shell dashboard-main" id="dashboard-main">
+      <section class="dashboard-hero" data-dashboard-hero aria-labelledby="dashboard-title">
+        <div>
+          <p class="eyebrow">Resumen del viaje</p>
+          <h1 class="dashboard-title" id="dashboard-title">${escapeHtml(summary.trip.name)}</h1>
+          <p class="dashboard-subtitle">
+            Un tablero compacto para ver el viaje, los próximos eventos, el presupuesto, el equipaje y los recuerdos destacados en una sola pantalla.
+          </p>
+          <div class="trip-meta" aria-label="Metadatos del viaje">
+            <div class="meta-pill"><strong>Fechas</strong> ${escapeHtml(summary.trip.rangeLabel)}</div>
+            <div class="meta-pill"><strong>Paradas</strong> ${escapeHtml(summary.trip.stopCount)}</div>
+            <div class="meta-pill"><strong>Eventos</strong> ${escapeHtml(summary.events.length)}</div>
+          </div>
+        </div>
+        <aside class="hero-aside" aria-label="Resumen rápido">
+          <div class="stat-grid">
+            <div class="stat-card">
+              <div class="stat-label">Presupuesto</div>
+              <div class="stat-value">${escapeHtml(summary.budget.available)}</div>
+              <div class="stat-support">Disponible de ${escapeHtml(summary.budget.total)}</div>
+            </div>
+            <div class="stat-card">
+              <div class="stat-label">Equipaje</div>
+              <div class="stat-value">${escapeHtml(summary.packing.completed)} / ${escapeHtml(summary.packing.total)}</div>
+              <div class="stat-support">Piezas completadas</div>
+            </div>
+          </div>
+          <div class="stat-card">
+            <div class="stat-label">Próximo evento</div>
+            <div class="stat-value">${
+              summary.events[0]
+                ? escapeHtml(summary.events[0].time)
+                : "Sin pendientes"
+            }</div>
+            <div class="stat-support">${
+              summary.events[0]
+                ? `${escapeHtml(summary.events[0].stopName)} · ${escapeHtml(summary.events[0].dayLabel)}`
+                : "No hay eventos pendientes"
+            }</div>
+          </div>
+        </aside>
+      </section>
+
+      <section class="dashboard-grid" aria-label="Panel de control del viaje">
+        <article class="dashboard-panel dashboard-panel--wide" data-dashboard-section="events" aria-labelledby="events-title">
+          <div class="panel-head">
+            <h2 class="panel-title" id="events-title">Próximos eventos</h2>
+            <span class="panel-count">${escapeHtml(summary.events.length)} programados</span>
+          </div>
+          ${renderList(
+            summary.events,
+            "No hay eventos pendientes",
+            (event) => `
+              <div class="event-item">
+                <div>
+                  <h3 class="event-title">${escapeHtml(event.stopName)}</h3>
+                  <div class="event-meta">${escapeHtml(event.dayLabel)} · ${escapeHtml(event.time)}</div>
+                </div>
+                <div class="status-chip">${escapeHtml(event.statusLabel)}</div>
+              </div>
+            `,
+            "event-list",
+            "event-wrapper",
+          )}
+        </article>
+
+        <article class="dashboard-panel" data-dashboard-section="budget" aria-labelledby="budget-title">
+          <div class="panel-head">
+            <h2 class="panel-title" id="budget-title">Presupuesto</h2>
+            <span class="panel-count">${escapeHtml(formatPercent(budgetProgress))} usado</span>
+          </div>
+          <div class="budget-summary">
+            <div class="budget-numbers" aria-label="Resumen numérico del presupuesto">
+              <dl class="budget-number">
+                <dt>Total</dt>
+                <dd>${escapeHtml(summary.budget.total)}</dd>
+              </dl>
+              <dl class="budget-number">
+                <dt>Gastado</dt>
+                <dd>${escapeHtml(summary.budget.spent)}</dd>
+              </dl>
+              <dl class="budget-number">
+                <dt>Disponible</dt>
+                <dd>${escapeHtml(summary.budget.available)}</dd>
+              </dl>
+            </div>
+            <div class="track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(budgetProgress)}" aria-label="Progreso del presupuesto">
+              <div class="track-fill" style="width: ${budgetProgress}%"></div>
+            </div>
+            <div class="budget-overview">
+              <div>
+                <strong>${escapeHtml(formatPercent(budgetProgress))} del total</strong>
+                <span>Usado sobre el presupuesto fijado</span>
+              </div>
+            </div>
+            ${renderList(
+              summary.budget.byCategory,
+              "Todavía no hay gastos registrados",
+              (item) => `
+                <div class="category-item">
+                  <div class="category-name">${escapeHtml(item.label)}</div>
+                  <div class="category-amount">${escapeHtml(item.amount)}</div>
+                  <div class="category-bar">
+                    <div class="track" aria-hidden="true">
+                      <div class="track-fill" style="width: ${summary.budget.spent > 0 ? Math.min(100, (item.amount / summary.budget.spent) * 100) : 0}%"></div>
+                    </div>
+                  </div>
+                </div>
+              `,
+              "category-list",
+              "category-wrapper",
+            )}
+          </div>
+        </article>
+
+        <article class="dashboard-panel" data-dashboard-section="packing" aria-labelledby="packing-title">
+          <div class="panel-head">
+            <h2 class="panel-title" id="packing-title">Equipaje</h2>
+            <span class="panel-count">${escapeHtml(summary.packing.remaining)} pendientes</span>
+          </div>
+          <div class="packing-summary">
+            <div class="packing-overview">
+              <div>
+                <strong>${escapeHtml(summary.packing.completed)} de ${escapeHtml(summary.packing.total)}</strong>
+                <span>Ítems completos</span>
+              </div>
+            </div>
+            <div class="track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(packingProgress)}" aria-label="Progreso del equipaje">
+              <div class="track-fill" style="width: ${packingProgress}%"></div>
+            </div>
+            <div class="section-note">
+              ${summary.packing.total > 0 ? `${escapeHtml(formatPercent(packingProgress))} listo para salir.` : "Sin ítems cargados todavía."}
+            </div>
+          </div>
+        </article>
+
+        <article class="dashboard-panel dashboard-panel--wide" data-dashboard-section="memories" aria-labelledby="memories-title">
+          <div class="panel-head">
+            <h2 class="panel-title" id="memories-title">Recuerdos destacados</h2>
+            <span class="panel-count">${escapeHtml(summary.memories.highlights.length)} destacados</span>
+          </div>
+          <div class="memory-groups">
+            <div>
+              <div class="memory-group-title">Favoritos</div>
+              ${renderList(
+                summary.memories.favorites,
+                "Todavía no hay favoritos",
+                (item) => `
+                  <div class="memory-item">
+                    <div>
+                      <h3 class="memory-title">${escapeHtml(item.label)}</h3>
+                      <div class="memory-meta">${escapeHtml(item.detail)}</div>
+                    </div>
+                    <div class="memory-badge">Favorito</div>
+                  </div>
+                `,
+                "memory-list",
+                "memory-wrapper",
+              )}
+            </div>
+            <div class="memory-divider" aria-hidden="true"></div>
+            <div>
+              <div class="memory-group-title">Notas</div>
+              ${renderList(
+                summary.memories.notes,
+                "Todavía no hay notas guardadas",
+                (item) => `
+                  <div class="memory-item">
+                    <div>
+                      <h3 class="memory-title">${escapeHtml(item.label)}</h3>
+                      <div class="memory-meta">${escapeHtml(item.detail)}</div>
+                    </div>
+                    <div class="memory-badge">Nota</div>
+                  </div>
+                `,
+                "memory-list",
+                "memory-wrapper",
+              )}
+            </div>
+          </div>
+        </article>
+      </section>
+    </main>
+  `;
+}
+
+function render() {
+  const root = document.getElementById("app");
+
+  if (!root) {
+    return;
+  }
+
+  const state = getState();
+  const trip = buildTripSummary(state.stops);
+  const events = buildUpcomingEvents(state.stops, state.activities, 3);
+  const budget = buildBudgetSection(state.budget);
+  const packing = buildPackingSection(state.packing);
+  const memories = buildMemorySection(state.notes, state.favorites, state.stops, state.activities);
+
+  root.innerHTML = renderDashboard({
+    trip,
+    events,
+    budget,
+    packing,
+    memories,
+  });
+}
+
+function boot() {
+  render();
+  globalThis.addEventListener("storage", render);
+}
+
+if (document.readyState === "loading") {
+  document.addEventListener("DOMContentLoaded", boot, { once: true });
+} else {
+  boot();
+}
