+    },
+    data,
+  };
+}
+
+test("buildDashboardSummary composes the trip, agenda, budget, packing, and memories views", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const firstStop = createStop({
+    name: "Buenos Aires",
+    startDate: "2026-09-01",
