@@ -0,0 +1,234 @@
+import { subscribe } from "../src/storage/store.mjs";
+import { buildDashboardSummary } from "../src/dashboard/summary.mjs";
+
+const STORAGE_KEYS = [
+  "itinerary:stops",
+  "itinerary:agenda",
+  "organization.budget",
+  "organization:packing",
+  "itinerary:favorites",
+  "memories:notes",
+];
+
+const app = document.querySelector("#app");
+
+if (!app) {
+  throw new Error("Dashboard root element not found");
+}
+
+function escapeHtml(value) {
+  return String(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function renderEmpty(message) {
+  return `<p class="empty-state">${escapeHtml(message)}</p>`;
+}
+
+function renderEvents(events) {
+  if (events.length === 0) {
+    return renderEmpty("No hay eventos próximos cargados.");
+  }
+
+  return `
+    <ol class="stack-list">
+      ${events
+        .map(
+          (event) => `
+            <li class="stack-item">
+              <div class="stack-item__meta">
+                <span class="badge badge--soft">${escapeHtml(event.status)}</span>
+                <span class="stack-item__eyebrow">${escapeHtml(event.stopName)}</span>
+              </div>
+              <strong class="stack-item__title">${escapeHtml(event.label)}</strong>
+            </li>
+          `,
+        )
+        .join("")}
+    </ol>
+  `;
+}
+
+function renderBudget(budget) {
+  const categories = budget.categories;
+
+  return `
+    <div class="budget-summary">
+      <div class="meter">
+        <div class="meter__track" aria-hidden="true">
+          <div class="meter__fill" style="width: ${Math.max(0, Math.min(100, Math.round(budget.ratio * 100)))}%"></div>
+        </div>
+        <p class="meter__label">${escapeHtml(budget.spentLabel)} gastado de ${escapeHtml(budget.totalLabel)}</p>
+      </div>
+      <dl class="budget-stats">
+        <div>
+          <dt>Gastado</dt>
+          <dd>${escapeHtml(budget.spentLabel)}</dd>
+        </div>
+        <div>
+          <dt>Disponible</dt>
+          <dd>${escapeHtml(budget.availableLabel)}</dd>
+        </div>
+      </dl>
+      ${
+        categories.length === 0
+          ? renderEmpty("Todavía no hay gastos por categoría.")
+          : `<div class="category-list">
+              ${categories
+                .map(
+                  (category) => `
+                    <div class="category-row">
+                      <div class="category-row__top">
+                        <span>${escapeHtml(category.category)}</span>
+                        <strong>${escapeHtml(category.amount)}</strong>
+                      </div>
+                      <div class="category-row__bar">
+                        <span style="width: ${budget.spent === 0 ? 0 : Math.max(6, Math.round((category.amount / budget.spent) * 100))}%"></span>
+                      </div>
+                    </div>
+                  `,
+                )
+                .join("")}
+            </div>`
+      }
+    </div>
+  `;
+}
+
+function renderPacking(packing) {
+  const percent = packing.total === 0 ? 0 : Math.round((packing.completed / packing.total) * 100);
+
+  return `
+    <div class="packing-summary">
+      <div class="meter">
+        <div class="meter__track" aria-hidden="true">
+          <div class="meter__fill meter__fill--warm" style="width: ${percent}%"></div>
+        </div>
+        <p class="meter__label">${escapeHtml(packing.label)} completados</p>
+      </div>
+      <div class="packing-stats">
+        <span>${escapeHtml(packing.completed)} listos</span>
+        <span>${escapeHtml(packing.total)} totales</span>
+      </div>
+    </div>
+  `;
+}
+
+function renderHighlights(highlights) {
+  if (highlights.length === 0) {
+    return renderEmpty("No hay recuerdos destacados todavía.");
+  }
+
+  return `
+    <div class="highlight-grid">
+      ${highlights
+        .map(
+          (item) => `
+            <article class="highlight-card">
+              <p class="highlight-card__eyebrow">${escapeHtml(item.label)}</p>
+              <h3>${escapeHtml(item.title)}</h3>
+              <p>${escapeHtml(item.detail)}</p>
+            </article>
+          `,
+        )
+        .join("")}
+    </div>
+  `;
+}
+
+function renderDashboard() {
+  const summary = buildDashboardSummary();
+
+  app.innerHTML = `
+    <main class="shell" aria-live="polite">
+      <section class="hero panel">
+        <div class="hero__copy">
+          <p class="eyebrow">Dashboard del viaje</p>
+          <h1>${escapeHtml(summary.trip.name)}</h1>
+          <p class="hero__dates">${escapeHtml(summary.trip.label)}</p>
+        </div>
+        <div class="hero__actions">
+          <button class="action-button" type="button" data-action="refresh">Actualizar</button>
+        </div>
+        <dl class="hero__stats">
+          <div>
+            <dt>Paradas</dt>
+            <dd>${escapeHtml(summary.trip.stopCount)}</dd>
+          </div>
+          <div>
+            <dt>Actividades</dt>
+            <dd>${escapeHtml(summary.trip.activityCount)}</dd>
+          </div>
+          <div>
+            <dt>Fechas</dt>
+            <dd>${escapeHtml(summary.trip.label)}</dd>
+          </div>
+        </dl>
+      </section>
+
+      <section class="dashboard-grid">
+        <article class="panel card card--wide">
+          <div class="card__head">
+            <div>
+              <p class="eyebrow">Próximos eventos</p>
+              <h2>Agenda visible</h2>
+            </div>
+          </div>
+          ${renderEvents(summary.upcomingEvents)}
+        </article>
+
+        <article class="panel card">
+          <div class="card__head">
+            <div>
+              <p class="eyebrow">Presupuesto</p>
+              <h2>${escapeHtml(summary.budget.spentLabel)} gastados</h2>
+            </div>
+          </div>
+          ${renderBudget(summary.budget)}
+        </article>
+
+        <article class="panel card">
+          <div class="card__head">
+            <div>
+              <p class="eyebrow">Equipaje</p>
+              <h2>${escapeHtml(summary.packing.label)}</h2>
+            </div>
+          </div>
+          ${renderPacking(summary.packing)}
+        </article>
+
+        <article class="panel card card--wide">
+          <div class="card__head">
+            <div>
+              <p class="eyebrow">Recuerdos destacados</p>
+              <h2>Favoritos y notas</h2>
+            </div>
+          </div>
+          ${renderHighlights(summary.memories.highlights)}
+        </article>
+      </section>
+    </main>
+  `;
+}
+
+renderDashboard();
+
+const unsubscribe = STORAGE_KEYS.map((key) => subscribe(key, renderDashboard));
+
+app.addEventListener("click", (event) => {
+  const target = event.target;
+
+  if (target instanceof HTMLElement && target.matches("[data-action='refresh']")) {
+    renderDashboard();
+  }
+});
+
+window.addEventListener("beforeunload", () => {
+  for (const stop of unsubscribe) {
+    stop();
+  }
+});
