+  margin: 0;
+}
+
+.packing-stats {
+  color: var(--muted);
+  font-weight: 600;
+}
+
+.category-list {
+  display: grid;
+  gap: 0.85rem;
+}
+
+.category-row {
+  display: grid;
+  gap: 0.5rem;
+}
+
+.category-row__top {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 1rem;
