+}
+
+.category-row__bar span {
+  display: block;
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, rgba(242, 193, 78, 0.9), rgba(122, 227, 213, 0.88));
+}
+
+.highlight-grid {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 0.85rem;
+}
+
+.highlight-card {
+  padding: 1rem;
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.04);
+  border: 1px solid rgba(255, 255, 255, 0.08);
+}
+
+.highlight-card__eyebrow {
+  margin: 0 0 0.35rem;
+  color: var(--accent-strong);
+  font-size: 0.74rem;
+  font-weight: 800;
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+}
+
+.highlight-card h3 {
+  font-size: 1rem;
+}
+
+.highlight-card p:last-child {
+  margin: 0.4rem 0 0;
+  color: var(--muted);
+}
+
+:focus-visible {
+  outline: 3px solid var(--focus);
+  outline-offset: 3px;
+}
+
+button:focus-visible,
+a:focus-visible {
+  outline: 3px solid var(--focus);
+  outline-offset: 3px;
+}
+
+@media (max-width: 900px) {
+  .shell {
+    width: min(100vw - 1rem, 1180px);
+    padding-top: 1rem;
+  }
+
+  .hero,
+  .card {
+    padding: 1rem;
+  }
+
+  .hero {
+    grid-template-columns: 1fr;
+  }
+
+  .hero__actions {
+    justify-content: flex-start;
+  }
+
+  .hero__stats,
+  .budget-stats,
+  .highlight-grid,
+  .card {
+    grid-template-columns: 1fr;
+  }
+
+  .card,
+  .card--wide {
+    grid-column: span 12;
+  }
+}
+
+@media (max-width: 560px) {
+  .hero__copy h1 {
+    max-width: none;
+  }
+
+  .hero__stats {
+    grid-template-columns: 1fr;
+  }
+
+  .stack-item__meta {
+    align-items: flex-start;
+  }
+}
diff --git a/src/dashboard/summary.mjs b/src/dashboard/summary.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..a5a796bf74986be3bfd44038ad9f02330ccb4bed
--- /dev/null
+++ b/src/dashboard/summary.mjs
@@ -0,0 +1,224 @@
+import { getBudgetSummary } from "../organization/budget/budget.mjs";
+import { getPackingProgress } from "../organization/packing/packing.mjs";
+import { listFavorites } from "../memories/favorites/favorites.mjs";
+import { listNotes } from "../memories/notes/notes.mjs";
+import { searchItinerary } from "../itinerary/search/search.mjs";
+
+const MONTHS = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
+
+function isStopEntry(entry) {
+  return Object.prototype.hasOwnProperty.call(entry, "startDate");
+}
+
+function isActivityEntry(entry) {
+  return Object.prototype.hasOwnProperty.call(entry, "status");
+}
+
+function formatDate(value) {
+  if (typeof value !== "string") {
+    return value == null ? "" : String(value);
+  }
+
+  const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
+
+  if (!match) {
+    return value;
+  }
+
+  const year = Number(match[1]);
+  const monthIndex = Number(match[2]) - 1;
+  const day = Number(match[3]);
+
+  if (!Number.isInteger(year) || monthIndex < 0 || monthIndex >= MONTHS.length || !Number.isInteger(day)) {
+    return value;
+  }
+
+  return `${day} ${MONTHS[monthIndex]} ${year}`;
+}
+
+function formatDateRange(startDate, endDate) {
+  if (!startDate && !endDate) {
+    return "Sin fechas";
+  }
+
+  if (startDate === endDate) {
+    return formatDate(startDate);
+  }
+
+  return `${formatDate(startDate)} - ${formatDate(endDate)}`;
+}
+
+function formatCurrency(amount) {
+  return new Intl.NumberFormat("es-AR", {
+    maximumFractionDigits: 0,
+  }).format(amount);
+}
+
+function resolveTripName(stops) {
+  if (stops.length === 0) {
+    return "Viaje en familia";
+  }
+
+  if (stops.length === 1) {
+    return stops[0].name || "Viaje en familia";
+  }
+
+  const first = stops[0].name || "Inicio";
+  const last = stops[stops.length - 1].name || "Destino";
+
+  return `${first} · ${last}`;
+}
+
+function resolveTripDates(stops) {
+  if (stops.length === 0) {
+    return {
+      startDate: null,
+      endDate: null,
+      label: "Sin fechas",
+    };
+  }
+
+  const startDate = stops
+    .map((stop) => stop.startDate)
+    .filter((value) => typeof value === "string" && value !== "")
+    .sort()[0] ?? null;
+  const endDate = stops
+    .map((stop) => stop.endDate)
+    .filter((value) => typeof value === "string" && value !== "")
+    .sort()
+    .at(-1) ?? null;
+
+  return {
+    startDate,
+    endDate,
+    label: formatDateRange(startDate, endDate),
+  };
+}
+
+function buildStopIndex(stops) {
+  return new Map(stops.map((stop) => [stop.id, stop]));
+}
+
+function buildEventLabel(activity, stop) {
+  const stopLabel = stop?.name || "Parada";
+  return `${formatDate(activity.day)} · ${activity.time} · ${stopLabel}`;
+}
+
+function buildUpcomingEvents(activities, stopIndex) {
+  return activities.slice(0, 4).map((activity) => {
+    const stop = stopIndex.get(activity.stopId);
+
+    return {
+      id: activity.id,
+      stopId: activity.stopId,
+      stopName: stop?.name || "Parada",
+      day: activity.day,
+      time: activity.time,
+      status: activity.status,
+      label: buildEventLabel(activity, stop),
+    };
+  });
+}
+
+function buildBudgetCategories(byCategory) {
+  return Object.entries(byCategory)
+    .map(([category, amount]) => ({
+      category,
+      amount,
+    }))
+    .sort((left, right) => right.amount - left.amount || left.category.localeCompare(right.category));
+}
+
+function buildPackingSummary(progress) {
+  const ratio = progress.total === 0 ? 0 : progress.completed / progress.total;
+
+  return {
+    completed: progress.completed,
+    total: progress.total,
+    ratio,
+    label: progress.total === 0 ? "Sin items" : `${progress.completed}/${progress.total}`,
+  };
+}
+
+function buildMemoryHighlights(favorites, notes, stopIndex, activityIndex) {
+  const favoriteHighlights = favorites.map((favorite) => {
+    if (favorite.targetType === "stop") {
+      const stop = stopIndex.get(favorite.targetId);
+
+      return {
+        kind: "favorite-stop",
+        label: "Parada destacada",
+        title: stop?.name || "Parada favorita",
+        detail: stop ? formatDateRange(stop.startDate, stop.endDate) : favorite.targetId,
+      };
+    }
+
+    const activity = activityIndex.get(favorite.targetId);
+    const stop = activity ? stopIndex.get(activity.stopId) : null;
+
+    return {
+      kind: "favorite-activity",
+      label: "Actividad destacada",
+      title: activity ? buildEventLabel(activity, stop) : "Actividad favorita",
+      detail: activity?.status === "done" ? "Completada" : "Pendiente",
+    };
+  });
+
+  const noteHighlights = notes.map((note) => {
+    const stop = note.stopId ? stopIndex.get(note.stopId) : null;
+    const context = note.day != null ? `Día ${note.day}` : stop?.name || "Nota";
+
+    return {
+      kind: "note",
+      label: "Recuerdo",
+      title: note.text,
+      detail: context,
+    };
+  });
+
+  return [...favoriteHighlights, ...noteHighlights].slice(0, 4);
+}
+
+export function buildDashboardSummary() {
+  const itinerary = searchItinerary("", {});
+  const stops = itinerary.filter(isStopEntry);
+  const activities = itinerary.filter(isActivityEntry);
+  const stopIndex = buildStopIndex(stops);
+  const activityIndex = new Map(activities.map((activity) => [activity.id, activity]));
+  const tripDates = resolveTripDates(stops);
+  const budgetSummary = getBudgetSummary();
+  const packingProgress = getPackingProgress();
+  const favorites = listFavorites();
+  const notes = listNotes();
+
+  return {
+    trip: {
+      name: resolveTripName(stops),
+      startDate: tripDates.startDate,
+      endDate: tripDates.endDate,
+      label: tripDates.label,
+      stopCount: stops.length,
+      activityCount: activities.length,
+    },
+    upcomingEvents: buildUpcomingEvents(activities, stopIndex),
+    budget: {
+      total: budgetSummary.total,
+      spent: budgetSummary.spent,
+      available: budgetSummary.available,
+      byCategory: budgetSummary.byCategory,
+      categories: buildBudgetCategories(budgetSummary.byCategory),
+      ratio: budgetSummary.total === 0 ? 0 : budgetSummary.spent / budgetSummary.total,
+      spentLabel: formatCurrency(budgetSummary.spent),
+      totalLabel: formatCurrency(budgetSummary.total),
+      availableLabel: formatCurrency(budgetSummary.available),
+    },
+    packing: buildPackingSummary(packingProgress),
+    memories: {
+      favorites,
+      notes,
+      highlights: buildMemoryHighlights(favorites, notes, stopIndex, activityIndex),
+    },
+  };
+}
+
+export { formatDate, formatDateRange };
diff --git a/src/dashboard/summary.test.mjs b/src/dashboard/summary.test.mjs
