+}
diff --git a/src/dashboard/summary.mjs b/src/dashboard/summary.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..a5a796bf74986be3bfd44038ad9f02330ccb4bed
--- /dev/null
+++ b/src/dashboard/summary.mjs
@@ -0,0 +1,224 @@
+import { getBudgetSummary } from "../organization/budget/budget.mjs";
+import { getPackingProgress } from "../organization/packing/packing.mjs";
+import { listFavorites } from "../memories/favorites/favorites.mjs";
+import { listNotes } from "../memories/notes/notes.mjs";
+import { searchItinerary } from "../itinerary/search/search.mjs";
+
+const MONTHS = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
+
+function isStopEntry(entry) {
+  return Object.prototype.hasOwnProperty.call(entry, "startDate");
+}
+
+function isActivityEntry(entry) {
+  return Object.prototype.hasOwnProperty.call(entry, "status");
+}
+
+function formatDate(value) {
+  if (typeof value !== "string") {
+    return value == null ? "" : String(value);
+  }
+
+  const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
+
+  if (!match) {
+    return value;
+  }
+
+  const year = Number(match[1]);
+  const monthIndex = Number(match[2]) - 1;
+  const day = Number(match[3]);
+
+  if (!Number.isInteger(year) || monthIndex < 0 || monthIndex >= MONTHS.length || !Number.isInteger(day)) {
+    return value;
+  }
+
+  return `${day} ${MONTHS[monthIndex]} ${year}`;
+}
+
+function formatDateRange(startDate, endDate) {
+  if (!startDate && !endDate) {
+    return "Sin fechas";
+  }
+
+  if (startDate === endDate) {
+    return formatDate(startDate);
+  }
+
+  return `${formatDate(startDate)} - ${formatDate(endDate)}`;
+}
+
+function formatCurrency(amount) {
+  return new Intl.NumberFormat("es-AR", {
+    maximumFractionDigits: 0,
+  }).format(amount);
+}
+
+function resolveTripName(stops) {
+  if (stops.length === 0) {
+    return "Viaje en familia";
+  }
+
+  if (stops.length === 1) {
+    return stops[0].name || "Viaje en familia";
+  }
+
+  const first = stops[0].name || "Inicio";
+  const last = stops[stops.length - 1].name || "Destino";
+
+  return `${first} · ${last}`;
+}
+
+function resolveTripDates(stops) {
+  if (stops.length === 0) {
+    return {
+      startDate: null,
+      endDate: null,
+      label: "Sin fechas",
+    };
+  }
+
+  const startDate = stops
+    .map((stop) => stop.startDate)
+    .filter((value) => typeof value === "string" && value !== "")
+    .sort()[0] ?? null;
+  const endDate = stops
+    .map((stop) => stop.endDate)
+    .filter((value) => typeof value === "string" && value !== "")
+    .sort()
+    .at(-1) ?? null;
+
+  return {
+    startDate,
+    endDate,
+    label: formatDateRange(startDate, endDate),
+  };
+}
+
+function buildStopIndex(stops) {
+  return new Map(stops.map((stop) => [stop.id, stop]));
+}
+
+function buildEventLabel(activity, stop) {
+  const stopLabel = stop?.name || "Parada";
+  return `${formatDate(activity.day)} · ${activity.time} · ${stopLabel}`;
+}
+
+function buildUpcomingEvents(activities, stopIndex) {
+  return activities.slice(0, 4).map((activity) => {
+    const stop = stopIndex.get(activity.stopId);
+
+    return {
+      id: activity.id,
+      stopId: activity.stopId,
+      stopName: stop?.name || "Parada",
+      day: activity.day,
+      time: activity.time,
+      status: activity.status,
+      label: buildEventLabel(activity, stop),
+    };
+  });
+}
+
+function buildBudgetCategories(byCategory) {
+  return Object.entries(byCategory)
+    .map(([category, amount]) => ({
+      category,
+      amount,
+    }))
+    .sort((left, right) => right.amount - left.amount || left.category.localeCompare(right.category));
+}
+
+function buildPackingSummary(progress) {
+  const ratio = progress.total === 0 ? 0 : progress.completed / progress.total;
+
+  return {
+    completed: progress.completed,
+    total: progress.total,
+    ratio,
+    label: progress.total === 0 ? "Sin items" : `${progress.completed}/${progress.total}`,
+  };
+}
+
+function buildMemoryHighlights(favorites, notes, stopIndex, activityIndex) {
+  const favoriteHighlights = favorites.map((favorite) => {
+    if (favorite.targetType === "stop") {
+      const stop = stopIndex.get(favorite.targetId);
+
+      return {
+        kind: "favorite-stop",
+        label: "Parada destacada",
+        title: stop?.name || "Parada favorita",
+        detail: stop ? formatDateRange(stop.startDate, stop.endDate) : favorite.targetId,
+      };
+    }
+
+    const activity = activityIndex.get(favorite.targetId);
+    const stop = activity ? stopIndex.get(activity.stopId) : null;
+
+    return {
+      kind: "favorite-activity",
+      label: "Actividad destacada",
+      title: activity ? buildEventLabel(activity, stop) : "Actividad favorita",
+      detail: activity?.status === "done" ? "Completada" : "Pendiente",
+    };
+  });
+
+  const noteHighlights = notes.map((note) => {
+    const stop = note.stopId ? stopIndex.get(note.stopId) : null;
+    const context = note.day != null ? `Día ${note.day}` : stop?.name || "Nota";
+
+    return {
+      kind: "note",
+      label: "Recuerdo",
+      title: note.text,
+      detail: context,
+    };
+  });
+
+  return [...favoriteHighlights, ...noteHighlights].slice(0, 4);
+}
+
+export function buildDashboardSummary() {
+  const itinerary = searchItinerary("", {});
+  const stops = itinerary.filter(isStopEntry);
+  const activities = itinerary.filter(isActivityEntry);
+  const stopIndex = buildStopIndex(stops);
+  const activityIndex = new Map(activities.map((activity) => [activity.id, activity]));
+  const tripDates = resolveTripDates(stops);
+  const budgetSummary = getBudgetSummary();
+  const packingProgress = getPackingProgress();
+  const favorites = listFavorites();
+  const notes = listNotes();
+
+  return {
+    trip: {
+      name: resolveTripName(stops),
+      startDate: tripDates.startDate,
+      endDate: tripDates.endDate,
+      label: tripDates.label,
+      stopCount: stops.length,
+      activityCount: activities.length,
+    },
+    upcomingEvents: buildUpcomingEvents(activities, stopIndex),
+    budget: {
+      total: budgetSummary.total,
+      spent: budgetSummary.spent,
+      available: budgetSummary.available,
+      byCategory: budgetSummary.byCategory,
+      categories: buildBudgetCategories(budgetSummary.byCategory),
+      ratio: budgetSummary.total === 0 ? 0 : budgetSummary.spent / budgetSummary.total,
+      spentLabel: formatCurrency(budgetSummary.spent),
+      totalLabel: formatCurrency(budgetSummary.total),
+      availableLabel: formatCurrency(budgetSummary.available),
+    },
+    packing: buildPackingSummary(packingProgress),
+    memories: {
+      favorites,
+      notes,
+      highlights: buildMemoryHighlights(favorites, notes, stopIndex, activityIndex),
+    },
+  };
+}
+
+export { formatDate, formatDateRange };
diff --git a/src/dashboard/summary.test.mjs b/src/dashboard/summary.test.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..fd30a7b7916fb98b4c0cebe9f9463013bc767b66
--- /dev/null
+++ b/src/dashboard/summary.test.mjs
@@ -0,0 +1,236 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createActivity } from "../itinerary/agenda/agenda.mjs";
+import { createStop } from "../itinerary/stops/stops.mjs";
+import { addExpense, setTotalBudget } from "../organization/budget/budget.mjs";
+import { addPackingItem, togglePackingItem } from "../organization/packing/packing.mjs";
+import { toggleFavorite } from "../memories/favorites/favorites.mjs";
+import { createNote } from "../memories/notes/notes.mjs";
+import { buildDashboardSummary } from "./summary.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("buildDashboardSummary composes the trip, events, budget, packing, and memories", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const firstStop = createStop({
+    name: "Buenos Aires",
+    startDate: "2026-09-01",
+    endDate: "2026-09-02",
+    description: "Inicio del viaje",
+  });
+  const secondStop = createStop({
+    name: "Mendoza",
+    startDate: "2026-09-03",
+    endDate: "2026-09-06",
+    description: "Ruta de montaña",
+  });
+
+  const firstActivity = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-01",
+    time: "08:30",
+    status: "pending",
+  });
+  const secondActivity = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-02",
+    time: "10:00",
+    status: "done",
+  });
+  const thirdActivity = createActivity({
+    stopId: secondStop.id,
+    day: "2026-09-03",
+    time: "12:15",
+    status: "pending",
+  });
+
+  setTotalBudget(1000);
+  addExpense("transporte", 250);
+  addExpense("alojamiento", 300);
+
+  const [passport] = addPackingItem("Passport");
+  const [, socks] = addPackingItem({ name: "Socks" });
+  const [, jacket] = addPackingItem({ name: "Jacket" });
+  togglePackingItem(socks.id);
+
+  const favoriteStop = toggleFavorite("stop", secondStop.id);
+  const favoriteActivity = toggleFavorite("activity", secondActivity.id);
+
+  const noteByDay = createNote({
+    text: "Reservar almuerzo temprano",
+    day: 2,
+  });
+  const noteByStop = createNote({
+    text: "Llevar cámara",
+    stopId: firstStop.id,
+  });
+
+  const summary = buildDashboardSummary();
+
+  assert.deepEqual(summary.trip, {
+    name: "Buenos Aires · Mendoza",
+    startDate: "2026-09-01",
+    endDate: "2026-09-06",
+    label: "1 sep 2026 - 6 sep 2026",
+    stopCount: 2,
+    activityCount: 3,
+  });
+
+  assert.deepEqual(
+    summary.upcomingEvents.map(({ id, stopName, day, time, status, label }) => ({
+      id,
+      stopName,
+      day,
+      time,
+      status,
+      label,
+    })),
+    [
+      {
+        id: firstActivity.id,
+        stopName: "Buenos Aires",
+        day: "2026-09-01",
+        time: "08:30",
+        status: "pending",
+        label: "1 sep 2026 · 08:30 · Buenos Aires",
+      },
+      {
+        id: secondActivity.id,
+        stopName: "Buenos Aires",
+        day: "2026-09-02",
+        time: "10:00",
+        status: "done",
+        label: "2 sep 2026 · 10:00 · Buenos Aires",
+      },
+      {
+        id: thirdActivity.id,
+        stopName: "Mendoza",
+        day: "2026-09-03",
+        time: "12:15",
+        status: "pending",
+        label: "3 sep 2026 · 12:15 · Mendoza",
+      },
+    ],
+  );
+
+  assert.deepEqual(summary.budget, {
+    total: 1000,
+    spent: 550,
+    available: 450,
+    byCategory: {
+      transporte: 250,
+      alojamiento: 300,
+    },
+    categories: [
+      { category: "alojamiento", amount: 300 },
+      { category: "transporte", amount: 250 },
+    ],
+    ratio: 0.55,
+    spentLabel: "550",
+    totalLabel: "1000",
+    availableLabel: "450",
+  });
+
+  assert.deepEqual(summary.packing, {
+    completed: 1,
+    total: 2,
+    ratio: 0.5,
+    label: "1/2",
+  });
+
+  assert.deepEqual(summary.memories.highlights, [
+    {
+      kind: "favorite-stop",
+      label: "Parada destacada",
+      title: "Mendoza",
+      detail: "3 sep 2026 - 6 sep 2026",
+    },
+    {
+      kind: "favorite-activity",
+      label: "Actividad destacada",
+      title: "2 sep 2026 · 10:00 · Buenos Aires",
+      detail: "Completada",
+    },
+    {
+      kind: "note",
+      label: "Recuerdo",
+      title: "Reservar almuerzo temprano",
+      detail: "Día 2",
+    },
+    {
+      kind: "note",
+      label: "Recuerdo",
+      title: "Llevar cámara",
+      detail: "Buenos Aires",
+    },
+  ]);
+
+  assert.deepEqual(summary.memories.favorites, [favoriteStop, favoriteActivity]);
+  assert.deepEqual(summary.memories.notes, [noteByDay, noteByStop]);
+  assert.equal(passport.completed, false);
+  assert.equal(jacket.completed, false);
+});
+
+test("buildDashboardSummary returns an empty dashboard when there is no stored data", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  assert.deepEqual(buildDashboardSummary(), {
+    trip: {
+      name: "Viaje en familia",
+      startDate: null,
+      endDate: null,
+      label: "Sin fechas",
+      stopCount: 0,
+      activityCount: 0,
+    },
+    upcomingEvents: [],
+    budget: {
+      total: 0,
+      spent: 0,
+      available: 0,
+      byCategory: {},
+      categories: [],
+      ratio: 0,
+      spentLabel: "0",
+      totalLabel: "0",
+      availableLabel: "0",
+    },
+    packing: {
+      completed: 0,
+      total: 0,
+      ratio: 0,
+      label: "Sin items",
+    },
+    memories: {
+      favorites: [],
+      notes: [],
+      highlights: [],
+    },
+  });
+});

diff --git a/public/app.mjs b/public/app.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..f2b451f6bbcd5f89d9ba15f5e730c631bea595b1
--- /dev/null
+++ b/public/app.mjs
@@ -0,0 +1,234 @@
+import { subscribe } from "../src/storage/store.mjs";
+import { buildDashboardSummary } from "../src/dashboard/summary.mjs";
+
+const STORAGE_KEYS = [
+  "itinerary:stops",
+  "itinerary:agenda",
+  "organization.budget",
+  "organization:packing",
+  "itinerary:favorites",
+  "memories:notes",
+];
+
+const app = document.querySelector("#app");
+
+if (!app) {
+  throw new Error("Dashboard root element not found");
+}
+
+function escapeHtml(value) {
+  return String(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function renderEmpty(message) {
+  return `<p class="empty-state">${escapeHtml(message)}</p>`;
+}
+
+function renderEvents(events) {
+  if (events.length === 0) {
+    return renderEmpty("No hay eventos próximos cargados.");
+  }
+
+  return `
+    <ol class="stack-list">
+      ${events
+        .map(
+          (event) => `
+            <li class="stack-item">
+              <div class="stack-item__meta">
+                <span class="badge badge--soft">${escapeHtml(event.status)}</span>
+                <span class="stack-item__eyebrow">${escapeHtml(event.stopName)}</span>
+              </div>
+              <strong class="stack-item__title">${escapeHtml(event.label)}</strong>
+            </li>
+          `,
+        )
+        .join("")}
+    </ol>
+  `;
+}
+
+function renderBudget(budget) {
+  const categories = budget.categories;
+
+  return `
+    <div class="budget-summary">
+      <div class="meter">
+        <div class="meter__track" aria-hidden="true">
+          <div class="meter__fill" style="width: ${Math.max(0, Math.min(100, Math.round(budget.ratio * 100)))}%"></div>
+        </div>
+        <p class="meter__label">${escapeHtml(budget.spentLabel)} gastado de ${escapeHtml(budget.totalLabel)}</p>
+      </div>
+      <dl class="budget-stats">
+        <div>
+          <dt>Gastado</dt>
+          <dd>${escapeHtml(budget.spentLabel)}</dd>
+        </div>
+        <div>
+          <dt>Disponible</dt>
+          <dd>${escapeHtml(budget.availableLabel)}</dd>
+        </div>
+      </dl>
+      ${
+        categories.length === 0
+          ? renderEmpty("Todavía no hay gastos por categoría.")
+          : `<div class="category-list">
+              ${categories
+                .map(
+                  (category) => `
+                    <div class="category-row">
+                      <div class="category-row__top">
+                        <span>${escapeHtml(category.category)}</span>
+                        <strong>${escapeHtml(category.amount)}</strong>
+                      </div>
+                      <div class="category-row__bar">
+                        <span style="width: ${budget.spent === 0 ? 0 : Math.max(6, Math.round((category.amount / budget.spent) * 100))}%"></span>
+                      </div>
+                    </div>
+                  `,
+                )
+                .join("")}
+            </div>`
+      }
+    </div>
+  `;
+}
+
+function renderPacking(packing) {
+  const percent = packing.total === 0 ? 0 : Math.round((packing.completed / packing.total) * 100);
+
+  return `
+    <div class="packing-summary">
+      <div class="meter">
+        <div class="meter__track" aria-hidden="true">
+          <div class="meter__fill meter__fill--warm" style="width: ${percent}%"></div>
+        </div>
+        <p class="meter__label">${escapeHtml(packing.label)} completados</p>
+      </div>
+      <div class="packing-stats">
+        <span>${escapeHtml(packing.completed)} listos</span>
+        <span>${escapeHtml(packing.total)} totales</span>
+      </div>
+    </div>
+  `;
+}
+
+function renderHighlights(highlights) {
+  if (highlights.length === 0) {
+    return renderEmpty("No hay recuerdos destacados todavía.");
+  }
+
+  return `
+    <div class="highlight-grid">
+      ${highlights
+        .map(
+          (item) => `
+            <article class="highlight-card">
+              <p class="highlight-card__eyebrow">${escapeHtml(item.label)}</p>
+              <h3>${escapeHtml(item.title)}</h3>
+              <p>${escapeHtml(item.detail)}</p>
+            </article>
+          `,
+        )
+        .join("")}
+    </div>
+  `;
+}
+
+function renderDashboard() {
+  const summary = buildDashboardSummary();
+
+  app.innerHTML = `
+    <main class="shell" aria-live="polite">
+      <section class="hero panel">
+        <div class="hero__copy">
+          <p class="eyebrow">Dashboard del viaje</p>
+          <h1>${escapeHtml(summary.trip.name)}</h1>
+          <p class="hero__dates">${escapeHtml(summary.trip.label)}</p>
+        </div>
+        <div class="hero__actions">
+          <button class="action-button" type="button" data-action="refresh">Actualizar</button>
+        </div>
+        <dl class="hero__stats">
+          <div>
+            <dt>Paradas</dt>
+            <dd>${escapeHtml(summary.trip.stopCount)}</dd>
+          </div>
+          <div>
+            <dt>Actividades</dt>
+            <dd>${escapeHtml(summary.trip.activityCount)}</dd>
+          </div>
+          <div>
+            <dt>Fechas</dt>
+            <dd>${escapeHtml(summary.trip.label)}</dd>
+          </div>
+        </dl>
+      </section>
+
+      <section class="dashboard-grid">
+        <article class="panel card card--wide">
+          <div class="card__head">
+            <div>
+              <p class="eyebrow">Próximos eventos</p>
+              <h2>Agenda visible</h2>
+            </div>
+          </div>
+          ${renderEvents(summary.upcomingEvents)}
+        </article>
+
+        <article class="panel card">
+          <div class="card__head">
+            <div>
+              <p class="eyebrow">Presupuesto</p>
+              <h2>${escapeHtml(summary.budget.spentLabel)} gastados</h2>
+            </div>
+          </div>
+          ${renderBudget(summary.budget)}
+        </article>
+
+        <article class="panel card">
+          <div class="card__head">
+            <div>
+              <p class="eyebrow">Equipaje</p>
+              <h2>${escapeHtml(summary.packing.label)}</h2>
+            </div>
+          </div>
+          ${renderPacking(summary.packing)}
+        </article>
+
+        <article class="panel card card--wide">
+          <div class="card__head">
+            <div>
+              <p class="eyebrow">Recuerdos destacados</p>
+              <h2>Favoritos y notas</h2>
+            </div>
+          </div>
+          ${renderHighlights(summary.memories.highlights)}
+        </article>
+      </section>
+    </main>
+  `;
+}
+
+renderDashboard();
+
+const unsubscribe = STORAGE_KEYS.map((key) => subscribe(key, renderDashboard));
+
+app.addEventListener("click", (event) => {
+  const target = event.target;
+
+  if (target instanceof HTMLElement && target.matches("[data-action='refresh']")) {
+    renderDashboard();
+  }
+});
+
+window.addEventListener("beforeunload", () => {
+  for (const stop of unsubscribe) {
+    stop();
+  }
+});
diff --git a/public/index.html b/public/index.html
new file mode 100644
index 0000000000000000000000000000000000000000..e7ccc22e161e103e067b4a43bfda17534fb56677
--- /dev/null
+++ b/public/index.html
@@ -0,0 +1,18 @@
+<!doctype html>
+<html lang="es">
+  <head>
+    <meta charset="utf-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1" />
+    <meta
