+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createActivity } from "../itinerary/agenda/agenda.mjs";
+import { createStop } from "../itinerary/stops/stops.mjs";
+import { addExpense, setTotalBudget } from "../organization/budget/budget.mjs";
+import { addPackingItem, togglePackingItem } from "../organization/packing/packing.mjs";
+import { toggleFavorite } from "../memories/favorites/favorites.mjs";
+import { createNote } from "../memories/notes/notes.mjs";
+import { buildDashboardSummary } from "./summary.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("buildDashboardSummary composes the trip, events, budget, packing, and memories", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const firstStop = createStop({
+    name: "Buenos Aires",
+    startDate: "2026-09-01",
+    endDate: "2026-09-02",
+    description: "Inicio del viaje",
+  });
+  const secondStop = createStop({
+    name: "Mendoza",
+    startDate: "2026-09-03",
+    endDate: "2026-09-06",
+    description: "Ruta de montaña",
+  });
+
+  const firstActivity = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-01",
+    time: "08:30",
+    status: "pending",
+  });
+  const secondActivity = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-02",
+    time: "10:00",
+    status: "done",
+  });
+  const thirdActivity = createActivity({
+    stopId: secondStop.id,
+    day: "2026-09-03",
+    time: "12:15",
+    status: "pending",
+  });
+
+  setTotalBudget(1000);
+  addExpense("transporte", 250);
+  addExpense("alojamiento", 300);
+
+  const [passport] = addPackingItem("Passport");
+  const [, socks] = addPackingItem({ name: "Socks" });
+  const [, jacket] = addPackingItem({ name: "Jacket" });
+  togglePackingItem(socks.id);
+
+  const favoriteStop = toggleFavorite("stop", secondStop.id);
+  const favoriteActivity = toggleFavorite("activity", secondActivity.id);
+
+  const noteByDay = createNote({
+    text: "Reservar almuerzo temprano",
+    day: 2,
+  });
+  const noteByStop = createNote({
+    text: "Llevar cámara",
+    stopId: firstStop.id,
+  });
+
+  const summary = buildDashboardSummary();
+
+  assert.deepEqual(summary.trip, {
+    name: "Buenos Aires · Mendoza",
+    startDate: "2026-09-01",
+    endDate: "2026-09-06",
+    label: "1 sep 2026 - 6 sep 2026",
+    stopCount: 2,
+    activityCount: 3,
+  });
+
+  assert.deepEqual(
+    summary.upcomingEvents.map(({ id, stopName, day, time, status, label }) => ({
+      id,
+      stopName,
+      day,
+      time,
+      status,
+      label,
+    })),
+    [
+      {
+        id: firstActivity.id,
+        stopName: "Buenos Aires",
+        day: "2026-09-01",
+        time: "08:30",
+        status: "pending",
+        label: "1 sep 2026 · 08:30 · Buenos Aires",
+      },
+      {
+        id: secondActivity.id,
+        stopName: "Buenos Aires",
+        day: "2026-09-02",
+        time: "10:00",
+        status: "done",
+        label: "2 sep 2026 · 10:00 · Buenos Aires",
+      },
+      {
+        id: thirdActivity.id,
+        stopName: "Mendoza",
+        day: "2026-09-03",
+        time: "12:15",
+        status: "pending",
+        label: "3 sep 2026 · 12:15 · Mendoza",
+      },
+    ],
+  );
+
+  assert.deepEqual(summary.budget, {
+    total: 1000,
+    spent: 550,
+    available: 450,
+    byCategory: {
+      transporte: 250,
+      alojamiento: 300,
+    },
+    categories: [
+      { category: "alojamiento", amount: 300 },
+      { category: "transporte", amount: 250 },
+    ],
+    ratio: 0.55,
+    spentLabel: "550",
+    totalLabel: "1000",
+    availableLabel: "450",
+  });
+
+  assert.deepEqual(summary.packing, {
+    completed: 1,
+    total: 2,
+    ratio: 0.5,
+    label: "1/2",
+  });
+
+  assert.deepEqual(summary.memories.highlights, [
+    {
+      kind: "favorite-stop",
+      label: "Parada destacada",
+      title: "Mendoza",
+      detail: "3 sep 2026 - 6 sep 2026",
+    },
+    {
+      kind: "favorite-activity",
+      label: "Actividad destacada",
+      title: "2 sep 2026 · 10:00 · Buenos Aires",
+      detail: "Completada",
+    },
+    {
+      kind: "note",
+      label: "Recuerdo",
+      title: "Reservar almuerzo temprano",
+      detail: "Día 2",
+    },
+    {
+      kind: "note",
+      label: "Recuerdo",
+      title: "Llevar cámara",
+      detail: "Buenos Aires",
+    },
+  ]);
+
+  assert.deepEqual(summary.memories.favorites, [favoriteStop, favoriteActivity]);
+  assert.deepEqual(summary.memories.notes, [noteByDay, noteByStop]);
+  assert.equal(passport.completed, false);
+  assert.equal(jacket.completed, false);
+});
+
+test("buildDashboardSummary returns an empty dashboard when there is no stored data", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  assert.deepEqual(buildDashboardSummary(), {
+    trip: {
+      name: "Viaje en familia",
+      startDate: null,
+      endDate: null,
+      label: "Sin fechas",
+      stopCount: 0,
+      activityCount: 0,
+    },
+    upcomingEvents: [],
+    budget: {
+      total: 0,
+      spent: 0,
+      available: 0,
+      byCategory: {},
+      categories: [],
+      ratio: 0,
+      spentLabel: "0",
+      totalLabel: "0",
+      availableLabel: "0",
+    },
+    packing: {
+      completed: 0,
+      total: 0,
+      ratio: 0,
+      label: "Sin items",
+    },
+    memories: {
+      favorites: [],
+      notes: [],
+      highlights: [],
+    },
+  });
+});

