diff --git a/src/dashboard/summary.mjs b/src/dashboard/summary.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..211949aeac4d4a80812ac5f31fdea541879ce27b
--- /dev/null
+++ b/src/dashboard/summary.mjs
@@ -0,0 +1,183 @@
+import { getBudgetSummary } from "../organization/budget/budget.mjs";
+import { listActivities } from "../itinerary/agenda/agenda.mjs";
+import { listStops } from "../itinerary/stops/stops.mjs";
+import { listFavorites } from "../memories/favorites/favorites.mjs";
+import { listNotes } from "../memories/notes/notes.mjs";
+import { getPackingProgress } from "../organization/packing/packing.mjs";
+
+const DEFAULT_TRIP_NAME = "Viaje en familia";
+const DATE_FORMATTER = new Intl.DateTimeFormat("es-AR", {
+  day: "numeric",
+  month: "short",
+  year: "numeric",
+  timeZone: "UTC",
+});
+
+function formatIntegerLabel(value) {
+  return Number.isFinite(value) ? String(Math.trunc(value)) : "0";
+}
+
+function formatDateLabel(dateString) {
+  if (typeof dateString !== "string" || dateString.trim() === "") {
+    return "";
+  }
+
+  const date = new Date(`${dateString}T00:00:00Z`);
+
+  if (Number.isNaN(date.getTime())) {
+    return dateString;
+  }
+
+  return DATE_FORMATTER.format(date);
+}
+
+function buildTripSummary(stops) {
+  if (stops.length === 0) {
+    return {
+      name: DEFAULT_TRIP_NAME,
+      startDate: "",
+      endDate: "",
+      dateLabel: "Agrega paradas para ver las fechas",
+    };
+  }
+
+  const firstStop = stops[0];
+  const lastStop = stops[stops.length - 1];
+  const startDate = firstStop.startDate ?? "";
+  const endDate = lastStop.endDate ?? startDate;
+  const startLabel = formatDateLabel(startDate);
+  const endLabel = formatDateLabel(endDate);
+
+  return {
+    name: DEFAULT_TRIP_NAME,
+    startDate,
+    endDate,
+    dateLabel:
+      startLabel === endLabel
+        ? startLabel
+        : `${startLabel} - ${endLabel}`,
+  };
+}
+
+function buildBudgetSummary(summary) {
+  const categories = Object.entries(summary.byCategory).map(([category, total]) => ({
+    category,
+    total,
+    label: category,
+    totalLabel: formatIntegerLabel(total),
+  }));
+
+  return {
+    total: summary.total,
+    spent: summary.spent,
+    available: summary.available,
+    byCategory: summary.byCategory,
+    categories,
+    ratio: summary.total > 0 ? summary.spent / summary.total : 0,
+    spentLabel: formatIntegerLabel(summary.spent),
+    totalLabel: formatIntegerLabel(summary.total),
+    availableLabel: formatIntegerLabel(summary.available),
+  };
+}
+
+function buildPackingSummary(progress) {
+  return {
+    completed: progress.completed,
+    total: progress.total,
+    ratio: progress.total > 0 ? progress.completed / progress.total : 0,
+    label:
+      progress.total === 0
+        ? "0/0"
+        : `${formatIntegerLabel(progress.completed)}/${formatIntegerLabel(progress.total)}`,
+  };
+}
+
+function buildStopLookup(stops) {
+  return new Map(stops.map((stop) => [stop.id, stop]));
+}
+
+function buildUpcomingEvents(activities, stopLookup) {
+  return activities
+    .filter((activity) => activity.status === "pending")
+    .map((activity) => {
+      const stop = stopLookup.get(activity.stopId);
+      return {
+        id: activity.id,
+        stopId: activity.stopId,
+        stopName: stop?.name ?? "Parada",
+        day: activity.day,
+        time: activity.time,
+        status: activity.status,
+        label: [stop?.name, activity.time].filter(Boolean).join(" · ") || activity.id,
+      };
+    })
+    .slice(0, 4);
+}
+
+function buildMemoryHighlights(notes, favorites, stopLookup, activityLookup) {
+  const noteHighlights = notes.slice(0, 4).map((note) => {
+    const stop = note.stopId ? stopLookup.get(note.stopId) : null;
+    return {
+      kind: "note",
+      id: note.id,
+      title: note.text,
+      meta: stop ? stop.name : `Día ${note.day}`,
+    };
+  });
+
+  const favoriteHighlights = favorites.slice(0, 4).map((favorite) => {
+    if (favorite.targetType === "stop") {
+      return {
+        kind: "favorite",
+        id: favorite.targetId,
+        title: stopLookup.get(favorite.targetId)?.name ?? "Parada favorita",
+        meta: "Parada marcada",
+      };
+    }
+
+    const activity = activityLookup.get(favorite.targetId);
+
+    return {
+      kind: "favorite",
+      id: favorite.targetId,
+      title:
+        activity?.time && stopLookup.get(activity.stopId)?.name
+          ? `${stopLookup.get(activity.stopId)?.name} · ${activity.time}`
+          : activity?.time ?? "Actividad favorita",
+      meta: "Actividad marcada",
+    };
+  });
+
+  return {
+    notes: noteHighlights,
+    favorites: favoriteHighlights,
+    highlights: [...noteHighlights, ...favoriteHighlights].slice(0, 6),
+  };
+}
+
+export function getDashboardSummary() {
+  const stops = listStops();
+  const activities = listActivities();
+  const favorites = listFavorites();
+  const notes = listNotes();
+  const stopLookup = buildStopLookup(stops);
+  const activityLookup = new Map(activities.map((activity) => [activity.id, activity]));
+
+  return {
+    trip: buildTripSummary(stops),
+    upcomingEvents: buildUpcomingEvents(activities, stopLookup),
+    budget: buildBudgetSummary(getBudgetSummary()),
+    packing: buildPackingSummary(getPackingProgress()),
+    memories: buildMemoryHighlights(notes, favorites, stopLookup, activityLookup),
+  };
+}
+
+export {
+  DEFAULT_TRIP_NAME,
+  buildBudgetSummary,
+  buildMemoryHighlights,
+  buildPackingSummary,
+  buildTripSummary,
+  formatDateLabel,
+  formatIntegerLabel,
+};
diff --git a/src/dashboard/summary.test.mjs b/src/dashboard/summary.test.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..43c2439e6c40b4f64b36a0df3e5fba3bc7aa7970
--- /dev/null
+++ b/src/dashboard/summary.test.mjs
@@ -0,0 +1,312 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { addExpense, getBudgetSummary, setTotalBudget } from "../organization/budget/budget.mjs";
+import { addPackingItem, getPackingProgress, togglePackingItem } from "../organization/packing/packing.mjs";
+import { createActivity, listActivities } from "../itinerary/agenda/agenda.mjs";
+import { createStop, listStops } from "../itinerary/stops/stops.mjs";
+import { createNote, listNotes } from "../memories/notes/notes.mjs";
+import { toggleFavorite, listFavorites } from "../memories/favorites/favorites.mjs";
+import { getDashboardSummary, formatIntegerLabel, buildBudgetSummary } from "./summary.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("formats integer labels without locale separators", () => {
+  assert.equal(formatIntegerLabel(1000), "1000");
+  assert.equal(formatIntegerLabel(450), "450");
+  assert.equal(formatIntegerLabel(0), "0");
+});
+
+test("buildBudgetSummary keeps the raw numeric labels expected by the dashboard", () => {
+  assert.deepEqual(
+    buildBudgetSummary({
+      total: 1000,
+      spent: 550,
+      available: 450,
+      byCategory: {
+        transporte: 250,
+        alojamiento: 300,
+      },
+    }),
+    {
+      total: 1000,
+      spent: 550,
+      available: 450,
+      byCategory: {
+        transporte: 250,
+        alojamiento: 300,
+      },
+      categories: [
+        {
+          category: "transporte",
+          total: 250,
+          label: "transporte",
+          totalLabel: "250",
+        },
+        {
+          category: "alojamiento",
+          total: 300,
+          label: "alojamiento",
+          totalLabel: "300",
+        },
+      ],
+      ratio: 0.55,
+      spentLabel: "550",
+      totalLabel: "1000",
+      availableLabel: "450",
+    },
+  );
+});
+
+test("getDashboardSummary composes the voyage, agenda, budget, packing, and memories state", () => {
+  const localStorage = createLocalStorage();
+  globalThis.localStorage = localStorage;
+
+  const northStop = createStop({
+    name: "Cartagena",
+    startDate: "2026-09-02",
+    endDate: "2026-09-05",
+    description: "Primer tramo del viaje",
+  });
+  const southStop = createStop({
+    name: "Medellín",
+    startDate: "2026-09-06",
+    endDate: "2026-09-10",
+    description: "Segunda parada",
+  });
+
+  const departure = createActivity({
+    stopId: northStop.id,
+    day: 1,
+    time: "08:00",
+    status: "pending",
+  });
+  createActivity({
+    stopId: northStop.id,
+    day: 1,
+    time: "14:00",
+    status: "done",
+  });
+  createActivity({
+    stopId: southStop.id,
+    day: 2,
+    time: "09:15",
+    status: "pending",
+  });
+
+  setTotalBudget(1000);
+  addExpense("transporte", 250);
+  addExpense("alojamiento", 300);
+
+  const [passport] = addPackingItem("Pasaporte");
+  const [, charger] = addPackingItem("Cargador");
+  togglePackingItem(charger.id);
+
+  const firstNote = createNote({
+    text: "Mirador al atardecer",
+    day: 1,
+  });
+  createNote({
+    text: "Reservar almuerzo",
+    stopId: southStop.id,
+  });
+
+  toggleFavorite("stop", northStop.id);
+  toggleFavorite("activity", departure.id);
+
+  assert.deepEqual(listStops().map((stop) => stop.name), ["Cartagena", "Medellín"]);
+  assert.equal(listActivities().length, 3);
+  assert.equal(listNotes().length, 2);
+  assert.equal(listFavorites().length, 2);
+  assert.deepEqual(getBudgetSummary(), {
+    total: 1000,
+    spent: 550,
+    available: 450,
+    byCategory: {
+      transporte: 250,
+      alojamiento: 300,
+    },
+  });
+  assert.deepEqual(getPackingProgress(), { completed: 1, total: 2 });
+
+  assert.deepEqual(getDashboardSummary(), {
+    trip: {
+      name: "Viaje en familia",
+      startDate: "2026-09-02",
+      endDate: "2026-09-10",
+      dateLabel: "2 sept 2026 - 10 sept 2026",
+    },
