+++ b/src/dashboard/summary.test.mjs
@@ -0,0 +1,312 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { addExpense, getBudgetSummary, setTotalBudget } from "../organization/budget/budget.mjs";
+import { addPackingItem, getPackingProgress, togglePackingItem } from "../organization/packing/packing.mjs";
+import { createActivity, listActivities } from "../itinerary/agenda/agenda.mjs";
+import { createStop, listStops } from "../itinerary/stops/stops.mjs";
+import { createNote, listNotes } from "../memories/notes/notes.mjs";
+import { toggleFavorite, listFavorites } from "../memories/favorites/favorites.mjs";
+import { getDashboardSummary, formatIntegerLabel, buildBudgetSummary } from "./summary.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("formats integer labels without locale separators", () => {
+  assert.equal(formatIntegerLabel(1000), "1000");
+  assert.equal(formatIntegerLabel(450), "450");
+  assert.equal(formatIntegerLabel(0), "0");
