+:root {
+  color-scheme: light;
+  --bg: #f2e8d9;
+  --bg-soft: #f8f1e8;
+  --panel: rgba(255, 252, 247, 0.9);
+  --panel-strong: #ffffff;
+  --ink: #172027;
+  --muted: #5a6772;
+  --line: rgba(23, 32, 39, 0.12);
+  --accent: #0f766e;
+  --accent-strong: #094b45;
+  --accent-warm: #b45309;
