+}
+
+.hero__copy {
+  position: relative;
+  z-index: 1;
+}
+
+.hero h1,
+.panel h2,
+.memory-card__title {
+  margin: 0;
+  line-height: 1.05;
+  letter-spacing: -0.03em;
+}
+
+.hero h1 {
+  font-family: "Georgia", "Times New Roman", serif;
+  font-size: clamp(2.8rem, 5vw, 5.4rem);
+  max-width: 10ch;
+}
+
+.hero__dates {
+  margin: 14px 0 0;
+  color: var(--muted);
+  font-size: 1.02rem;
+}
+
+.eyebrow {
+  margin: 0 0 10px;
+  color: var(--accent-strong);
+  text-transform: uppercase;
+  letter-spacing: 0.18em;
+  font-size: 0.72rem;
+  font-weight: 700;
+}
+
+.hero__metrics {
+  display: grid;
+  gap: 14px;
+  align-content: end;
+  position: relative;
+  z-index: 1;
+}
+
+.metric {
+  background: var(--panel-strong);
+  border-radius: var(--radius-lg);
+  padding: 18px;
+  border: 1px solid rgba(23, 32, 39, 0.08);
+}
+
+.metric__label,
+.metric__detail,
+.panel__copy,
+.panel__empty,
+.event-card__meta,
+.memory-card__meta {
+  color: var(--muted);
+}
+
+.metric__label {
+  display: block;
+  font-size: 0.85rem;
+  margin-bottom: 10px;
+}
+
+.metric__value {
+  display: block;
+  font-size: clamp(2rem, 4vw, 3rem);
+  line-height: 1;
+}
+
+.metric__detail {
+  display: block;
+  margin-top: 8px;
+  font-size: 0.92rem;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(12, minmax(0, 1fr));
+  gap: 20px;
+}
+
+.panel--events {
+  grid-column: span 5;
+}
+
+.panel--budget {
+  grid-column: span 7;
+}
+
+.panel--packing {
+  grid-column: span 4;
+}
+
+.panel--memories {
+  grid-column: span 8;
+}
+
+.panel {
+  padding: 22px;
+}
+
+.panel__header {
+  display: flex;
+  align-items: start;
+  justify-content: space-between;
+  gap: 14px;
+  margin-bottom: 16px;
+}
+
+.panel__header h2 {
+  font-size: 1.3rem;
+}
+
+.pill {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  padding: 8px 12px;
+  border-radius: 999px;
+  background: var(--accent-soft);
+  color: var(--accent-strong);
+  font-size: 0.82rem;
+  font-weight: 700;
+  white-space: nowrap;
+}
+
+.events-list,
+.stat-list {
+  list-style: none;
+  padding: 0;
+  margin: 0;
+}
+
+.events-list {
+  display: grid;
+  gap: 12px;
+}
+
+.event-card,
+.stat-row {
+  border: 1px solid var(--line);
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.72);
+}
+
+.event-card {
+  padding: 14px 16px;
+  display: grid;
+  gap: 6px;
+}
+
+.event-card__day {
+  color: var(--accent-strong);
+  font-size: 0.78rem;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  font-weight: 700;
+}
+
+.event-card__title {
+  font-size: 1rem;
+}
+
+.event-card__meta {
+  font-size: 0.9rem;
+}
+
+.event-card--empty {
+  color: var(--muted);
+  background: transparent;
+  border-style: dashed;
+}
+
+.progress {
+  width: 100%;
+  height: 12px;
+  border-radius: 999px;
+  background: rgba(23, 32, 39, 0.08);
+  overflow: hidden;
+  margin-bottom: 16px;
+}
+
+.progress span {
+  display: block;
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent) 0%, #159085 100%);
+}
+
+.progress--packing span {
+  background: linear-gradient(90deg, var(--accent-warm) 0%, #d97706 100%);
+}
+
+.stats {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 12px;
+  margin: 0 0 16px;
+}
+
+.stats > div {
+  padding: 16px;
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.72);
+  border: 1px solid var(--line);
+}
+
+.stats dt {
