+++ b/src/dashboard/summary.mjs
@@ -0,0 +1,183 @@
+import { getBudgetSummary } from "../organization/budget/budget.mjs";
+import { listActivities } from "../itinerary/agenda/agenda.mjs";
+import { listStops } from "../itinerary/stops/stops.mjs";
+import { listFavorites } from "../memories/favorites/favorites.mjs";
+import { listNotes } from "../memories/notes/notes.mjs";
+import { getPackingProgress } from "../organization/packing/packing.mjs";
+
+const DEFAULT_TRIP_NAME = "Viaje en familia";
+const DATE_FORMATTER = new Intl.DateTimeFormat("es-AR", {
+  day: "numeric",
+  month: "short",
+  year: "numeric",
+  timeZone: "UTC",
+});
+
+function formatIntegerLabel(value) {
+  return Number.isFinite(value) ? String(Math.trunc(value)) : "0";
+}
+
+function formatDateLabel(dateString) {
+  if (typeof dateString !== "string" || dateString.trim() === "") {
+    return "";
+  }
+
+  const date = new Date(`${dateString}T00:00:00Z`);
+
+  if (Number.isNaN(date.getTime())) {
+    return dateString;
+  }
+
+  return DATE_FORMATTER.format(date);
+}
+
+function buildTripSummary(stops) {
+  if (stops.length === 0) {
+    return {
+      name: DEFAULT_TRIP_NAME,
+      startDate: "",
+      endDate: "",
+      dateLabel: "Agrega paradas para ver las fechas",
+    };
+  }
+
+  const firstStop = stops[0];
+  const lastStop = stops[stops.length - 1];
+  const startDate = firstStop.startDate ?? "";
+  const endDate = lastStop.endDate ?? startDate;
+  const startLabel = formatDateLabel(startDate);
+  const endLabel = formatDateLabel(endDate);
+
+  return {
+    name: DEFAULT_TRIP_NAME,
+    startDate,
+    endDate,
+    dateLabel:
+      startLabel === endLabel
+        ? startLabel
+        : `${startLabel} - ${endLabel}`,
+  };
+}
+
+function buildBudgetSummary(summary) {
+  const categories = Object.entries(summary.byCategory).map(([category, total]) => ({
+    category,
+    total,
+    label: category,
+    totalLabel: formatIntegerLabel(total),
+  }));
+
+  return {
+    total: summary.total,
+    spent: summary.spent,
+    available: summary.available,
+    byCategory: summary.byCategory,
+    categories,
+    ratio: summary.total > 0 ? summary.spent / summary.total : 0,
+    spentLabel: formatIntegerLabel(summary.spent),
+    totalLabel: formatIntegerLabel(summary.total),
+    availableLabel: formatIntegerLabel(summary.available),
+  };
+}
+
+function buildPackingSummary(progress) {
+  return {
+    completed: progress.completed,
+    total: progress.total,
+    ratio: progress.total > 0 ? progress.completed / progress.total : 0,
+    label:
+      progress.total === 0
+        ? "0/0"
+        : `${formatIntegerLabel(progress.completed)}/${formatIntegerLabel(progress.total)}`,
+  };
+}
+
+function buildStopLookup(stops) {
+  return new Map(stops.map((stop) => [stop.id, stop]));
+}
+
+function buildUpcomingEvents(activities, stopLookup) {
+  return activities
+    .filter((activity) => activity.status === "pending")
+    .map((activity) => {
+      const stop = stopLookup.get(activity.stopId);
+      return {
+        id: activity.id,
+        stopId: activity.stopId,
+        stopName: stop?.name ?? "Parada",
+        day: activity.day,
+        time: activity.time,
+        status: activity.status,
+        label: [stop?.name, activity.time].filter(Boolean).join(" · ") || activity.id,
+      };
+    })
+    .slice(0, 4);
+}
+
+function buildMemoryHighlights(notes, favorites, stopLookup, activityLookup) {
+  const noteHighlights = notes.slice(0, 4).map((note) => {
+    const stop = note.stopId ? stopLookup.get(note.stopId) : null;
+    return {
+      kind: "note",
+      id: note.id,
+      title: note.text,
+      meta: stop ? stop.name : `Día ${note.day}`,
+    };
+  });
+
+  const favoriteHighlights = favorites.slice(0, 4).map((favorite) => {
+    if (favorite.targetType === "stop") {
+      return {
+        kind: "favorite",
+        id: favorite.targetId,
+        title: stopLookup.get(favorite.targetId)?.name ?? "Parada favorita",
+        meta: "Parada marcada",
+      };
+    }
+
+    const activity = activityLookup.get(favorite.targetId);
+
+    return {
+      kind: "favorite",
+      id: favorite.targetId,
+      title:
+        activity?.time && stopLookup.get(activity.stopId)?.name
+          ? `${stopLookup.get(activity.stopId)?.name} · ${activity.time}`
+          : activity?.time ?? "Actividad favorita",
+      meta: "Actividad marcada",
+    };
+  });
+
+  return {
+    notes: noteHighlights,
+    favorites: favoriteHighlights,
+    highlights: [...noteHighlights, ...favoriteHighlights].slice(0, 6),
+  };
+}
+
+export function getDashboardSummary() {
+  const stops = listStops();
+  const activities = listActivities();
+  const favorites = listFavorites();
+  const notes = listNotes();
+  const stopLookup = buildStopLookup(stops);
+  const activityLookup = new Map(activities.map((activity) => [activity.id, activity]));
+
+  return {
+    trip: buildTripSummary(stops),
+    upcomingEvents: buildUpcomingEvents(activities, stopLookup),
+    budget: buildBudgetSummary(getBudgetSummary()),
+    packing: buildPackingSummary(getPackingProgress()),
+    memories: buildMemoryHighlights(notes, favorites, stopLookup, activityLookup),
+  };
+}
+
+export {
+  DEFAULT_TRIP_NAME,
+  buildBudgetSummary,
+  buildMemoryHighlights,
+  buildPackingSummary,
+  buildTripSummary,
+  formatDateLabel,
+  formatIntegerLabel,
+};
