@@ -0,0 +1,408 @@
+const STORAGE_KEYS = {
+  budget: "organization.budget",
+  packing: "organization:packing",
+  agenda: "itinerary:agenda",
+  stops: "itinerary:stops",
+  notes: "memories:notes",
+  favorites: "itinerary:favorites",
+};
+
+const DEFAULT_TRIP_NAME = "Viaje en familia";
+const DATE_FORMATTER = new Intl.DateTimeFormat("es-AR", {
+  day: "numeric",
+  month: "short",
+  year: "numeric",
+  timeZone: "UTC",
+});
+
+function readStoredValue(key) {
+  const raw = globalThis.localStorage?.getItem(key);
+  if (raw == null) {
+    return null;
+  }
+
+  try {
+    return JSON.parse(raw);
+  } catch {
+    return null;
+  }
+}
+
+function formatIntegerLabel(value) {
+  return Number.isFinite(value) ? String(Math.trunc(value)) : "0";
+}
+
+function formatDateLabel(dateString) {
+  if (typeof dateString !== "string" || dateString.trim() === "") {
+    return "";
+  }
+
+  const date = new Date(`${dateString}T00:00:00Z`);
+
+  if (Number.isNaN(date.getTime())) {
+    return dateString;
+  }
+
+  return DATE_FORMATTER.format(date);
+}
+
+function normalizeStops() {
+  const stops = readStoredValue(STORAGE_KEYS.stops);
+
+  return Array.isArray(stops)
+    ? stops.map((stop) => ({
+        id: String(stop.id),
+        name: stop.name,
+        startDate: stop.startDate,
+        endDate: stop.endDate,
+        description: stop.description,
+      }))
+    : [];
+}
+
+function normalizeActivities() {
+  const activities = readStoredValue(STORAGE_KEYS.agenda);
+
+  return Array.isArray(activities)
+    ? activities.map((activity) => ({
+        id: String(activity.id),
+        stopId: String(activity.stopId),
+        day: activity.day,
+        time: activity.time,
+        status: activity.status,
+      }))
+    : [];
+}
+
+function normalizeBudget() {
+  const budget = readStoredValue(STORAGE_KEYS.budget);
+
+  return {
+    total: Number.isFinite(budget?.total) ? budget.total : 0,
+    spent: Number.isFinite(budget?.spent) ? budget.spent : 0,
+    available: Number.isFinite(budget?.available) ? budget.available : 0,
+    byCategory:
+      budget && typeof budget.byCategory === "object" && budget.byCategory !== null
+        ? Object.fromEntries(
+            Object.entries(budget.byCategory).map(([category, value]) => [
+              category,
+              Number.isFinite(value) ? value : 0,
+            ]),
+          )
+        : {},
+  };
+}
+
+function normalizePacking() {
+  const items = readStoredValue(STORAGE_KEYS.packing);
+
+  if (!Array.isArray(items)) {
+    return { completed: 0, total: 0 };
+  }
+
+  return {
+    completed: items.filter((item) => item && item.completed).length,
+    total: items.length,
+  };
+}
+
+function normalizeNotes() {
+  const notes = readStoredValue(STORAGE_KEYS.notes);
+
+  return Array.isArray(notes)
+    ? notes.map((note) => ({
+        id: String(note.id),
+        text: note.text,
+        day: note.day,
+        stopId: note.stopId,
+      }))
+    : [];
+}
+
+function normalizeFavorites() {
+  const favorites = readStoredValue(STORAGE_KEYS.favorites);
+
+  return Array.isArray(favorites)
+    ? favorites.map((favorite) => ({
+        targetType: favorite.targetType,
+        targetId: String(favorite.targetId),
+      }))
+    : [];
+}
+
+function buildTripSummary(stops) {
+  if (stops.length === 0) {
+    return {
+      name: DEFAULT_TRIP_NAME,
+      startDate: "",
+      endDate: "",
+      dateLabel: "Agrega paradas para ver las fechas",
+    };
+  }
+
+  const firstStop = stops[0];
+  const lastStop = stops[stops.length - 1];
+  const startLabel = formatDateLabel(firstStop.startDate ?? "");
+  const endLabel = formatDateLabel(lastStop.endDate ?? firstStop.startDate ?? "");
+  const labels = [startLabel, endLabel].filter(Boolean);
+
+  return {
+    name: DEFAULT_TRIP_NAME,
+    startDate: firstStop.startDate ?? "",
+    endDate: lastStop.endDate ?? firstStop.startDate ?? "",
+    dateLabel: labels.length <= 1 ? labels[0] ?? "" : `${labels[0]} - ${labels[1]}`,
+  };
+}
+
+function buildBudgetSummary(summary) {
+  const categories = Object.entries(summary.byCategory).map(([category, total]) => ({
+    category,
+    total,
+    totalLabel: formatIntegerLabel(total),
+  }));
+
+  return {
+    total: summary.total,
+    spent: summary.spent,
+    available: summary.available,
+    byCategory: summary.byCategory,
+    categories,
+    ratio: summary.total > 0 ? summary.spent / summary.total : 0,
+    spentLabel: formatIntegerLabel(summary.spent),
+    totalLabel: formatIntegerLabel(summary.total),
+    availableLabel: formatIntegerLabel(summary.available),
+  };
+}
+
+function buildUpcomingEvents(activities, stops) {
+  const stopLookup = new Map(stops.map((stop) => [stop.id, stop]));
+
+  return activities
+    .filter((activity) => activity.status === "pending")
+    .map((activity) => {
+      const stop = stopLookup.get(activity.stopId);
+      return {
+        id: activity.id,
+        stopId: activity.stopId,
+        stopName: stop?.name ?? "Parada",
+        day: activity.day,
+        time: activity.time,
+        status: activity.status,
+        label: [stop?.name, activity.time].filter(Boolean).join(" · ") || activity.id,
+      };
+    })
+    .slice(0, 4);
+}
+
+function buildMemories(notes, favorites, stops, activities) {
+  const stopLookup = new Map(stops.map((stop) => [stop.id, stop]));
+  const activityLookup = new Map(activities.map((activity) => [activity.id, activity]));
+
+  const noteHighlights = notes.slice(0, 4).map((note) => {
+    const stop = note.stopId ? stopLookup.get(String(note.stopId)) : null;
+    return {
+      kind: "note",
+      id: note.id,
+      title: note.text,
+      meta: stop ? stop.name : `Día ${note.day}`,
+    };
+  });
+
+  const favoriteHighlights = favorites.slice(0, 4).map((favorite) => {
+    if (favorite.targetType === "stop") {
+      return {
+        kind: "favorite",
+        id: favorite.targetId,
+        title: stopLookup.get(favorite.targetId)?.name ?? "Parada favorita",
+        meta: "Parada marcada",
+      };
+    }
+
+    const activity = activityLookup.get(favorite.targetId);
+    const stop = activity ? stopLookup.get(activity.stopId) : null;
+    return {
+      kind: "favorite",
+      id: favorite.targetId,
+      title: stop?.name && activity?.time ? `${stop.name} · ${activity.time}` : activity?.time ?? "Actividad favorita",
+      meta: "Actividad marcada",
+    };
+  });
+
+  return {
+    notes: noteHighlights,
+    favorites: favoriteHighlights,
+    highlights: [...noteHighlights, ...favoriteHighlights].slice(0, 6),
+  };
+}
+
+function renderDashboard() {
+  const stops = normalizeStops();
+  const activities = normalizeActivities();
+  const budget = buildBudgetSummary(normalizeBudget());
+  const packing = normalizePacking();
+  const trip = buildTripSummary(stops);
+  const upcomingEvents = buildUpcomingEvents(activities, stops);
+  const memories = buildMemories(normalizeNotes(), normalizeFavorites(), stops, activities);
+
+  const upcomingMarkup = upcomingEvents.length
+    ? upcomingEvents
+        .map(
+          (event) => `
+            <li class="event-card">
+              <span class="event-card__day">Día ${event.day}</span>
+              <strong class="event-card__title">${event.label}</strong>
+              <span class="event-card__meta">${event.status === "pending" ? "Pendiente" : "Completado"}</span>
+            </li>
+          `,
+        )
+        .join("")
+    : `<li class="event-card event-card--empty">No hay próximos eventos pendientes.</li>`;
+
+  const categoryMarkup = budget.categories.length
+    ? budget.categories
+        .map(
+          (category) => `
+            <li class="stat-row">
+              <span>${category.category}</span>
+              <strong>${category.totalLabel}</strong>
+            </li>
+          `,
+        )
+        .join("")
+    : `<li class="stat-row stat-row--empty"><span>Sin gasto cargado</span><strong>0</strong></li>`;
+
+  const memoryMarkup = memories.highlights.length
+    ? memories.highlights
+        .map(
+          (item) => `
+            <article class="memory-card memory-card--${item.kind}">
+              <p class="memory-card__meta">${item.meta}</p>
+              <h3 class="memory-card__title">${item.title}</h3>
+            </article>
+          `,
+        )
+        .join("")
+    : `<p class="panel__empty">No hay recuerdos destacados todavía.</p>`;
+
+  const packingRatio = packing.total > 0 ? Math.round((packing.completed / packing.total) * 100) : 0;
+  const budgetRatio = budget.total > 0 ? Math.round((budget.spent / budget.total) * 100) : 0;
+
+  return `
+    <header class="hero panel">
+      <div class="hero__copy">
+        <p class="eyebrow">Dashboard del viaje</p>
+        <h1>${trip.name}</h1>
+        <p class="hero__dates">${trip.dateLabel}</p>
+      </div>
+      <div class="hero__metrics">
+        <div class="metric metric--budget">
+          <span class="metric__label">Presupuesto usado</span>
+          <strong class="metric__value">${budget.spentLabel}</strong>
+          <span class="metric__detail">${budgetRatio}% de ${budget.totalLabel}</span>
+        </div>
+        <div class="metric metric--packing">
+          <span class="metric__label">Equipaje listo</span>
+          <strong class="metric__value">${packing.label}</strong>
+          <span class="metric__detail">${packingRatio}% completo</span>
+        </div>
+      </div>
+    </header>
+
+    <section class="grid">
+      <section class="panel panel--events" aria-labelledby="events-title">
+        <div class="panel__header">
+          <div>
+            <p class="eyebrow">Próximos eventos</p>
+            <h2 id="events-title">Lo que viene</h2>
+          </div>
+        </div>
+        <ul class="events-list">${upcomingMarkup}</ul>
+      </section>
+
+      <section class="panel panel--budget" aria-labelledby="budget-title">
+        <div class="panel__header">
+          <div>
+            <p class="eyebrow">Presupuesto</p>
+            <h2 id="budget-title">Resumen financiero</h2>
+          </div>
+          <span class="pill">${budget.availableLabel} disponibles</span>
+        </div>
+        <div class="progress progress--budget" aria-label="Progreso del presupuesto">
+          <span style="width: ${Math.min(100, Math.max(0, budgetRatio))}%"></span>
+        </div>
+        <dl class="stats">
+          <div>
+            <dt>Total</dt>
+            <dd>${budget.totalLabel}</dd>
+          </div>
+          <div>
+            <dt>Gastado</dt>
+            <dd>${budget.spentLabel}</dd>
+          </div>
+          <div>
+            <dt>Disponible</dt>
+            <dd>${budget.availableLabel}</dd>
+          </div>
+        </dl>
+        <ul class="stat-list">${categoryMarkup}</ul>
+      </section>
+
+      <section class="panel panel--packing" aria-labelledby="packing-title">
+        <div class="panel__header">
+          <div>
+            <p class="eyebrow">Equipaje</p>
+            <h2 id="packing-title">Progreso de preparación</h2>
+          </div>
+          <span class="pill">${packing.label}</span>
+        </div>
+        <div class="progress progress--packing" aria-label="Progreso del equipaje">
+          <span style="width: ${Math.min(100, Math.max(0, packingRatio))}%"></span>
+        </div>
+        <p class="panel__copy">
+          ${packing.completed} de ${packing.total} elementos listos
+        </p>
+      </section>
+
+      <section class="panel panel--memories" aria-labelledby="memories-title">
+        <div class="panel__header">
+          <div>
+            <p class="eyebrow">Recuerdos destacados</p>
+            <h2 id="memories-title">Notas y favoritos</h2>
+          </div>
+        </div>
+        <div class="memory-grid">${memoryMarkup}</div>
+      </section>
+    </section>
+  `;
+}
+
+function render() {
+  if (typeof document === "undefined") {
+    return;
+  }
+
+  const app = document.getElementById("app");
+
+  if (!app) {
+    return;
+  }
+
+  app.innerHTML = renderDashboard();
+}
+
+function bindStorageUpdates() {
+  if (typeof window === "undefined" || typeof window.addEventListener !== "function") {
+    return;
+  }
+
+  window.addEventListener("storage", (event) => {
+    if (!event.key || Object.values(STORAGE_KEYS).includes(event.key)) {
+      render();
+    }
+  });
+}
+
+if (typeof document !== "undefined") {
+  render();
+  bindStorageUpdates();
+}
