@@ -0,0 +1,408 @@
+:root {
+  color-scheme: light;
+  --bg: #f2e8d9;
+  --bg-soft: #f8f1e8;
+  --panel: rgba(255, 252, 247, 0.9);
+  --panel-strong: #ffffff;
+  --ink: #172027;
+  --muted: #5a6772;
+  --line: rgba(23, 32, 39, 0.12);
+  --accent: #0f766e;
+  --accent-strong: #094b45;
+  --accent-warm: #b45309;
+  --accent-soft: rgba(15, 118, 110, 0.14);
+  --shadow: 0 24px 70px rgba(29, 39, 48, 0.12);
+  --radius-xl: 28px;
+  --radius-lg: 22px;
+  --radius-md: 16px;
+  --radius-sm: 12px;
+  font-family: "Avenir Next", "Segoe UI", "Trebuchet MS", system-ui, sans-serif;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html,
+body {
+  margin: 0;
+  min-height: 100%;
+}
+
+body {
+  color: var(--ink);
+  background:
+    radial-gradient(circle at top left, rgba(180, 83, 9, 0.16), transparent 36%),
+    radial-gradient(circle at top right, rgba(15, 118, 110, 0.18), transparent 32%),
+    linear-gradient(180deg, #f8f1e8 0%, var(--bg) 100%);
+}
+
+body::before {
+  content: "";
+  position: fixed;
+  inset: 0;
+  pointer-events: none;
+  background-image:
+    linear-gradient(rgba(23, 32, 39, 0.03) 1px, transparent 1px),
+    linear-gradient(90deg, rgba(23, 32, 39, 0.03) 1px, transparent 1px);
+  background-size: 34px 34px;
+  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.9), rgba(0, 0, 0, 0.15));
+}
+
+.app-shell {
+  width: min(1180px, calc(100vw - 32px));
+  margin: 0 auto;
+  padding: 24px 0 40px;
+}
+
+.panel {
+  background: var(--panel);
+  border: 1px solid var(--line);
+  border-radius: var(--radius-xl);
+  box-shadow: var(--shadow);
+  backdrop-filter: blur(12px);
+}
+
+.hero {
+  display: grid;
+  grid-template-columns: minmax(0, 1.5fr) minmax(280px, 0.9fr);
+  gap: 24px;
+  padding: 28px;
+  margin-bottom: 24px;
+  position: relative;
+  overflow: hidden;
+}
+
+.hero::after {
+  content: "";
+  position: absolute;
+  right: -60px;
+  top: -30px;
+  width: 240px;
+  height: 240px;
+  border-radius: 50%;
+  background: radial-gradient(circle, rgba(15, 118, 110, 0.18), transparent 66%);
+}
+
+.hero__copy {
+  position: relative;
+  z-index: 1;
+}
+
+.hero h1,
+.panel h2,
+.memory-card__title {
+  margin: 0;
+  line-height: 1.05;
+  letter-spacing: -0.03em;
+}
+
+.hero h1 {
+  font-family: "Georgia", "Times New Roman", serif;
+  font-size: clamp(2.8rem, 5vw, 5.4rem);
+  max-width: 10ch;
+}
+
+.hero__dates {
+  margin: 14px 0 0;
+  color: var(--muted);
+  font-size: 1.02rem;
+}
+
+.eyebrow {
+  margin: 0 0 10px;
+  color: var(--accent-strong);
+  text-transform: uppercase;
+  letter-spacing: 0.18em;
+  font-size: 0.72rem;
+  font-weight: 700;
+}
+
+.hero__metrics {
+  display: grid;
+  gap: 14px;
+  align-content: end;
+  position: relative;
+  z-index: 1;
+}
+
+.metric {
+  background: var(--panel-strong);
+  border-radius: var(--radius-lg);
+  padding: 18px;
+  border: 1px solid rgba(23, 32, 39, 0.08);
+}
+
+.metric__label,
+.metric__detail,
+.panel__copy,
+.panel__empty,
+.event-card__meta,
+.memory-card__meta {
+  color: var(--muted);
+}
+
+.metric__label {
+  display: block;
+  font-size: 0.85rem;
+  margin-bottom: 10px;
+}
+
+.metric__value {
+  display: block;
+  font-size: clamp(2rem, 4vw, 3rem);
+  line-height: 1;
+}
+
+.metric__detail {
+  display: block;
+  margin-top: 8px;
+  font-size: 0.92rem;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(12, minmax(0, 1fr));
+  gap: 20px;
+}
+
+.panel--events {
+  grid-column: span 5;
+}
+
+.panel--budget {
