  assertFiniteAmount(amount, "amount");

  const key = String(category);
  const summary = loadSummary();
  const nextCategoryTotal = (summary.byCategory[key] ?? 0) + amount;

  const nextSummary = updateAvailable({
    ...summary,
    spent: summary.spent + amount,
    byCategory: {
      ...summary.byCategory,
