diff --git a/public/styles.css b/public/styles.css
new file mode 100644
index 0000000000000000000000000000000000000000..c91b45ecbf229ad89521971a2e87359231b830a5
--- /dev/null
+++ b/public/styles.css
@@ -0,0 +1,395 @@
+:root {
+  color-scheme: dark;
+  --bg: #08111d;
+  --bg-soft: #102033;
+  --panel: rgba(248, 242, 233, 0.96);
+  --panel-strong: #f5efe5;
+  --panel-border: rgba(8, 17, 29, 0.14);
+  --text: #f8f5ef;
+  --text-soft: #c6d1dd;
+  --ink: #132033;
+  --ink-soft: #425164;
+  --accent: #f4a261;
+  --accent-2: #7bdcb5;
+  --accent-3: #8ecae6;
+  --accent-4: #ffd166;
+  --ring: #fff1b8;
+  --shadow: 0 28px 60px rgba(3, 8, 14, 0.35);
+  --radius-xl: 30px;
+  --radius-lg: 22px;
+  --radius-md: 16px;
+  --radius-sm: 12px;
+  font-family: "Avenir Next", "Segoe UI", "Trebuchet MS", system-ui, sans-serif;
+}
+
+*,
+*::before,
+*::after {
+  box-sizing: border-box;
+}
+
+html {
+  min-height: 100%;
+  scroll-behavior: smooth;
+}
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  color: var(--text);
+  background:
+    radial-gradient(circle at top left, rgba(244, 162, 97, 0.22), transparent 32%),
+    radial-gradient(circle at right 20%, rgba(123, 220, 181, 0.14), transparent 28%),
+    linear-gradient(180deg, var(--bg) 0%, var(--bg-soft) 100%);
+}
+
