+  height: 12px;
+  border-radius: 999px;
+  background: rgba(19, 32, 51, 0.12);
+}
+
+.progress-fill {
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), #f6c177);
+}
+
+.progress-fill-alt {
