diff --git a/public/styles.css b/public/styles.css
new file mode 100644
index 0000000000000000000000000000000000000000..277611b2055a2c7b57d3f655c875fac7de589011
--- /dev/null
+++ b/public/styles.css
@@ -0,0 +1,390 @@
+:root {
+  color-scheme: dark;
+  --bg: #08111d;
+  --bg-soft: #102033;
+  --panel: rgba(248, 242, 233, 0.96);
+  --panel-strong: #f5efe5;
+  --panel-border: rgba(8, 17, 29, 0.14);
+  --text: #f8f5ef;
+  --text-soft: #c6d1dd;
+  --ink: #132033;
+  --ink-soft: #425164;
+  --accent: #f4a261;
+  --accent-2: #7bdcb5;
+  --accent-3: #8ecae6;
+  --accent-4: #ffd166;
+  --ring: #fff1b8;
+  --shadow: 0 28px 60px rgba(3, 8, 14, 0.35);
+  --radius-xl: 30px;
+  --radius-lg: 22px;
+  --radius-md: 16px;
+  --radius-sm: 12px;
+  font-family: "Avenir Next", "Segoe UI", "Trebuchet MS", system-ui, sans-serif;
+}
+
+*,
+*::before,
+*::after {
+  box-sizing: border-box;
+}
+
+html {
+  min-height: 100%;
+  scroll-behavior: smooth;
+}
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  color: var(--text);
+  background:
+    radial-gradient(circle at top left, rgba(244, 162, 97, 0.22), transparent 32%),
+    radial-gradient(circle at right 20%, rgba(123, 220, 181, 0.14), transparent 28%),
+    linear-gradient(180deg, var(--bg) 0%, var(--bg-soft) 100%);
+}
+
+body::before {
+  content: "";
+  position: fixed;
+  inset: 0;
+  pointer-events: none;
+  opacity: 0.12;
+  background-image: linear-gradient(rgba(255, 255, 255, 0.22) 1px, transparent 1px),
+    linear-gradient(90deg, rgba(255, 255, 255, 0.16) 1px, transparent 1px);
+  background-size: 72px 72px;
+  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.7), transparent 95%);
+}
+
+body,
+button,
+a {
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+}
+
+a {
+  color: inherit;
+  text-decoration: none;
+}
+
+button,
+a {
+  transition:
+    transform 160ms ease,
+    background-color 160ms ease,
+    color 160ms ease,
+    border-color 160ms ease,
+    box-shadow 160ms ease;
+}
+
+button:hover,
+a:hover {
+  transform: translateY(-1px);
+}
+
+:focus-visible {
+  outline: 3px solid var(--ring);
+  outline-offset: 4px;
+}
+
+.dashboard-shell {
+  position: relative;
+  width: min(1180px, calc(100% - 32px));
+  margin: 0 auto;
+  padding: 24px 0 40px;
+}
+
+.skip-link {
+  position: absolute;
+  left: 16px;
+  top: 8px;
+  z-index: 2;
+  padding: 10px 14px;
+  border-radius: 999px;
+  background: var(--panel-strong);
+  color: var(--ink);
+  transform: translateY(-160%);
+  box-shadow: var(--shadow);
+}
+
+.skip-link:focus-visible {
+  transform: translateY(0);
+}
+
+.dashboard-canvas {
+  display: grid;
+  gap: 22px;
+}
+
+.hero-panel {
+  display: grid;
+  gap: 18px;
+  padding: 26px;
+  border-radius: var(--radius-xl);
+  background:
+    linear-gradient(145deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.02)),
+    rgba(9, 19, 31, 0.74);
+  box-shadow: var(--shadow);
+  border: 1px solid rgba(255, 255, 255, 0.09);
+  backdrop-filter: blur(16px);
+}
+
+.hero-copy {
+  display: grid;
+  gap: 10px;
+}
+
+.eyebrow,
+.section-kicker,
+.stat-label,
+.memory-tag {
+  margin: 0;
+  text-transform: uppercase;
+  letter-spacing: 0.14em;
+  font-size: 0.75rem;
+  font-weight: 700;
+}
+
+.eyebrow {
+  color: var(--accent-4);
+}
+
+.hero-title {
+  margin: 0;
+  font-family: "Iowan Old Style", "Palatino Linotype", Georgia, serif;
+  font-size: clamp(2.5rem, 6vw, 5rem);
+  line-height: 0.94;
+  letter-spacing: -0.05em;
+}
+
+.hero-date {
+  margin: 0;
+  color: var(--text-soft);
+  font-size: clamp(1rem, 2.2vw, 1.25rem);
+}
+
+.hero-meta {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 12px;
+}
+
+.stat-card {
+  --accent: var(--accent);
+  display: grid;
+  gap: 8px;
+  padding: 16px;
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.08);
+  border: 1px solid rgba(255, 255, 255, 0.08);
+}
+
+.stat-card::before {
+  content: "";
+  width: 100%;
+  height: 4px;
+  border-radius: 999px;
+  background: var(--accent);
+}
+
+.stat-label {
+  color: var(--text-soft);
+}
+
+.stat-value {
+  font-size: clamp(1.2rem, 2vw, 1.65rem);
+  letter-spacing: -0.03em;
+}
+
+.stat-helper {
+  margin: 0;
+  color: var(--text-soft);
+  font-size: 0.95rem;
+}
+
+.quick-actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+}
+
+.chip-link,
+.refresh-button {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  min-height: 42px;
+  padding: 10px 14px;
+  border-radius: 999px;
+  border: 1px solid rgba(255, 255, 255, 0.16);
+  background: rgba(255, 255, 255, 0.06);
+  color: var(--text);
+  font: inherit;
+}
+
+.refresh-button {
+  width: fit-content;
+  cursor: pointer;
+}
+
+.dashboard-grid {
+  display: grid;
+  grid-template-columns: repeat(12, minmax(0, 1fr));
+  gap: 18px;
+}
+
+.panel {
+  display: grid;
+  gap: 14px;
+}
+
+.card {
+  padding: 22px;
+  border-radius: var(--radius-lg);
+  background: var(--panel);
+  color: var(--ink);
+  border: 1px solid var(--panel-border);
+  box-shadow: var(--shadow);
+}
+
+.card-wide {
+  grid-column: span 12;
+}
+
+.dashboard-grid > .card {
+  grid-column: span 6;
+}
+
+.section-kicker {
+  color: var(--ink-soft);
+}
+
+.section-title {
+  margin: 0;
+  font-family: "Iowan Old Style", "Palatino Linotype", Georgia, serif;
+  font-size: clamp(1.35rem, 2.4vw, 1.8rem);
+  letter-spacing: -0.03em;
+}
+
+.panel-lead {
+  margin: 0;
+  color: var(--ink-soft);
+}
+
+.stack-list {
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  display: grid;
+  gap: 10px;
+}
+
+.list-item,
+.memory-card {
+  display: grid;
+  gap: 6px;
+  padding: 14px;
+  border-radius: var(--radius-sm);
+  background: rgba(19, 32, 51, 0.05);
+  border: 1px solid rgba(19, 32, 51, 0.08);
+}
+
+.item-row {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+}
+
+.item-title {
+  color: var(--ink);
+  font-size: 1rem;
+  font-weight: 700;
+}
+
+.item-meta {
+  margin: 0;
+  color: var(--ink-soft);
+  font-size: 0.95rem;
+}
+
+.item-status {
+  color: var(--ink);
+  font-weight: 600;
+}
+
+.item-pill {
+  padding: 4px 10px;
+  border-radius: 999px;
+  background: rgba(17, 24, 39, 0.08);
+  color: var(--ink);
+  font-size: 0.82rem;
+  white-space: nowrap;
+}
+
+.progress-track {
+  overflow: hidden;
+  height: 12px;
+  border-radius: 999px;
+  background: rgba(19, 32, 51, 0.12);
+}
+
+.progress-fill {
+  height: 100%;
+  border-radius: inherit;
+  background: linear-gradient(90deg, var(--accent), #f6c177);
+}
+
+.progress-fill-alt {
+  background: linear-gradient(90deg, var(--accent-2), var(--accent-3));
+}
+
+.progress-caption {
+  margin: 0;
+  font-size: 0.95rem;
+  font-weight: 600;
+  color: var(--ink-soft);
+}
+
+.memory-tag {
+  color: var(--ink-soft);
+}
+
+.empty-state {
+  padding: 14px;
+  color: var(--ink-soft);
+  border: 1px dashed rgba(19, 32, 51, 0.16);
+  border-radius: var(--radius-sm);
+}
+
+@media (max-width: 960px) {
+  .hero-meta {
+    grid-template-columns: 1fr;
+  }
+
+  .dashboard-grid > .card,
+  .dashboard-grid > section {
+    grid-column: span 12;
+  }
+}
+
+@media (max-width: 720px) {
+  .dashboard-shell {
+    width: min(100% - 20px, 1180px);
+    padding-top: 18px;
+  }
+
+  .hero-panel,
+  .card {
+    padding: 18px;
+  }
+
+  .hero-title {
+    font-size: clamp(2.1rem, 13vw, 3.5rem);
+  }
+
+  .item-row {
+    align-items: flex-start;
+    flex-direction: column;
+  }
+}
diff --git a/src/dashboard/summary.mjs b/src/dashboard/summary.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..c9e510c6a28b9d29316b071aadbf011ed6d7717f
--- /dev/null
+++ b/src/dashboard/summary.mjs
@@ -0,0 +1,260 @@
+import { listActivities } from "../itinerary/agenda/agenda.mjs";
+import { listFavorites } from "../memories/favorites/favorites.mjs";
+import { listNotes } from "../memories/notes/notes.mjs";
+import { getBudgetSummary } from "../organization/budget/budget.mjs";
+import { getPackingProgress } from "../organization/packing/packing.mjs";
+import { listStops } from "../itinerary/stops/stops.mjs";
+
+const TRIP_NAME = "Viaje en familia";
+const MONTH_LABELS = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sept", "oct", "nov", "dic"];
+const MAX_UPCOMING_EVENTS = 3;
+const MAX_HIGHLIGHTS = 4;
+
+function parseIsoDate(value) {
+  if (typeof value !== "string") {
+    return null;
+  }
+
+  const parts = value.split("-");
+
+  if (parts.length !== 3) {
+    return null;
+  }
+
+  const [yearText, monthText, dayText] = parts;
+  const year = Number(yearText);
+  const month = Number(monthText);
+  const day = Number(dayText);
+
+  if (!Number.isInteger(year) || !Number.isInteger(month) || !Number.isInteger(day)) {
+    return null;
+  }
+
+  if (month < 1 || month > 12 || day < 1 || day > 31) {
+    return null;
+  }
+
+  return { year, month, day };
+}
+
+function formatIsoDate(value) {
+  const date = parseIsoDate(value);
+
+  if (!date) {
+    return "";
+  }
+
+  return `${date.day} ${MONTH_LABELS[date.month - 1]} ${date.year}`;
+}
+
+function formatDateRange(startDate, endDate) {
+  const start = formatIsoDate(startDate);
+  const end = formatIsoDate(endDate);
+
+  if (start && end) {
+    return `${start} - ${end}`;
+  }
+
+  if (start) {
+    return start;
+  }
+
+  if (end) {
+    return end;
+  }
+
+  return "Fechas por definir";
+}
+
+function buildStopIndex(stops) {
+  return new Map(stops.map((stop, index) => [stop.id, { ...stop, index }]));
+}
+
+function buildTripSummary(stops) {
+  const firstStop = stops[0];
+  const lastStop = stops[stops.length - 1];
+
+  return {
+    name: TRIP_NAME,
+    startDate: firstStop?.startDate ?? "",
+    endDate: lastStop?.endDate ?? "",
+    dateLabel: formatDateRange(firstStop?.startDate, lastStop?.endDate),
+  };
+}
+
+function buildUpcomingEvents(stops, activities) {
+  const stopIndex = buildStopIndex(stops);
+  const rankedActivities = activities
+    .map((activity, index) => {
+      const stop = stopIndex.get(activity.stopId);
+
+      return {
+        ...activity,
+        stopName: stop?.name ?? "Parada sin nombre",
+        stopIndex: stop?.index ?? Number.POSITIVE_INFINITY,
+        activityIndex: index,
+      };
+    })
+    .sort((left, right) => {
+      if (left.stopIndex !== right.stopIndex) {
+        return left.stopIndex - right.stopIndex;
+      }
+
+      if (left.day !== right.day) {
+        return String(left.day).localeCompare(String(right.day));
+      }
+
+      if (left.time !== right.time) {
+        return String(left.time).localeCompare(String(right.time));
+      }
+
+      return left.activityIndex - right.activityIndex;
+    });
+
+  const pendingActivities = rankedActivities.filter((activity) => activity.status === "pending");
+  const visibleActivities = pendingActivities.length > 0 ? pendingActivities : rankedActivities;
+
+  return visibleActivities.slice(0, MAX_UPCOMING_EVENTS).map((activity) => ({
+    id: activity.id,
+    stopId: activity.stopId,
+    stopName: activity.stopName,
+    day: activity.day,
+    time: activity.time,
+    status: activity.status,
+    label: `${activity.time} · ${activity.stopName}`,
+  }));
+}
+
+function formatBudgetCategoryLabel(category, amount, total) {
+  const share = total > 0 ? Math.round((amount / total) * 100) : 0;
+
+  return {
+    category,
+    amount,
+    share,
+    label: `${category} · ${amount}`,
+  };
+}
+
+function buildBudgetSummary() {
+  const summary = getBudgetSummary();
+  const categories = Object.entries(summary.byCategory)
+    .sort((left, right) => {
+      const amountDifference = right[1] - left[1];
+
+      if (amountDifference !== 0) {
+        return amountDifference;
+      }
+
+      return left[0].localeCompare(right[0]);
+    })
+    .map(([category, amount]) => formatBudgetCategoryLabel(category, amount, summary.spent));
+
+  return {
+    total: summary.total,
+    spent: summary.spent,
+    available: summary.available,
+    ratio: summary.total > 0 ? summary.spent / summary.total : 0,
+    spentLabel: String(summary.spent),
+    totalLabel: String(summary.total),
+    availableLabel: String(summary.available),
+    categories,
+  };
+}
+
+function buildPackingSummary() {
+  const progress = getPackingProgress();
+
+  return {
+    completed: progress.completed,
+    total: progress.total,
+    ratio: progress.total > 0 ? progress.completed / progress.total : 0,
+    label: `${progress.completed}/${progress.total}`,
+  };
+}
+
+function describeNote(note, stopIndex) {
+  if (note.day !== undefined) {
+    return `Día ${note.day}`;
+  }
+
+  const stop = stopIndex.get(note.stopId);
+
+  return stop?.name ?? "Parada destacada";
+}
+
+function describeFavorite(favorite, stopIndex, activityIndex) {
+  if (favorite.targetType === "stop") {
+    const stop = stopIndex.get(favorite.targetId);
+
+    return stop?.name ?? "Parada destacada";
+  }
+
+  const activity = activityIndex.get(favorite.targetId);
+
+  if (!activity) {
+    return "Actividad destacada";
+  }
+
+  return `${activity.time} · ${activity.stopName}`;
+}
+
+function buildMemoriesSummary(stops, activities) {
+  const stopIndex = buildStopIndex(stops);
+  const activityIndex = new Map(
+    activities.map((activity, index) => [
+      activity.id,
+      {
+        ...activity,
+        stopName: stopIndex.get(activity.stopId)?.name ?? "Parada sin nombre",
+        index,
+      },
+    ]),
+  );
+
+  const notes = listNotes().map((note) => ({
+    id: note.id,
+    text: note.text,
+    label: describeNote(note, stopIndex),
+  }));
+
+  const favorites = listFavorites().map((favorite) => ({
+    targetType: favorite.targetType,
+    targetId: favorite.targetId,
+    label: describeFavorite(favorite, stopIndex, activityIndex),
+  }));
+
+  const highlights = [
+    ...notes.slice(0, 2).map((note) => ({
+      kind: "note",
+      id: note.id,
+      label: note.label,
+      text: note.text,
+    })),
+    ...favorites.slice(0, 2).map((favorite) => ({
+      kind: "favorite",
+      targetType: favorite.targetType,
+      targetId: favorite.targetId,
+      label: favorite.label,
+    })),
+  ].slice(0, MAX_HIGHLIGHTS);
+
+  return {
+    notes,
+    favorites,
+    highlights,
+  };
+}
+
+export function buildDashboardSummary() {
+  const stops = listStops();
+  const activities = listActivities();
+
+  return {
+    trip: buildTripSummary(stops),
+    upcomingEvents: buildUpcomingEvents(stops, activities),
+    budget: buildBudgetSummary(),
+    packing: buildPackingSummary(),
+    memories: buildMemoriesSummary(stops, activities),
+  };
+}
diff --git a/src/dashboard/summary.test.mjs b/src/dashboard/summary.test.mjs
