+  }
+
+  return `${date.day} ${MONTH_LABELS[date.month - 1]} ${date.year}`;
+}
+
+function formatDateRange(startDate, endDate) {
+  const start = formatIsoDate(startDate);
+  const end = formatIsoDate(endDate);
