+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createActivity, toggleActivityStatus } from "../itinerary/agenda/agenda.mjs";
+import { createStop } from "../itinerary/stops/stops.mjs";
+import { createNote } from "../memories/notes/notes.mjs";
+import { addExpense, setTotalBudget } from "../organization/budget/budget.mjs";
+import { addPackingItem, togglePackingItem } from "../organization/packing/packing.mjs";
+import { toggleFavorite } from "../memories/favorites/favorites.mjs";
+import { buildDashboardSummary, getDashboardSummary, TRIP_NAME } from "./summary.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("returns an empty dashboard summary when no data exists", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  assert.deepEqual(getDashboardSummary(), {
+    trip: {
+      name: TRIP_NAME,
+      dateLabel: "Fechas por definir",
+      startDate: null,
+      endDate: null,
+      stopsCount: 0,
+    },
+    upcomingEvents: [],
+    budget: {
+      total: 0,
+      spent: 0,
+      available: 0,
+      ratio: 0,
+      categories: [],
+    },
+    packing: {
+      completed: 0,
+      total: 0,
+      ratio: 0,
+    },
+    highlights: [],
+    notes: [],
+    favorites: [],
+  });
+});
+
+test("composes the dashboard from the canonical itinerary, organization, and memory states", () => {
+  globalThis.localStorage = createLocalStorage();
+
+  const firstStop = createStop({
+    name: "Mendoza",
+    startDate: "2026-09-01",
+    endDate: "2026-09-03",
+    description: "Viñedos y centro",
+  });
+  const secondStop = createStop({
+    name: "Bariloche",
+    startDate: "2026-09-04",
+    endDate: "2026-09-07",
+    description: "Lagos y montaña",
+  });
+
+  const firstActivity = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-02",
+    time: "08:30",
+  });
+  const secondActivity = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-03",
+    time: "11:00",
+  });
+  const thirdActivity = createActivity({
+    stopId: secondStop.id,
+    day: "2026-09-05",
+    time: "09:00",
+  });
+  const fourthActivity = createActivity({
+    stopId: secondStop.id,
+    day: "2026-09-06",
+    time: "17:30",
+  });
+
+  toggleActivityStatus(secondActivity.id);
+  toggleActivityStatus(fourthActivity.id);
+
+  setTotalBudget(1200);
+  addExpense("alojamiento", 500);
+  addExpense("alimentacion", 250);
+  addExpense("transporte", 150);
+
+  addPackingItem("Pasaporte");
+  const [charger] = addPackingItem({ name: "Cargador" });
+  togglePackingItem(charger.id);
+
+  createNote({ text: "Reservar restaurante para el primer día", day: 1 });
+  createNote({ text: "Mirador con mejor luz al atardecer", stopId: secondStop.id });
+  toggleFavorite("stop", firstStop.id);
+  toggleFavorite("activity", firstActivity.id);
+
+  const summary = buildDashboardSummary();
+
+  assert.equal(summary.trip.name, TRIP_NAME);
+  assert.equal(summary.trip.dateLabel, "1 sept 2026 - 7 sept 2026");
+  assert.equal(summary.trip.stopsCount, 2);
+
+  assert.deepEqual(
+    summary.upcomingEvents.map(({ id, stopName, day, time, status }) => ({
+      id,
+      stopName,
+      day,
+      time,
+      status,
+    })),
+    [
+      {
+        id: firstActivity.id,
+        stopName: "Mendoza",
+        day: "2026-09-02",
+        time: "08:30",
+        status: "pending",
+      },
+      {
+        id: thirdActivity.id,
+        stopName: "Bariloche",
+        day: "2026-09-05",
+        time: "09:00",
+        status: "pending",
+      },
+    ],
+  );
+
+  assert.deepEqual(summary.budget, {
+    total: 1200,
+    spent: 900,
+    available: 300,
+    ratio: 0.75,
+    categories: [
+      { category: "alojamiento", amount: 500, share: 56 },
+      { category: "alimentacion", amount: 250, share: 28 },
+      { category: "transporte", amount: 150, share: 17 },
+    ],
+  });
+
+  assert.deepEqual(summary.packing, {
+    completed: 1,
+    total: 2,
+    ratio: 0.5,
+  });
+
+  assert.deepEqual(summary.notes, [
+    {
+      id: summary.notes[0].id,
+      text: "Reservar restaurante para el primer día",
+      day: 1,
+      stopId: undefined,
+      label: "Día 1",
+    },
+    {
+      id: summary.notes[1].id,
+      text: "Mirador con mejor luz al atardecer",
+      day: undefined,
+      stopId: secondStop.id,
+      label: "Bariloche",
+    },
+  ]);
+
+  assert.deepEqual(summary.favorites, [
+    {
+      targetType: "stop",
+      targetId: firstStop.id,
+      label: "Mendoza",
+      kindLabel: "Parada",
+    },
+    {
+      targetType: "activity",
+      targetId: firstActivity.id,
+      label: "08:30 · Mendoza",
+      kindLabel: "Actividad",
+    },
+  ]);
+
+  assert.deepEqual(summary.highlights, [
+    {
+      kind: "note",
+      label: "Día 1",
+      text: "Reservar restaurante para el primer día",
+    },
+    {
+      kind: "note",
+      label: "Bariloche",
+      text: "Mirador con mejor luz al atardecer",
+    },
+    {
+      kind: "favorite",
+      label: "Mendoza",
+      text: "Parada",
+      targetType: "stop",
+    },
+    {
+      kind: "favorite",
+      label: "08:30 · Mendoza",
+      text: "Actividad",
+      targetType: "activity",
+    },
+  ]);
+});

