+import { getDashboardSummary } from "../src/dashboard/summary.mjs";
+import { subscribe } from "../src/storage/store.mjs";
+
+const MAX_REFRESH_KEYS = [
+  "itinerary:stops",
+  "itinerary:agenda",
+  "organization.budget",
+  "organization:packing",
+  "memories:notes",
+  "itinerary:favorites",
+];
+
+function createElement(tag, className, text) {
+  const element = document.createElement(tag);
+
+  if (className) {
+    element.className = className;
+  }
+
+  if (text !== undefined) {
+    element.textContent = text;
+  }
+
+  return element;
+}
+
+function formatPercent(value) {
+  return `${Math.max(0, Math.min(100, Math.round(value * 100)))}%`;
+}
+
+function renderList(items, emptyLabel, createItem) {
+  const list = createElement("ul", "stack-list");
+
+  if (items.length === 0) {
+    list.append(createElement("li", "empty-state", emptyLabel));
+    return list;
+  }
+
+  for (const item of items) {
+    list.append(createItem(item));
+  }
+
+  return list;
+}
+
+function createStatCard(label, value, helper, accent) {
+  const card = createElement("article", "stat-card");
+  card.style.setProperty("--accent", accent);
+  card.append(
+    createElement("p", "stat-label", label),
+    createElement("strong", "stat-value", value),
+    createElement("p", "stat-helper", helper),
+  );
+  return card;
+}
+
+function createProgressTrack(ratio, alt = false) {
+  const track = createElement("div", "progress-track");
+  const fill = createElement("div", alt ? "progress-fill progress-fill-alt" : "progress-fill");
+  fill.style.width = formatPercent(ratio);
+  track.append(fill);
+  return track;
+}
+
+function buildHero(summary) {
+  const header = createElement("header", "hero-panel");
+  const heroCopy = createElement("div", "hero-copy");
+  heroCopy.append(
+    createElement("p", "eyebrow", "Presentación del viaje"),
+    Object.assign(createElement("h1", "hero-title"), { textContent: summary.trip.name }),
+    Object.assign(createElement("p", "hero-date"), { textContent: summary.trip.dateLabel }),
+  );
+
+  const heroMeta = createElement("div", "hero-meta");
+  heroMeta.append(
+    createStatCard("Eventos", `${summary.upcomingEvents.length}`, "Próximas actividades visibles", "#f4a261"),
+    createStatCard(
+      "Presupuesto",
+      `${summary.budget.spent}/${summary.budget.total}`,
+      `Disponible ${summary.budget.available}`,
+      "#8ecae6",
+    ),
+    createStatCard(
+      "Equipaje",
+      `${summary.packing.completed}/${summary.packing.total}`,
+      "Progreso total de preparación",
+      "#7bdcb5",
+    ),
