+    }),
+  );
+  return section;
+}
+
+function renderDashboard() {
+  const summary = getDashboardSummary();
+  const app = document.getElementById("app");
+
+  if (!app) {
+    return;
+  }
+
+  app.replaceChildren();
+
+  const shell = createElement("div", "dashboard-shell");
+  const skipLink = createElement("a", "skip-link", "Saltar al contenido");
+  skipLink.href = "#dashboard-main";
+  shell.append(skipLink);
+
+  const canvas = createElement("div", "dashboard-canvas");
+  const main = createElement("main", "dashboard-grid");
+  main.id = "dashboard-main";
+
+  main.append(
+    buildEventsSection(summary),
+    buildBudgetSection(summary),
+    buildPackingSection(summary),
+    buildMemoriesSection(summary),
+    buildNotesSection(summary),
+    buildFavoritesSection(summary),
+  );
+
+  canvas.append(buildHero(summary), main);
+  shell.append(canvas);
+  app.append(shell);
+}
+
+if (typeof window !== "undefined" && window.document) {
+  renderDashboard();
+
+  for (const key of MAX_REFRESH_KEYS) {
+    subscribe(key, renderDashboard);
+  }
+}
