+function createProgressTrack(ratio, alt = false) {
+  const track = createElement("div", "progress-track");
+  const fill = createElement("div", alt ? "progress-fill progress-fill-alt" : "progress-fill");
+  fill.style.width = formatPercent(ratio);
+  track.append(fill);
+  return track;
+}
+
+function buildHero(summary) {
+  const header = createElement("header", "hero-panel");
+  const heroCopy = createElement("div", "hero-copy");
+  heroCopy.append(
+    createElement("p", "eyebrow", "Presentación del viaje"),
+    Object.assign(createElement("h1", "hero-title"), { textContent: summary.trip.name }),
+    Object.assign(createElement("p", "hero-date"), { textContent: summary.trip.dateLabel }),
+  );
+
+  const heroMeta = createElement("div", "hero-meta");
+  heroMeta.append(
+    createStatCard("Eventos", `${summary.upcomingEvents.length}`, "Próximas actividades visibles", "#f4a261"),
+    createStatCard(
+      "Presupuesto",
+      `${summary.budget.spent}/${summary.budget.total}`,
+      `Disponible ${summary.budget.available}`,
+      "#8ecae6",
+    ),
+    createStatCard(
+      "Equipaje",
+      `${summary.packing.completed}/${summary.packing.total}`,
+      "Progreso total de preparación",
+      "#7bdcb5",
+    ),
+  );
+
+  const quickActions = createElement("nav", "quick-actions");
+  quickActions.setAttribute("aria-label", "Secciones del dashboard");
+  for (const [label, href] of [
+    ["Eventos", "#events"],
+    ["Presupuesto", "#budget"],
+    ["Equipaje", "#packing"],
+    ["Recuerdos", "#memories"],
+  ]) {
+    const link = createElement("a", "chip-link", label);
+    link.href = href;
+    quickActions.append(link);
+  }
+
+  const refreshButton = createElement("button", "refresh-button", "Actualizar");
+  refreshButton.type = "button";
+  refreshButton.addEventListener("click", renderDashboard);
+
+  header.append(heroCopy, heroMeta, quickActions, refreshButton);
+  return header;
+}
+
+function buildEventsSection(summary) {
+  const section = createElement("section", "panel card");
+  section.id = "events";
+  section.append(
+    createElement("p", "section-kicker", "Agenda"),
+    createElement("h2", "section-title", "Próximos eventos"),
+    renderList(summary.upcomingEvents, "Todavía no hay eventos cargados.", (event) => {
+      const item = createElement("li", "list-item");
+      item.append(
+        createElement("strong", "item-title", event.stopName),
+        createElement("p", "item-meta", `${event.day} · ${event.time}`),
+        createElement("p", "item-meta item-status", event.status === "done" ? "Completado" : "Pendiente"),
+      );
+      return item;
+    }),
+  );
+  return section;
+}
+
+function buildBudgetSection(summary) {
+  const section = createElement("section", "panel card");
+  section.id = "budget";
+  section.append(
+    createElement("p", "section-kicker", "Presupuesto"),
+    createElement("h2", "section-title", "Resumen del gasto"),
+    createElement(
+      "p",
+      "panel-lead",
+      `Gastado ${summary.budget.spent} de ${summary.budget.total}. Disponible ${summary.budget.available}.`,
+    ),
+    createProgressTrack(summary.budget.ratio),
+    renderList(summary.budget.categories, "Todavía no hay gastos registrados.", (category) => {
+      const item = createElement("li", "list-item");
+      const row = createElement("div", "item-row");
+      row.append(
+        createElement("strong", "item-title", category.category),
+        createElement("span", "item-pill", `${category.share}%`),
+      );
+      item.append(row, createElement("p", "item-meta", `${category.amount} gastados`));
+      return item;
+    }),
+  );
+  return section;
+}
+
+function buildPackingSection(summary) {
+  const section = createElement("section", "panel card");
+  section.id = "packing";
+  section.append(
+    createElement("p", "section-kicker", "Equipaje"),
+    createElement("h2", "section-title", "Progreso de preparación"),
+    createElement(
+      "p",
+      "panel-lead",
+      `Llevas ${summary.packing.completed} de ${summary.packing.total} elementos listos.`,
+    ),
+    createProgressTrack(summary.packing.ratio, true),
+    createElement("p", "progress-caption", `${Math.round(summary.packing.ratio * 100)}% completado`),
+  );
+  return section;
+}
+
+function buildMemoriesSection(summary) {
+  const section = createElement("section", "panel card card-wide");
+  section.id = "memories";
+  section.append(
+    createElement("p", "section-kicker", "Recuerdos"),
+    createElement("h2", "section-title", "Recuerdos destacados"),
+    renderList(summary.highlights, "Aún no hay recuerdos destacados.", (highlight) => {
+      const item = createElement("li", "memory-card");
+      item.append(
+        createElement("span", "memory-tag", highlight.kind === "note" ? "Nota" : "Favorito"),
+        createElement("strong", "item-title", highlight.label),
+      );
+
+      if (highlight.text) {
+        item.append(createElement("p", "item-meta", highlight.text));
+      }
+
+      return item;
+    }),
+  );
+  return section;
+}
+
+function buildNotesSection(summary) {
+  const section = createElement("section", "panel card");
+  section.append(
+    createElement("p", "section-kicker", "Notas"),
+    createElement("h2", "section-title", "Notas del viaje"),
+    renderList(summary.notes, "No hay notas todavía.", (note) => {
+      const item = createElement("li", "list-item");
+      item.append(
+        createElement("strong", "item-title", note.text),
+        createElement("p", "item-meta", note.label),
+      );
+      return item;
+    }),
+  );
+  return section;
+}
+
+function buildFavoritesSection(summary) {
+  const section = createElement("section", "panel card");
+  section.append(
+    createElement("p", "section-kicker", "Favoritos"),
+    createElement("h2", "section-title", "Marcados como favoritos"),
+    renderList(summary.favorites, "Todavía no hay favoritos.", (favorite) => {
+      const item = createElement("li", "list-item");
+      item.append(
+        createElement("strong", "item-title", favorite.label),
+        createElement("p", "item-meta", favorite.kindLabel),
+      );
+      return item;
+    }),
+  );
+  return section;
+}
+
+function renderDashboard() {
+  const summary = getDashboardSummary();
+  const app = document.getElementById("app");
+
+  if (!app) {
+    return;
+  }
+
+  app.replaceChildren();
+
+  const shell = createElement("div", "dashboard-shell");
+  const skipLink = createElement("a", "skip-link", "Saltar al contenido");
+  skipLink.href = "#dashboard-main";
+  shell.append(skipLink);
+
+  const canvas = createElement("div", "dashboard-canvas");
+  const main = createElement("main", "dashboard-grid");
+  main.id = "dashboard-main";
+
+  main.append(
+    buildEventsSection(summary),
+    buildBudgetSection(summary),
+    buildPackingSection(summary),
+    buildMemoriesSection(summary),
+    buildNotesSection(summary),
+    buildFavoritesSection(summary),
+  );
+
+  canvas.append(buildHero(summary), main);
+  shell.append(canvas);
+  app.append(shell);
+}
+
+if (typeof window !== "undefined" && window.document) {
+  renderDashboard();
+
+  for (const key of MAX_REFRESH_KEYS) {
+    subscribe(key, renderDashboard);
+  }
+}
