+      if (highlight.text) {
+        item.append(createElement("p", "item-meta", highlight.text));
+      }
+
+      return item;
+    }),
+  );
+  return section;
+}
+
+function buildNotesSection(summary) {
+  const section = createElement("section", "panel card");
+  section.append(
+    createElement("p", "section-kicker", "Notas"),
+    createElement("h2", "section-title", "Notas del viaje"),
+    renderList(summary.notes, "No hay notas todavía.", (note) => {
+      const item = createElement("li", "list-item");
+      item.append(
+        createElement("strong", "item-title", note.text),
+        createElement("p", "item-meta", note.label),
+      );
+      return item;
+    }),
+  );
+  return section;
+}
+
+function buildFavoritesSection(summary) {
+  const section = createElement("section", "panel card");
+  section.append(
+    createElement("p", "section-kicker", "Favoritos"),
+    createElement("h2", "section-title", "Marcados como favoritos"),
+    renderList(summary.favorites, "Todavía no hay favoritos.", (favorite) => {
+      const item = createElement("li", "list-item");
+      item.append(
+        createElement("strong", "item-title", favorite.label),
+        createElement("p", "item-meta", favorite.kindLabel),
+      );
+      return item;
+    }),
+  );
+  return section;
+}
+
+function renderDashboard() {
+  const summary = getDashboardSummary();
+  const app = document.getElementById("app");
+
+  if (!app) {
+    return;
+  }
+
+  app.replaceChildren();
+
+  const shell = createElement("div", "dashboard-shell");
+  const skipLink = createElement("a", "skip-link", "Saltar al contenido");
+  skipLink.href = "#dashboard-main";
+  shell.append(skipLink);
+
+  const canvas = createElement("div", "dashboard-canvas");
+  const main = createElement("main", "dashboard-grid");
+  main.id = "dashboard-main";
+
+  main.append(
+    buildEventsSection(summary),
+    buildBudgetSection(summary),
+    buildPackingSection(summary),
+    buildMemoriesSection(summary),
+    buildNotesSection(summary),
+    buildFavoritesSection(summary),
+  );
+
+  canvas.append(buildHero(summary), main);
+  shell.append(canvas);
+  app.append(shell);
+}
+
+if (typeof window !== "undefined" && window.document) {
+  renderDashboard();
+
+  for (const key of MAX_REFRESH_KEYS) {
+    subscribe(key, renderDashboard);
+  }
+}
