+    description: "Lagos y montaña",
+  });
+
+  const firstActivity = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-02",
+    time: "08:30",
+  });
+  const secondActivity = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-03",
+    time: "11:00",
+  });
+  const thirdActivity = createActivity({
+    stopId: secondStop.id,
+    day: "2026-09-05",
+    time: "09:00",
+  });
+  const fourthActivity = createActivity({
+    stopId: secondStop.id,
+    day: "2026-09-06",
+    time: "17:30",
+  });
+
+  toggleActivityStatus(secondActivity.id);
+  toggleActivityStatus(fourthActivity.id);
+
+  setTotalBudget(1200);
+  addExpense("alojamiento", 500);
+  addExpense("alimentacion", 250);
+  addExpense("transporte", 150);
+
+  addPackingItem("Pasaporte");
+  const [charger] = addPackingItem({ name: "Cargador" });
+  togglePackingItem(charger.id);
+
+  createNote({ text: "Reservar restaurante para el primer día", day: 1 });
+  createNote({ text: "Mirador con mejor luz al atardecer", stopId: secondStop.id });
+  toggleFavorite("stop", firstStop.id);
