+      stopId: secondStop.id,
+      label: "Bariloche",
+    },
+  ]);
+
+  assert.deepEqual(summary.favorites, [
+    {
+      targetType: "stop",
+      targetId: firstStop.id,
+      label: "Mendoza",
+      kindLabel: "Parada",
+    },
+    {
+      targetType: "activity",
+      targetId: firstActivity.id,
+      label: "08:30 · Mendoza",
+      kindLabel: "Actividad",
+    },
+  ]);
+
+  assert.deepEqual(summary.highlights, [
+    {
+      kind: "note",
+      label: "Día 1",
+      text: "Reservar restaurante para el primer día",
+    },
+    {
+      kind: "note",
+      label: "Bariloche",
+      text: "Mirador con mejor luz al atardecer",
+    },
+    {
+      kind: "favorite",
+      label: "Mendoza",
+      text: "Parada",
+      targetType: "stop",
+    },
+    {
+      kind: "favorite",
+      label: "08:30 · Mendoza",
+      text: "Actividad",
+      targetType: "activity",
+    },
+  ]);
+});

