+    dateLabel: formatDateRange(firstStop?.startDate, lastStop?.endDate),
+    startDate: firstStop?.startDate ?? null,
+    endDate: lastStop?.endDate ?? null,
+    stopsCount: stops.length,
+  };
+}
+
+function buildUpcomingEvents(stops, activities) {
+  const stopIndex = buildStopIndex(stops);
+  const rankedActivities = activities
+    .map((activity, index) => {
+      const stop = stopIndex.get(activity.stopId);
+
+      return {
+        ...activity,
+        stopName: stop?.name ?? "Parada sin nombre",
+        stopIndex: stop?.index ?? Number.POSITIVE_INFINITY,
+        activityIndex: index,
+      };
+    })
+    .sort((left, right) => {
+      if (left.stopIndex !== right.stopIndex) {
+        return left.stopIndex - right.stopIndex;
+      }
+
+      if (left.day !== right.day) {
+        return String(left.day).localeCompare(String(right.day));
+      }
+
+      if (left.time !== right.time) {
+        return String(left.time).localeCompare(String(right.time));
+      }
+
+      return left.activityIndex - right.activityIndex;
+    });
+
+  const pendingActivities = rankedActivities.filter((activity) => activity.status === "pending");
+  const visibleActivities = pendingActivities.length > 0 ? pendingActivities : rankedActivities;
+
+  return visibleActivities.slice(0, MAX_UPCOMING_EVENTS).map((activity) => ({
+    id: activity.id,
+    stopId: activity.stopId,
+    stopName: activity.stopName,
+    day: activity.day,
+    time: activity.time,
+    status: activity.status,
+  }));
+}
+
+function buildBudgetSummaryView(summary) {
+  const categories = Object.entries(summary.byCategory ?? {})
+    .sort((left, right) => right[1] - left[1] || left[0].localeCompare(right[0]))
+    .map(([category, amount]) => ({
+      category,
+      amount,
+      share: summary.spent > 0 ? Math.round((amount / summary.spent) * 100) : 0,
+    }));
+
+  return {
+    total: Number(summary.total) || 0,
+    spent: Number(summary.spent) || 0,
+    available: Number(summary.available) || 0,
+    ratio: Number(summary.total) > 0 ? Number(summary.spent) / Number(summary.total) : 0,
+    categories,
+  };
+}
+
+function buildPackingSummaryView(progress) {
+  const completed = Number(progress.completed) || 0;
+  const total = Number(progress.total) || 0;
+
+  return {
+    completed,
+    total,
+    ratio: total > 0 ? completed / total : 0,
+  };
+}
+
+function buildNotesView(stops, notes) {
+  const stopIndex = buildStopIndex(stops);
+
+  return notes.map((note) => ({
+    id: note.id,
+    text: note.text,
+    day: note.day,
+    stopId: note.stopId,
+    label:
+      note.day !== undefined
+        ? `Día ${note.day}`
+        : stopIndex.get(note.stopId)?.name ?? "Parada destacada",
+  }));
+}
+
+function buildFavoritesView(stops, activities, favorites) {
+  const stopIndex = buildStopIndex(stops);
+  const activityIndex = buildActivityIndex(stops, activities);
+
+  return favorites.map((favorite) => ({
+    targetType: favorite.targetType,
+    targetId: favorite.targetId,
+    label:
+      favorite.targetType === "stop"
+        ? stopIndex.get(favorite.targetId)?.name ?? "Parada destacada"
+        : `${activityIndex.get(favorite.targetId)?.time ?? "Sin hora"} · ${
+            activityIndex.get(favorite.targetId)?.stopName ?? "Actividad destacada"
+          }`,
+    kindLabel: favorite.targetType === "stop" ? "Parada" : "Actividad",
+  }));
+}
+
+function buildHighlights(notes, favorites) {
+  const noteHighlights = notes.slice(0, 2).map((note) => ({
+    kind: "note",
+    label: note.label,
+    text: note.text,
+  }));
+
+  const favoriteHighlights = favorites.slice(0, 2).map((favorite) => ({
+    kind: "favorite",
+    label: favorite.label,
+    text: favorite.kindLabel,
+    targetType: favorite.targetType,
+  }));
+
+  return [...noteHighlights, ...favoriteHighlights].slice(0, MAX_HIGHLIGHTS);
+}
+
+export function getDashboardSummary() {
+  const stops = listStops();
+  const activities = listActivities();
+  const notes = buildNotesView(stops, listNotes());
+  const favorites = buildFavoritesView(stops, activities, listFavorites());
+
+  return {
+    trip: buildTripSummary(stops),
+    upcomingEvents: buildUpcomingEvents(stops, activities),
+    budget: buildBudgetSummaryView(getBudgetSummary()),
+    packing: buildPackingSummaryView(getPackingProgress()),
+    highlights: buildHighlights(notes, favorites),
+    notes,
+    favorites,
+  };
+}
+
+export function buildDashboardSummary() {
+  return getDashboardSummary();
+}
