+  filterPackingItems,
+  getPackingProgress,
+  togglePackingItem,
+} from "../../src/organization/packing/packing.mjs";
+
+function createLocalStorage() {
+  const data = new Map();
+
+  return {
+    getItem(key) {
+      return data.has(key) ? data.get(key) : null;
+    },
+    setItem(key, value) {
+      data.set(key, String(value));
+    },
+    removeItem(key) {
+      data.delete(key);
+    },
+    clear() {
+      data.clear();
+    },
+    key(index) {
+      return Array.from(data.keys())[index] ?? null;
+    },
+    get length() {
+      return data.size;
+    },
+    data,
+  };
+}
+
+test("integrates the trip dashboard across route, organization, and memories with localStorage persistence", () => {
+  const localStorage = createLocalStorage();
+  globalThis.localStorage = localStorage;
+
+  const buenosAires = createStop({
+    name: "Buenos Aires",
+    startDate: "2026-09-01",
+    endDate: "2026-09-03",
+    description: "Inicio urbano y logística",
+  });
+  const cordoba = createStop({
+    name: "Córdoba",
+    startDate: "2026-09-04",
+    endDate: "2026-09-05",
+    description: "Escala central de descanso",
+  });
+  const mendoza = createStop({
+    name: "Mendoza",
+    startDate: "2026-08-28",
+    endDate: "2026-08-30",
+    description: "Cierre entre viñedos",
+  });
+
+  assert.deepEqual(reorderStops(mendoza.id, 0).map((stop) => stop.name), [
+    "Mendoza",
+    "Buenos Aires",
+    "Córdoba",
+  ]);
