+  const mendozaActivity = createActivity({
+    stopId: mendoza.id,
+    day: "2026-08-28",
+    time: "08:00",
+  });
+  const buenosAiresActivity = createActivity({
+    stopId: buenosAires.id,
+    day: "2026-09-02",
+    time: "10:30",
+  });
+  const cordobaActivity = createActivity({
+    stopId: cordoba.id,
+    day: "2026-09-05",
+    time: "15:15",
+  });
+
