+  const dayNote = createNote({
+    text: "Reservar cena de bienvenida",
+    day: 1,
+  });
+  const stopNote = createNote({
+    text: "Confirmar paseo en bodegas",
+    stopId: mendoza.id,
+  });
+
+  const stopFavorite = toggleFavorite("stop", mendoza.id);
+  const activityFavorite = toggleFavorite("activity", cordobaActivity.id);
