+      name: "Viaje en familia",
+      startDate: "2026-08-28",
+      endDate: "2026-09-05",
+      dateLabel: "28 ago 2026 - 5 sept 2026",
+    },
+    upcomingEvents: [
+      {
+        id: buenosAiresActivity.id,
+        stopId: buenosAires.id,
+        stopName: "Buenos Aires",
+        day: "2026-09-02",
+        time: "10:30",
+        status: "pending",
+        label: "10:30 · Buenos Aires",
+      },
+      {
+        id: cordobaActivity.id,
+        stopId: cordoba.id,
+        stopName: "Córdoba",
+        day: "2026-09-05",
+        time: "15:15",
+        status: "pending",
+        label: "15:15 · Córdoba",
+      },
+    ],
+    budget: {
+      total: 2000,
+      spent: 1500,
+      available: 500,
+      ratio: 0.75,
+      spentLabel: "1500",
+      totalLabel: "2000",
+      availableLabel: "500",
+      categories: [
+        {
+          category: "alojamiento",
+          amount: 900,
+          share: 60,
+          label: "alojamiento · 900",
+        },
+        {
+          category: "transporte",
+          amount: 350,
+          share: 23,
+          label: "transporte · 350",
+        },
+        {
+          category: "comidas",
+          amount: 250,
+          share: 17,
+          label: "comidas · 250",
+        },
+      ],
+    },
+    packing: {
+      completed: 1,
+      total: 2,
+      ratio: 0.5,
+      label: "1/2",
+    },
+    memories: {
+      notes: [
+        {
+          id: dayNote.id,
+          text: "Reservar cena de bienvenida",
+          label: "Día 1",
+        },
+        {
+          id: stopNote.id,
+          text: "Confirmar paseo en bodegas",
+          label: "Mendoza",
+        },
+      ],
+      favorites: [
+        {
+          targetType: "stop",
+          targetId: stopFavorite.targetId,
+          label: "Mendoza",
+        },
+        {
+          targetType: "activity",
+          targetId: activityFavorite.targetId,
+          label: "15:15 · Córdoba",
+        },
+      ],
+      highlights: [
+        {
+          kind: "note",
+          id: dayNote.id,
+          label: "Día 1",
+          text: "Reservar cena de bienvenida",
+        },
+        {
+          kind: "note",
+          id: stopNote.id,
+          label: "Mendoza",
+          text: "Confirmar paseo en bodegas",
+        },
+        {
+          kind: "favorite",
+          targetType: "stop",
+          targetId: stopFavorite.targetId,
+          label: "Mendoza",
+        },
+        {
+          kind: "favorite",
+          targetType: "activity",
+          targetId: activityFavorite.targetId,
+          label: "15:15 · Córdoba",
+        },
+      ],
+    },
+  });
+
+  assert.deepEqual(JSON.parse(localStorage.data.get("itinerary:stops")), [
+    {
+      id: mendoza.id,
+      name: "Mendoza",
+      startDate: "2026-08-28",
+      endDate: "2026-08-30",
+      description: "Cierre entre viñedos",
+    },
+    {
+      id: buenosAires.id,
+      name: "Buenos Aires",
+      startDate: "2026-09-01",
+      endDate: "2026-09-03",
+      description: "Inicio urbano y logística",
+    },
+    {
+      id: cordoba.id,
+      name: "Córdoba",
+      startDate: "2026-09-04",
+      endDate: "2026-09-05",
+      description: "Escala central de descanso",
+    },
+  ]);
+  assert.equal(
+    localStorage.data.get("itinerary:agenda"),
